test "tmpfs references: every descriptor owns one open_count, so close never treats a second descriptor as a reason to skip the release" {
    const src = kt.vfs_source;
    // hasSharedRef must not list tmpfs: that made the second open of a file (and statx's internal open) leak the entry.
    const start = std.mem.indexOf(u8, src, "fn hasSharedRef(") orelse return error.TestUnexpectedResult;
    const end = std.mem.indexOfPos(u8, src, start, "/// Close a file descriptor.") orelse return error.TestUnexpectedResult;
    try std.testing.expect(std.mem.indexOf(u8, src[start..end], ".tmpfs_file =>") == null);
    // dup2 and dupFdAtLeast retain the entry, since each copy is closed with its own release.
    const dup2 = std.mem.indexOf(u8, src, "pub fn dup2(self: *FdTable") orelse return error.TestUnexpectedResult;
    const dup2_end = std.mem.indexOfPos(u8, src, dup2, "/// Duplicate into the lowest available slot") orelse return error.TestUnexpectedResult;
    try std.testing.expect(std.mem.indexOf(u8, src[dup2..dup2_end], "tmpfsRetain(") != null);
    const dupat = std.mem.indexOf(u8, src, "pub fn dupFdAtLeast(") orelse return error.TestUnexpectedResult;
    const dupat_end = std.mem.indexOfPos(u8, src, dupat, "\n};\n") orelse return error.TestUnexpectedResult;
    try std.testing.expect(std.mem.indexOf(u8, src[dupat..dupat_end], "tmpfsRetain(") != null);
}

test "getrandom argument rules: flags, zero length, pointer errors, per-call cap" {
    const rp = kt.random_policy;
    // Valid flags and every combination of them except RANDOM|INSECURE.
    for ([_]u64{ 0, 1, 2, 4, 1 | 2, 1 | 4 }) |f| {
        try std.testing.expectEqual(@as(u64, 16), rp.check(16, f).ok);
    }
    try std.testing.expectEqual(@as(i64, -22), rp.check(16, 2 | 4).err);
    try std.testing.expectEqual(@as(i64, -22), rp.check(16, 1 | 2 | 4).err);
    // Unknown bits are EINVAL, even next to valid ones.
    try std.testing.expectEqual(@as(i64, -22), rp.check(16, 8).err);
    try std.testing.expectEqual(@as(i64, -22), rp.check(16, 0x1234).err);
    try std.testing.expectEqual(@as(i64, -22), rp.check(16, 1 | 0x10).err);
    try std.testing.expectEqual(@as(i64, -22), rp.check(0, 8).err);
    // Lengths: 257 and 4096 and 1 MiB are served in full (the old limit was 256); only a very large request is capped.
    try std.testing.expectEqual(@as(u64, 0), rp.check(0, 0).ok);
    try std.testing.expectEqual(@as(u64, 257), rp.check(257, 0).ok);
    try std.testing.expectEqual(@as(u64, 4096), rp.check(4096, 0).ok);
    try std.testing.expectEqual(@as(u64, 1 << 20), rp.check(1 << 20, 0).ok);
    try std.testing.expectEqual(rp.MAX_PER_CALL, rp.check(rp.MAX_PER_CALL + 1, 0).ok);
    try std.testing.expectEqual(rp.MAX_PER_CALL, rp.check(std.math.maxInt(u64), 0).ok);
    // The pointer: a zero-length request never touches it; otherwise a bad pointer is EFAULT.
    try std.testing.expectEqual(@as(i64, 0), rp.pointerErrno(0, false));
    try std.testing.expectEqual(@as(i64, 0), rp.pointerErrno(0, true));
    try std.testing.expectEqual(@as(i64, 0), rp.pointerErrno(8, true));
    try std.testing.expectEqual(@as(i64, -14), rp.pointerErrno(8, false));
}

test "fork retains a tmpfs entry once per descriptor, the same count close releases" {
    const src = kt.vfs_source;
    const start = std.mem.indexOf(u8, src, "pub fn retainSharedResources(") orelse return error.TestUnexpectedResult;
    const end = std.mem.indexOfPos(u8, src, start, "/// Block read callback for readahead") orelse return error.TestUnexpectedResult;
    const body = src[start..end];
    // tmpfs must not be de-duplicated per table (the "seen" scan), because close releases one reference per descriptor.
    try std.testing.expect(std.mem.indexOf(u8, body, ".tmpfs_file => seen") == null);
    // ...and the retain for tmpfs is taken for every descriptor, so it must sit before the "seen" skip.
    const retain = std.mem.indexOf(u8, body, "if (desc.fd_type == .tmpfs_file) {") orelse return error.TestUnexpectedResult;
    const skip = std.mem.indexOf(u8, body, "if (seen) continue;") orelse return error.TestUnexpectedResult;
    try std.testing.expect(retain < skip);
    try std.testing.expect(std.mem.indexOf(u8, body[retain..skip], "tmpfsRetain(") != null);
    // FAT32 is per-descriptor too (the same rule): its retain also sits before the scan.
    const fat_retain = std.mem.indexOf(u8, body, "if (desc.fd_type == .fat32_file) {") orelse return error.TestUnexpectedResult;
    try std.testing.expect(fat_retain < skip);
    try std.testing.expect(std.mem.indexOf(u8, body[fat_retain..skip], "retainFile(") != null);
    try std.testing.expect(std.mem.indexOf(u8, body, ".fat32_file => seen") == null);
    // SCM_RIGHTS: a passed tmpfs descriptor keeps its own reference as well.
    const per_fd = std.mem.indexOf(u8, src, "fn refIsPerFd(") orelse return error.TestUnexpectedResult;
    try std.testing.expect(std.mem.indexOf(u8, src[per_fd .. per_fd + 200], ".tmpfs_file") != null);
}

