    try std.testing.expectEqual(@as(?i32, 1), p.getValue(none, p.SOL_IP, p.IP_MULTICAST_LOOP));
    try std.testing.expectEqual(@as(?i32, 1), p.getValue(none, p.SOL_IP, p.IP_MULTICAST_ALL));
    try std.testing.expectEqual(@as(?i32, 0), p.getValue(none, p.SOL_IP, p.IP_MULTICAST_IF));
    const set4 = struct {
        fn f(cur: p.IpOpts, name: u64, v: i32) p.SetResult {
            var b: [4]u8 = undefined;
            std.mem.writeInt(i32, &b, v, .little);
            return p.applySet(cur, p.SOL_IP, name, &b);
        }
    }.f;
    try std.testing.expectEqual(@as(u8, 7), set4(none, p.IP_MULTICAST_TTL, 7).ok.mc4_ttl);
    try std.testing.expectEqual(@as(u8, 0), set4(none, p.IP_MULTICAST_TTL, 0).ok.mc4_ttl);
    try std.testing.expectEqual(@as(u8, 1), set4(.{ .mc4_ttl = 9 }, p.IP_MULTICAST_TTL, -1).ok.mc4_ttl);
    try std.testing.expectEqual(@as(i64, -22), set4(none, p.IP_MULTICAST_TTL, 256).err);
    try std.testing.expectEqual(@as(i64, -22), set4(none, p.IP_MULTICAST_TTL, -2).err);
    // One byte is accepted for the IPv4 multicast options.
    try std.testing.expectEqual(@as(u8, 9), p.applySet(none, p.SOL_IP, p.IP_MULTICAST_TTL, &.{9}).ok.mc4_ttl);
    try std.testing.expect(!p.applySet(none, p.SOL_IP, p.IP_MULTICAST_LOOP, &.{0}).ok.mc4_loop);
    try std.testing.expect(set4(.{ .mc4_loop = false }, p.IP_MULTICAST_LOOP, 5).ok.mc4_loop);
    try std.testing.expectEqual(@as(i64, -22), set4(none, p.IP_MULTICAST_ALL, 3).err);
    try std.testing.expect(!set4(none, p.IP_MULTICAST_ALL, 0).ok.mc4_all);
    const our = [4]u8{ 10, 0, 2, 15 };
    try std.testing.expectEqual(@as(?u8, 2), p.ifaceOf4(our, 0, true, our));
    try std.testing.expectEqual(@as(?u8, null), p.ifaceOf4(our, 0, false, our));
    try std.testing.expectEqual(@as(?u8, 1), p.ifaceOf4(.{ 127, 0, 0, 1 }, 0, true, our));
    try std.testing.expectEqual(@as(?u8, null), p.ifaceOf4(.{ 10, 9, 9, 9 }, 0, true, our));
    try std.testing.expectEqual(@as(?u8, 2), p.ifaceOf4(.{ 0, 0, 0, 0 }, 2, true, our));
    try std.testing.expectEqual(@as(?u8, null), p.ifaceOf4(.{ 0, 0, 0, 0 }, 99, true, our));
    const ifa = p.setMulticastIf4(none, &our, true, our).ok;
    try std.testing.expectEqual(our, ifa.mc4_addr);
    try std.testing.expectEqual(@as(?i32, @bitCast(our)), p.getValue(ifa, p.SOL_IP, p.IP_MULTICAST_IF));
    try std.testing.expectEqual(@as(i64, -99), p.setMulticastIf4(none, &.{ 10, 9, 9, 9 }, true, our).err);
    try std.testing.expectEqual(@as(i64, -22), p.setMulticastIf4(none, our[0..3], true, our).err);
    try std.testing.expectEqual(@as(u8, 0), p.setMulticastIf4(ifa, &.{ 0, 0, 0, 0 }, true, our).ok.mc4_index);
    try std.testing.expectEqual(@as(?i64, -22), p.streamSetErrno4(p.IP_MULTICAST_TTL));
    try std.testing.expectEqual(@as(?i64, -22), p.streamSetErrno4(p.IP_MULTICAST_IF));
    try std.testing.expectEqual(@as(?i64, -71), p.streamSetErrno4(p.IP_ADD_MEMBERSHIP));
    try std.testing.expectEqual(@as(?i64, null), p.streamSetErrno4(p.IP_MULTICAST_LOOP));
    var hdr: [20]u8 = @splat(0);
    hdr[0] = 0x45;
    hdr[8] = 64;
    p.setTtl4(&hdr, 1, kt.ipv4.checksum);
    try std.testing.expectEqual(@as(u8, 1), hdr[8]);
    try std.testing.expectEqual(@as(u16, 0), kt.ipv4.checksum(&hdr, 20));

    const g1 = [4]u8{ 239, 1, 1, 1 };
    const g2 = [4]u8{ 239, 1, 1, 2 };
    const any = [4]u8{ 0, 0, 0, 0 };
    var mem: m.Membership4 = .{};
    try std.testing.expectEqual(m.EINVAL, m.join4(&mem, .{ 10, 0, 0, 1 }, any, 0, true, our));
    try std.testing.expectEqual(m.ENODEV, m.join4(&mem, g1, .{ 10, 9, 9, 9 }, 0, true, our));
    try std.testing.expectEqual(m.ENODEV, m.join4(&mem, g1, any, 0, false, our));
    try std.testing.expectEqual(@as(i64, 0), m.join4(&mem, g1, any, 0, true, our));
    try std.testing.expectEqual(m.EADDRINUSE, m.join4(&mem, g1, any, 0, true, our));
    try std.testing.expectEqual(m.EADDRINUSE, m.join4(&mem, g1, our, 0, true, our));
    try std.testing.expectEqual(m.EADDRINUSE, m.join4(&mem, g1, any, 2, true, our));
    try std.testing.expectEqual(m.ENODEV, m.join4(&mem, g1, any, 99, true, our));
    try std.testing.expectEqual(@as(i64, 0), m.join4(&mem, g1, .{ 127, 0, 0, 1 }, 0, true, our));
    try std.testing.expectEqual(m.EADDRNOTAVAIL, m.drop4(&mem, g2, any, 0, true, our));
    try std.testing.expectEqual(m.EADDRNOTAVAIL, m.drop4(&mem, .{ 10, 0, 0, 1 }, any, 0, true, our));
    try std.testing.expectEqual(@as(i64, 0), m.drop4(&mem, g1, any, 0, true, our));
    try std.testing.expect(m.joined4(&mem, g1, null));
    try std.testing.expectEqual(m.EADDRNOTAVAIL, m.drop4(&mem, g1, any, 0, true, our));
    try std.testing.expectEqual(@as(i64, 0), m.drop4(&mem, g1, any, 1, true, our));
    try std.testing.expect(!m.joined4(&mem, g1, null));
    try std.testing.expectEqual(m.ENODEV, m.drop4(&mem, g1, any, 0, false, our));
    var full: m.Membership4 = .{};
    for (0..m.MAX_GROUPS4) |i| try std.testing.expectEqual(@as(i64, 0), m.join4(&full, .{ 239, 2, 0, @intCast(i + 1) }, any, 0, true, our));
    try std.testing.expectEqual(m.ENOBUFS, m.join4(&full, g1, any, 0, true, our));
    var src16: [16]u8 = @splat(0);
    src16[0] = 10;
    src16[3] = 7;
    const src = [4]u8{ 10, 0, 0, 7 };
    try std.testing.expect(m.socketMatches4(any, g1, 0, @splat(0), src, 5));
    try std.testing.expect(m.socketMatches4(g1, g1, 0, @splat(0), src, 5));
    try std.testing.expect(!m.socketMatches4(g2, g1, 0, @splat(0), src, 5));
    try std.testing.expect(!m.socketMatches4(any, g1, 6, src16, src, 5));
    try std.testing.expect(m.socketMatches4(any, g1, 5, src16, src, 5));
    try std.testing.expect(m.socketAccepts4(&mem, true, g1, 2) and !m.socketAccepts4(&mem, false, g1, 2));
    try std.testing.expect(m.alwaysJoined4(.{ 224, 0, 0, 1 }) and !m.alwaysJoined4(g1));
    try std.testing.expect(m.isMulticast4(.{ 224, 0, 0, 0 }) and m.isMulticast4(.{ 239, 255, 255, 255 }) and !m.isMulticast4(.{ 240, 0, 0, 0 }));
    try std.testing.expectEqual([6]u8{ 0x01, 0x00, 0x5e, 0x01, 0x01, 0x01 }, m.multicastMac4(.{ 239, 129, 1, 1 }));
    // A socket bound to a group sends from the interface's address, or 127.0.0.1 towards loopback.
    const tp = kt.tcp_port_policy;
    try std.testing.expectEqual(our, tp.sourceAddr(g1, .{ 10, 0, 2, 2 }, our));
    try std.testing.expectEqual([4]u8{ 127, 0, 0, 1 }, tp.sourceAddr(g1, .{ 127, 0, 0, 1 }, our));

    const us = kt.udp_source;
    try std.testing.expect(std.mem.indexOf(u8, us, "    if (mcast.isMulticast4(dst_ip)) {\n        enqueueMcast4(hdr.dst_port, ip16, hdr.src_port, dst_ip, data[8..][0..actual_payload], ifindex, meta);\n        return;\n    }\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, us, "        if (!mcast.alwaysJoined4(group) and !hostJoined4Locked(group, ifindex)) return;\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, us, "            if (!mcast.socketAccepts4(&port_mc4[i], port_opts[i].ip.mc4_all, group, ifindex)) continue;\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, us, "    if (group) ip_opt_policy.setTtl4(send_pkt[14..][0..20], ttl_ov orelse opts4.mc4_ttl, ipv4.checksum);\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, us, "    if (group and !via_lo and opts4.mc4_loop and (mcast.alwaysJoined4(dst_ip) or hostJoined4(dst_ip, out_if))) _ = lo.sendPacketOn(&send_pkt, frame_len, out_if);\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, us, "    else if (group)\n        mcast.multicastMac4(dst_ip)\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, us, "    port_mc4[ni] = port_mc4[oi];\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, us, "            port_mc4[i] = port_mc4[num_ports];\n") != null);
    const so = kt.socket_opt_source;
    try std.testing.expect(std.mem.indexOf(u8, so, "(optname == ipo.IP_ADD_MEMBERSHIP or optname == ipo.IP_DROP_MEMBERSHIP)) return setMembership4(ref, optname, optval_ptr, optlen);") != null);
    try std.testing.expect(std.mem.indexOf(u8, so, "    if (ref == .tcp) return -71;\n    // do_ip_setsockopt checks optlen against struct ip_mreq for every socket type first.\n    if (optlen < 8) return -22;\n    if (ref != .udp and ref != .raw) return -92;\n") != null);
}

test "multicast outgoing interface: IP_MULTICAST_IF lo sends out lo only, IPV6_MULTICAST_IF lo is ENETUNREACH, IPv4 group delivery checks the arrival interface, each sharing socket sends with its own options (hello363)" {
    const m = kt.mcast_policy;
    const g1 = [4]u8{ 239, 1, 3, 1 };
    const any = [4]u8{ 0, 0, 0, 0 };
    const our = [4]u8{ 10, 0, 2, 15 };
    // A membership counts only on the interface it was joined on (ip_mc_sf_allow), unless MULTICAST_ALL.
    var mem: m.Membership4 = .{};
    try std.testing.expectEqual(@as(i64, 0), m.join4(&mem, g1, any, 1, true, our));
    try std.testing.expect(m.joined4(&mem, g1, 1) and !m.joined4(&mem, g1, 2) and m.joined4(&mem, g1, null));
    try std.testing.expect(m.socketAccepts4(&mem, false, g1, 1));
    try std.testing.expect(!m.socketAccepts4(&mem, false, g1, 2));
    try std.testing.expect(m.socketAccepts4(&mem, true, g1, 2));
    // The IP_MULTICAST_IF address is the source of a group datagram from an unbound socket.
    try std.testing.expectEqual(@as(?[4]u8, .{ 127, 0, 0, 1 }), m.multicastSource4(true, any, .{ 127, 0, 0, 1 }));
    try std.testing.expectEqual(@as(?[4]u8, null), m.multicastSource4(false, any, .{ 127, 0, 0, 1 }));
    try std.testing.expectEqual(@as(?[4]u8, null), m.multicastSource4(true, our, .{ 127, 0, 0, 1 }));
    try std.testing.expectEqual(@as(?[4]u8, null), m.multicastSource4(true, any, any));
    // IPv6 has no multicast route on lo.
    const bp = kt.bind_addr_policy;
    var g6: [16]u8 = @splat(0);
    g6[0] = 0xff;
    g6[1] = 0x0e;
    g6[15] = 0x31;
    var lo6: [16]u8 = @splat(0);
    lo6[15] = 1;
    try std.testing.expectEqual(bp.ENETUNREACH, bp.routeErrno6(g6, bp.sendOif6(g6, 0, 0, 1)));
    try std.testing.expectEqual(@as(i64, 0), bp.routeErrno6(g6, bp.sendOif6(g6, 0, 0, 0)));
    try std.testing.expectEqual(@as(i64, 0), bp.routeErrno6(g6, bp.sendOif6(g6, 0, 0, 2)));
    try std.testing.expectEqual(@as(i64, 0), bp.routeErrno6(lo6, bp.sendOif6(lo6, 0, 0, 1)));
    // A loopback frame remembers the interface it arrives on.
    var q = lo.LoopbackQueue.init();
    try std.testing.expect(q.enqueueOn(&.{ 1, 2, 3 }, 2));
    try std.testing.expect(q.enqueue(&.{ 4, 5 }));
    var out: [8]u8 = undefined;
    var ifx: u8 = 0;
    try std.testing.expectEqual(@as(u32, 3), q.dequeueFrom(&out, &ifx));
    try std.testing.expectEqual(@as(u8, 2), ifx);
    try std.testing.expectEqual(@as(u32, 2), q.dequeueFrom(&out, &ifx));
    try std.testing.expectEqual(lo.IFINDEX, ifx);

    const us = kt.udp_source;
    try std.testing.expect(std.mem.indexOf(u8, us, "    const via_lo = loopback or (group and out_if == lo.IFINDEX);\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, us, "    const ok = if (via_lo) lo.sendNowMeta(&send_pkt, frame_len, skbMeta(src_key, skb_ov)) or lo.dropIsLoss(frame_len) else nic.sendPacket(&send_pkt, frame_len);\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, us, "    const our_ip = if (mcast.multicastSource4(group, bound, opts4.mc4_addr)) |a| a else ") != null);
    // Options come from the sending socket's own registry key, not from whichever socket first holds the port.
    try std.testing.expect(std.mem.indexOf(u8, us, "    var opts4: ip_opt_policy.IpOpts = if (getPortOpts(src_key)) |po| po.ip else .{};\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, us, "    const opts: ip_opt_policy.IpOpts = if (getPortOpts(src_key)) |po| po.ip else .{};\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, us, "getPortOpts(src_port)") == null);
    const ss = kt.socket_syscall_source;
    try std.testing.expectEqual(@as(usize, 2), std.mem.count(u8, ss, "const src_key = "));
    try std.testing.expectEqual(@as(usize, 2), std.mem.count(u8, ss, "const unreach6 = bind_addr_policy.routeErrno6(dst6, oif6);\n"));
    try std.testing.expect(std.mem.indexOf(u8, kt.net_mod_source, "udp.handlePacketMetaInfo(info.src_ip, info.dst_ip, data + payload_start, info.payload_len, meta4);") != null);
    try std.testing.expect(std.mem.indexOf(u8, kt.lo_source, "net_mod.handleRxPacketMeta(&buf, n, ifindex, meta);") != null);
}

test "IPv6 bind ties a link-scoped socket to its sin6_scope_id interface: separate ports per interface, receive filter, getsockname scope, no stream multicast bind (hello364)" {
    const bp = kt.bind_addr_policy;
    var ll: [16]u8 = @splat(0);
    ll[0] = 0xfe;
    ll[1] = 0x80;
    ll[15] = 1;
    var ff01: [16]u8 = @splat(0);
    ff01[0] = 0xff;
    ff01[1] = 0x01;
    ff01[15] = 1;
    var ff02: [16]u8 = @splat(0);
    ff02[0] = 0xff;
    ff02[1] = 0x02;
    ff02[15] = 1;
    var glob: [16]u8 = @splat(0);
    glob[0] = 0x20;
    glob[1] = 0x01;
    glob[15] = 7;
    var ff05: [16]u8 = @splat(0);
    ff05[0] = 0xff;
    ff05[1] = 0x05;
    ff05[15] = 1;
    // Interface-local multicast needs a scope too (__ipv6_addr_needs_scope_id).
    try std.testing.expect(bp.needsScope6(ff01) and bp.needsScope6(ff02) and bp.needsScope6(ll));
    try std.testing.expect(!bp.needsScope6(glob) and !bp.needsScope6(ff05));
    // sk_bound_dev_if comes from sin6_scope_id only for an address that needs a scope.
    try std.testing.expectEqual(@as(u8, 1), bp.boundDev6(ff02, 1));
    try std.testing.expectEqual(@as(u8, 2), bp.boundDev6(ll, 2));
    try std.testing.expectEqual(@as(u8, 0), bp.boundDev6(glob, 2));
    try std.testing.expectEqual(@as(u8, 0), bp.boundDev6(ff05, 1));
    // inet_bind_conflict: different interfaces never conflict; an unbound one conflicts with any.
    try std.testing.expect(!bp.boundDevsConflict(1, 2));
    try std.testing.expect(bp.boundDevsConflict(1, 1));
    try std.testing.expect(bp.boundDevsConflict(0, 2) and bp.boundDevsConflict(1, 0) and bp.boundDevsConflict(0, 0));
    // __inet6_bind: a stream socket cannot bind a multicast address.
    try std.testing.expectEqual(bp.EINVAL, bp.streamBindErrno6(ff02));
    try std.testing.expectEqual(bp.EINVAL, bp.streamBindErrno6(ff05));
    try std.testing.expectEqual(@as(i64, 0), bp.streamBindErrno6(glob));
    try std.testing.expectEqual(@as(i64, 0), bp.streamBindErrno6(ll));
    // __udp_v6_is_mcast_sock: a socket tied to an interface takes only datagrams that arrived on it.
    const m = kt.mcast_policy;
    const wild: [16]u8 = @splat(0);
    try std.testing.expect(m.socketMatches(ff02, ff02, 0, wild, glob, 5, 1, 1));
    try std.testing.expect(!m.socketMatches(ff02, ff02, 0, wild, glob, 5, 1, 2));
    try std.testing.expect(!m.socketMatches(ff02, ff02, 0, wild, glob, 5, 2, 1));
    try std.testing.expect(m.socketMatches(ff02, ff02, 0, wild, glob, 5, 0, 1));
    // getsockname reports the interface the socket is tied to.
    const sa = kt.sockaddr_util;
    try std.testing.expectEqual(@as(u32, 1), sa.boundScope6(ff02, 1));
    // inet6_getname: ipv6_iface_scope_id(addr, sk_bound_dev_if), so a socket on no interface names scope 0 (hello366 U4).
    try std.testing.expectEqual(@as(u32, 0), sa.boundScope6(ff02, 0));
    try std.testing.expectEqual(@as(u32, 0), sa.boundScope6(glob, 0));
    try std.testing.expectEqual(@as(u32, 0), sa.boundScope6(glob, 1));

    const us = kt.udp_source;
    try std.testing.expect(std.mem.indexOf(u8, us, "if (port_v6[j] and port_v6[oi] and !@import(\"bind_addr_policy.zig\").boundDevsConflict(dev6, port_dev6[j])) continue;") != null);
    try std.testing.expect(std.mem.indexOf(u8, us, "    port_dev6[ni] = dev6;\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, us, "            port_dev6[i] = port_dev6[num_ports];\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, us, "    port_dev6[idx] = 0;\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, us, "port_peer_ip[i], src_ip, src_port, port_dev6[i], ifindex)) continue;") != null);
    const ss = kt.socket_syscall_source;
    try std.testing.expect(std.mem.indexOf(u8, ss, "parsed.addr, bind_addr_policy.boundDev6(parsed.addr, parsed.scope_id));") != null);
    const stream_at = std.mem.indexOf(u8, ss, "const stream_rc = bind_addr_policy.streamBindErrno6(parsed.addr);").?;
    try std.testing.expect(stream_at < std.mem.indexOfPos(u8, ss, stream_at, "inet6ScopeErrno(parsed.addr").?);
    try std.testing.expect(std.mem.indexOf(u8, ss, "sa.writeInet6(&sa_buf, name_port, our6, sa.boundScope6(our6, udp.boundDev6(desc.udpKey())))") != null);
    try std.testing.expect(std.mem.indexOf(u8, kt.net_mod_source, "udp.handlePacketV6Info(info6.src_ip, info6.dst_ip, data + up_start, up_len, .{ .ifindex = ifindex,") != null);
}

test "IPv6 send interface: sendto's sin6_scope_id, the bound interface and IPV6_MULTICAST_IF pick it, lo carries only ::1; connect ties a scoped peer's interface (hello365)" {
    const bp = kt.bind_addr_policy;
    var ff02: [16]u8 = @splat(0);
    ff02[0] = 0xff;
    ff02[1] = 0x02;
    ff02[15] = 1;
    var ll: [16]u8 = @splat(0);
    ll[0] = 0xfe;
    ll[1] = 0x80;
    ll[15] = 1;
    var ff0e: [16]u8 = @splat(0);
    ff0e[0] = 0xff;
    ff0e[1] = 0x0e;
    ff0e[15] = 1;
    var uni: [16]u8 = @splat(0);
    uni[0] = 0x20;
    uni[1] = 0x01;
    uni[15] = 9;
    var lo6: [16]u8 = @splat(0);
    lo6[15] = 1;
    // udpv6_sendmsg: the scope of an address that needs one, else sk_bound_dev_if, else mcast_oif for a group.
    try std.testing.expectEqual(@as(u8, 2), bp.sendOif6(ff02, 2, 1, 1));
    try std.testing.expectEqual(@as(u8, 1), bp.sendOif6(ff02, 0, 1, 2));
    try std.testing.expectEqual(@as(u8, 1), bp.sendOif6(ff0e, 9, 0, 1));
    try std.testing.expectEqual(@as(u8, 0), bp.sendOif6(ff0e, 9, 0, 0));
    try std.testing.expectEqual(@as(u8, 0), bp.sendOif6(uni, 9, 0, 1));
    try std.testing.expectEqual(@as(u8, 255), bp.sendOif6(ff02, 1000, 0, 0));
    // lo has a route only to ::1; an unknown interface none.
    try std.testing.expectEqual(@as(i64, 0), bp.routeErrno6(ff02, 0));
    try std.testing.expectEqual(@as(i64, 0), bp.routeErrno6(ff02, 2));
    try std.testing.expectEqual(bp.ENETUNREACH, bp.routeErrno6(ff02, 1));
    try std.testing.expectEqual(bp.ENETUNREACH, bp.routeErrno6(ll, 1));
    try std.testing.expectEqual(@as(i64, 0), bp.routeErrno6(lo6, 1));
    try std.testing.expectEqual(bp.ENETUNREACH, bp.routeErrno6(ff02, 9));
    // __ip6_datagram_connect.
    try std.testing.expectEqual(bp.Connect6{ .dev = 0, .err = bp.EINVAL }, bp.connectDev6(ff02, 0, 0, 0));
    try std.testing.expectEqual(bp.Connect6{ .dev = 0, .err = bp.EINVAL }, bp.connectDev6(ll, 0, 0, 0));
    try std.testing.expectEqual(bp.Connect6{ .dev = 2, .err = 0 }, bp.connectDev6(ff02, 2, 0, 0));
    try std.testing.expectEqual(bp.Connect6{ .dev = 9, .err = bp.ENETUNREACH }, bp.connectDev6(ff02, 9, 0, 0));
    try std.testing.expectEqual(bp.Connect6{ .dev = 9, .err = bp.EINVAL }, bp.connectDev6(ff02, 2, 9, 0));
    try std.testing.expectEqual(bp.Connect6{ .dev = 1, .err = bp.ENETUNREACH }, bp.connectDev6(ff02, 1, 1, 0));
    try std.testing.expectEqual(bp.Connect6{ .dev = 2, .err = 0 }, bp.connectDev6(ff02, 0, 0, 2));
    try std.testing.expectEqual(bp.Connect6{ .dev = 1, .err = bp.ENETUNREACH }, bp.connectDev6(ff02, 0, 0, 1));
    try std.testing.expectEqual(bp.Connect6{ .dev = 0, .err = bp.ENETUNREACH }, bp.connectDev6(ff0e, 0, 0, 1));
    try std.testing.expectEqual(bp.Connect6{ .dev = 0, .err = 0 }, bp.connectDev6(uni, 9, 0, 1));
    try std.testing.expectEqual(bp.Connect6{ .dev = 1, .err = bp.ENETUNREACH }, bp.connectDev6(uni, 0, 1, 0));

    // A link-scoped group is sent from the link-local address even when a global one exists (the source getsockname reports too).
    const v6 = kt.ipv6;
    try std.testing.expect(v6.wantsLinkLocalSource(ff02) and v6.wantsLinkLocalSource(ll));
    var ff01: [16]u8 = ff02;
    ff01[1] = 0x01;
    var ff05: [16]u8 = ff02;
    ff05[1] = 0x05;
    try std.testing.expect(v6.wantsLinkLocalSource(ff01));
    try std.testing.expect(!v6.wantsLinkLocalSource(ff05) and !v6.wantsLinkLocalSource(ff0e) and !v6.wantsLinkLocalSource(uni));
    try std.testing.expect(std.mem.indexOf(u8, kt.ndp_source, "    if (ipv6.wantsLinkLocalSource(dst)) return ll;\n") != null);

    const us = kt.udp_source;
    try std.testing.expect(std.mem.indexOf(u8, us, "    port_dev6[i] = r.dev;\n    return r.err;\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, us, "return @import(\"bind_addr_policy.zig\").sendOif6(dst, scope_id, port_dev6[i], port_opts[i].ip.mc_if);") != null);
    try std.testing.expect(std.mem.indexOf(u8, us, "    const out_if6 = mcast.outInterface(oif);\n") != null);
    const ss = kt.socket_syscall_source;
    try std.testing.expectEqual(@as(usize, 2), std.mem.count(u8, ss, "scope6 = parsed.scope_id;"));
    try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, ss, "const oif6 = udp.sendOif6(src_key, dst6, scope6);"));
    try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, ss, "var oif6 = udp.sendOif6(src_key, dst6, scope6);"));
    const conn_at = std.mem.indexOf(u8, ss, "const dev_rc = udp.connectDev6(t.fd_table.fds[fd].udpKey(), parsed.addr, parsed.scope_id);").?;
    try std.testing.expect(conn_at < std.mem.indexOfPos(u8, ss, conn_at, "t.fd_table.fds[fd].udp_connected = true;").?);
}

