test "ping sockets: SOCK_DGRAM/IPPROTO_ICMP sends echo requests under the socket's ident and gets the matching replies (hello371)" {
    const pp = kt.ping_policy;
    // ping_common_sendmsg: a full ICMP header, and only an echo request (or an extended echo request) with code 0.
    try std.testing.expectEqual(@as(i64, 0), pp.sendErrno(8, 8, 0));
    try std.testing.expectEqual(@as(i64, 0), pp.sendErrno(64, 8, 0));
    try std.testing.expectEqual(@as(i64, 0), pp.sendErrno(8, 42, 0));
    try std.testing.expectEqual(@as(i64, -22), pp.sendErrno(7, 8, 0));
    try std.testing.expectEqual(@as(i64, -22), pp.sendErrno(16, 0, 0));
    try std.testing.expectEqual(@as(i64, -22), pp.sendErrno(16, 8, 1));
    try std.testing.expectEqual(@as(i64, -90), pp.sendErrno(pp.MAX_MESSAGE4 + 1, 8, 0));
    // ping_v4_sendmsg puts the socket's ident in the id field and checksums the whole message.
    var msg = [_]u8{ 8, 0, 0x12, 0x34, 0xaa, 0xbb, 0, 7, 'p', 'a', 'y', 'l', 'o', 'a', 'd', '!' };
    pp.finishRequest(&msg, 0x1234);
    try std.testing.expectEqual(@as(u8, 8), msg[0]);
    try std.testing.expectEqual(@as(u8, 0x12), msg[4]);
    try std.testing.expectEqual(@as(u8, 0x34), msg[5]);
    try std.testing.expectEqual(@as(u8, 7), msg[7]);
    try std.testing.expectEqual(@as(u16, 0), kt.ipv4.checksum(&msg, msg.len));
    // Odd length too.
    var odd = [_]u8{ 8, 0, 0, 0, 0, 0, 0, 1, 'x' };
    pp.finishRequest(&odd, 1);
    try std.testing.expectEqual(@as(u16, 0), kt.ipv4.checksum(&odd, odd.len));
    // ping_rcv takes echo replies (and extended ones) for the socket whose ident is the reply's id.
    const reply = [_]u8{ 0, 0, 0, 0, 0x12, 0x34, 0, 7 };
    try std.testing.expectEqual(@as(?u16, 0x1234), pp.replyIdent(&reply));
    try std.testing.expectEqual(@as(?u16, null), pp.replyIdent(&[_]u8{ 8, 0, 0, 0, 0x12, 0x34, 0, 7 }));
    try std.testing.expectEqual(@as(?u16, null), pp.replyIdent(&[_]u8{ 0, 1, 0, 0, 0x12, 0x34, 0, 7 }));
    try std.testing.expectEqual(@as(?u16, 0x0102), pp.replyIdent(&[_]u8{ 43, 0, 0, 0, 1, 2, 0, 0 }));
    try std.testing.expectEqual(@as(?u16, null), pp.replyIdent(&[_]u8{ 0, 0, 0, 0, 1, 2, 0 }));
    // A socket bound to an address takes only replies sent to it.
    try std.testing.expect(pp.takesReply(.{ 0, 0, 0, 0 }, .{ 127, 0, 0, 1 }));
    try std.testing.expect(pp.takesReply(.{ 127, 0, 0, 1 }, .{ 127, 0, 0, 1 }));
    try std.testing.expect(!pp.takesReply(.{ 127, 0, 0, 1 }, .{ 10, 0, 2, 15 }));
    // ping_check_bind_addr and ping_bind.
    try std.testing.expect(pp.bindAddrAllowed(.{ 0, 0, 0, 0 }, false));
    try std.testing.expect(pp.bindAddrAllowed(.{ 127, 0, 0, 1 }, true));
    try std.testing.expect(!pp.bindAddrAllowed(.{ 10, 0, 2, 99 }, false));
    try std.testing.expect(!pp.bindAddrAllowed(.{ 224, 0, 0, 1 }, true));
    try std.testing.expect(!pp.bindAddrAllowed(.{ 255, 255, 255, 255 }, true));
    try std.testing.expectEqual(@as(i64, 0), pp.bindErrno(false));
    try std.testing.expectEqual(@as(i64, -22), pp.bindErrno(true));
    // SO_REUSEADDR is on for a new ping socket (INET_PROTOSW_REUSE), so two default ping sockets share an ident.
    try std.testing.expect(pp.mayShareIdent(1, 1));
    try std.testing.expect(!pp.mayShareIdent(0, 1));
    try std.testing.expect(!pp.mayShareIdent(1, 0));

    // socket(): AF_INET datagram sockets accept IPPROTO_ICMP; a stream socket does not.
    const np = kt.namespace_policy;
    try std.testing.expect(np.socketArgs(2, 2, 1) == .ok);
    try std.testing.expectEqual(@as(i64, -93), np.socketArgs(2, 1, 1).err);
    try std.testing.expectEqual(@as(i64, -93), np.socketArgs(10, 2, 1).err);

    // Wiring: echo replies are offered to ping sockets before anything else, and UDP never sees a ping slot.
    try std.testing.expect(std.mem.indexOf(u8, kt.icmp_source, "if (pp.replyIdent(data[0..len])) |ident| {\n        if (len > 0xffff or ipv4.checksum(data, @intCast(len)) != 0) return;\n        @import(\"udp.zig\").deliverPing(ident, src_ip, dst_ip, data[0..len], m);") == null and std.mem.indexOf(u8, kt.icmp_source, "if (pp.replyIdent(data[0..len])) |ident| {\n        if (len > 0xffff or ipv4.checksum(data, @intCast(len)) != 0) return;\n        var m = meta;\n        m.spec_dst = .{ 0, 0, 0, 0 };\n        @import(\"udp.zig\").deliverPing(ident, src_ip, dst_ip, data[0..len], m);") != null);
    const us = kt.udp_source;
    try std.testing.expect(std.mem.indexOf(u8, us, "pub fn deliverPing(ident: u16, src_ip: [4]u8, dst_ip: [4]u8, msg: []const u8, meta: ip_cmsg_policy.RecvInfo) void {") != null);
    // notifyError, enqueue and both group paths skip ping slots; rebind only conflicts with UDP slots; the port count is per space.
    // A socket with no local port yet is skipped the same way (hello385).
    try std.testing.expectEqual(@as(usize, 3), std.mem.count(u8, us, "if (port_ping[i] or !port_named[i]) continue;"));
    try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, us, "if (port_ping[i] or port_v6[i] or !port_named[i]) continue;"));
    try std.testing.expect(std.mem.indexOf(u8, us, "        if (port_ping[j]) continue;\n        if (portNumber(ports[j]) != new_port) continue;\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, us, "        used[nu] = @intCast((ports[j] >> 16) & 0x7fff);\n        nu += 1;\n        if (!port_named[j]) continue;\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, us, "        if (port_ping[i] != ping) continue;\n        if (!port_named[i]) continue;\n        if (portNumber(ports[i]) == port) n += 1;") != null);
    try std.testing.expect(std.mem.indexOf(u8, us, "const key = PING_KEY | ident;") != null);
    try std.testing.expect(std.mem.indexOf(u8, us, "        port_opts[i].flags |= @import(\"udp_port_policy.zig\").REUSEADDR_FLAG;\n        return key;") != null);
    // getsockopt(SO_PROTOCOL) on a ping socket is IPPROTO_ICMP.
    try std.testing.expectEqual(@as(u32, 1), kt.sockopt_policy.identity(.ping, false).protocol);
    try std.testing.expectEqual(@as(u32, 2), kt.sockopt_policy.identity(.ping, false).sock_type);
}

test "net.ipv4.ping_group_range: who may create a ping socket, read and written as two gids (hello373)" {
    const pp = kt.ping_policy;
    // Default: nobody (1 0), shown as the overflow gid twice (from_kgid_munged of an empty range).
    var r = pp.GroupRange{};
    var buf: [32]u8 = undefined;
    try std.testing.expectEqualStrings("65534\t65534\n", buf[0..pp.formatRange(r, &buf)]);
    try std.testing.expect(!pp.groupAllowed(r, 0, &.{}));
    // proc_doulongvec_minmax: up to two decimal values separated by blanks; a missing high value keeps the old one.
    try std.testing.expectEqual(@as(i64, 3), pp.writeRange(&r, "0 0"));
    try std.testing.expectEqualStrings("0\t0\n", buf[0..pp.formatRange(r, &buf)]);
    try std.testing.expect(pp.groupAllowed(r, 0, &.{}));
    try std.testing.expect(!pp.groupAllowed(r, 5, &.{}));
    try std.testing.expect(pp.groupAllowed(r, 5, &.{ 3, 0 }));
    try std.testing.expectEqual(@as(i64, 4), pp.writeRange(&r, "0 0\n"));
    try std.testing.expectEqual(@as(i64, 7), pp.writeRange(&r, "  2\t9  "));
    try std.testing.expectEqualStrings("2\t9\n", buf[0..pp.formatRange(r, &buf)]);
    try std.testing.expect(pp.groupAllowed(r, 9, &.{}) and pp.groupAllowed(r, 2, &.{}) and !pp.groupAllowed(r, 10, &.{}));
    try std.testing.expectEqual(@as(i64, 1), pp.writeRange(&r, "7"));
    try std.testing.expectEqualStrings("7\t9\n", buf[0..pp.formatRange(r, &buf)]);
    // Three values: the first two are taken (proc_doulongvec stops at maxlen) and the bytes up to the third are consumed.
    try std.testing.expectEqual(@as(i64, 4), pp.writeRange(&r, "1 2 3"));
    try std.testing.expectEqualStrings("1\t2\n", buf[0..pp.formatRange(r, &buf)]);
    // An inverted range means nobody again.
    try std.testing.expectEqual(@as(i64, 3), pp.writeRange(&r, "5 3"));
    try std.testing.expectEqualStrings("65534\t65534\n", buf[0..pp.formatRange(r, &buf)]);
    try std.testing.expect(!pp.groupAllowed(r, 4, &.{}));
    // Junk, a negative value or one past GID_T_MAX (2^32 - 2) is EINVAL and changes nothing.
    _ = pp.writeRange(&r, "1 1");
    try std.testing.expectEqual(@as(i64, -22), pp.writeRange(&r, "x"));
    try std.testing.expectEqual(@as(i64, -22), pp.writeRange(&r, "-1 3"));
    try std.testing.expectEqual(@as(i64, -22), pp.writeRange(&r, "0 4294967295"));
    try std.testing.expectEqual(@as(i64, 12), pp.writeRange(&r, "0 4294967294"));
    try std.testing.expectEqual(@as(i64, -22), pp.writeRange(&r, "1 4294967295"));
    try std.testing.expectEqualStrings("0\t4294967294\n", buf[0..pp.formatRange(r, &buf)]);
    try std.testing.expectEqual(@as(i64, 0), pp.writeRange(&r, ""));
    try std.testing.expectEqualStrings("0\t4294967294\n", buf[0..pp.formatRange(r, &buf)]);

    // The ping tests run as root (the file is root-writable only) holding CAP_SETUID/CAP_SETGID for hello373's children and
    // CAP_NET_RAW for its raw-socket check.
    const cp = kt.capability_profile;
    for ([_][]const u8{ "hello371", "hello372", "hello373" }) |name| {
        const prof = cp.profileForLaunch(name, true, false);
        try std.testing.expectEqual(@as(u32, 0), prof.uid);
        try std.testing.expectEqual(@as(u32, 0), prof.gid);
        try std.testing.expect(prof.caps.cap_setuid and prof.caps.cap_setgid and prof.caps.cap_net_raw);
    }
    // socket() asks the policy with the caller's egid and supplementary groups; the procfs file is mode 0644 owned by root, which a
    // holder of CAP_NET_ADMIN may also write (net_ctl_permissions, hello383).
    const ss = kt.socket_syscall_source;
    try std.testing.expect(std.mem.indexOf(u8, ss, "if (!udp.pingGroupAllowed(t.egid, t.groups[0..t.ngroups])) return -13; // EACCES") != null);
    try std.testing.expect(std.mem.indexOf(u8, kt.vfs_source, "str.eql(rest, \"sys/net/ipv4/ping_group_range\")") != null);
    // Opened for writing, the descriptor is writable (writeInner refuses any other with EBADF before the procfs write is reached).
    try std.testing.expect(std.mem.indexOf(u8, kt.vfs_source, "                .writable = is_writable and (procfs.isSysctl(pfile) or pfile == .pid_comm),\n") != null);
}

test "IPv6 ping sockets: SOCK_DGRAM/IPPROTO_ICMPV6 share the ident table but only take replies of their own family (hello374)" {
    const pp = kt.ping_policy;
    // ping_common_sendmsg for AF_INET6: an ICMPv6 echo request (128) or extended one (160) with code 0; the IPv4 type 8 is EINVAL.
    try std.testing.expectEqual(@as(i64, 0), pp.sendErrno6(8, 128, 0));
    try std.testing.expectEqual(@as(i64, 0), pp.sendErrno6(16, 160, 0));
    try std.testing.expectEqual(@as(i64, -22), pp.sendErrno6(7, 128, 0));
    try std.testing.expectEqual(@as(i64, -22), pp.sendErrno6(16, 8, 0));
    try std.testing.expectEqual(@as(i64, -22), pp.sendErrno6(16, 128, 1));
    try std.testing.expectEqual(@as(i64, -90), pp.sendErrno6(pp.MAX_MESSAGE4 + 1, 128, 0));
    var m = [_]u8{ 128, 0, 0, 0, 0, 0, 0, 9 };
    pp.setIdent(&m, 0x1374);
    try std.testing.expectEqual(@as(u8, 0x13), m[4]);
    try std.testing.expectEqual(@as(u8, 0x74), m[5]);
    // Echo replies (129) and extended ones (161) with code 0 go to the socket whose ident is the id.
    try std.testing.expectEqual(@as(?u16, 0x0102), pp.replyIdent6(&[_]u8{ 129, 0, 0, 0, 1, 2, 0, 0 }));
    try std.testing.expectEqual(@as(?u16, 0x0102), pp.replyIdent6(&[_]u8{ 161, 0, 0, 0, 1, 2, 0, 0 }));
    try std.testing.expectEqual(@as(?u16, null), pp.replyIdent6(&[_]u8{ 128, 0, 0, 0, 1, 2, 0, 0 }));
    try std.testing.expectEqual(@as(?u16, null), pp.replyIdent6(&[_]u8{ 0, 0, 0, 0, 1, 2, 0, 0 }));
    try std.testing.expectEqual(@as(?u16, null), pp.replyIdent6(&[_]u8{ 129, 1, 0, 0, 1, 2, 0, 0 }));
    try std.testing.expectEqual(@as(?u16, null), pp.replyIdent6(&[_]u8{ 129, 0, 0, 0, 1, 2, 0 }));
    // ping_check_bind_addr for AF_INET6.
    const any: [16]u8 = @splat(0);
    var lo1: [16]u8 = @splat(0);
    lo1[15] = 1;
    var grp: [16]u8 = @splat(0);
    grp[0] = 0xff;
    grp[1] = 2;
    grp[15] = 1;
    var ll: [16]u8 = @splat(0);
    ll[0] = 0xfe;
    ll[1] = 0x80;
    ll[15] = 5;
    try std.testing.expectEqual(@as(i64, 0), pp.bindAddrErrno6(any, false, 0, false, false));
    try std.testing.expectEqual(@as(i64, 0), pp.bindAddrErrno6(lo1, false, 0, false, true));
    try std.testing.expectEqual(@as(i64, -22), pp.bindAddrErrno6(grp, true, 0, false, false));
    try std.testing.expectEqual(@as(i64, -99), pp.bindAddrErrno6(lo1, false, 0, false, false));
    try std.testing.expectEqual(@as(i64, -22), pp.bindAddrErrno6(ll, true, 0, false, true));
    try std.testing.expectEqual(@as(i64, -19), pp.bindAddrErrno6(ll, true, 7, false, true));
    try std.testing.expectEqual(@as(i64, 0), pp.bindAddrErrno6(ll, true, 2, true, true));
    try std.testing.expectEqual(@as(i64, -97), pp.family6Errno(2));
    try std.testing.expectEqual(@as(i64, 0), pp.family6Errno(10));
    // ping_v6_sendmsg: a link-scoped destination needs an interface; a v4-mapped one is EINVAL.
    try std.testing.expectEqual(@as(i64, -22), pp.destErrno6(ll, true, 0));
    try std.testing.expectEqual(@as(i64, 0), pp.destErrno6(ll, true, 2));
    var mapped: [16]u8 = @splat(0);
    mapped[10] = 0xff;
    mapped[11] = 0xff;
    mapped[12] = 127;
    mapped[15] = 1;
    try std.testing.expectEqual(@as(i64, -22), pp.destErrno6(mapped, false, 0));
    try std.testing.expectEqual(@as(i64, 0), pp.destErrno6(lo1, false, 0));
    // ping_lookup: the last hashed holder whose bound address is :: or the reply's destination.
    const two = [_]pp.Holder6{ .{ .seq = 1, .bound = any }, .{ .seq = 2, .bound = any } };
    try std.testing.expectEqual(@as(?usize, 1), pp.pickReceiver6(&two, lo1));
    const spec = [_]pp.Holder6{ .{ .seq = 1, .bound = any }, .{ .seq = 2, .bound = ll } };
    try std.testing.expectEqual(@as(?usize, 0), pp.pickReceiver6(&spec, lo1));
    try std.testing.expectEqual(@as(?usize, 1), pp.pickReceiver6(&spec, ll));
    try std.testing.expectEqual(@as(?usize, null), pp.pickReceiver6(&[_]pp.Holder6{.{ .seq = 1, .bound = ll }}, lo1));

    // socket(): AF_INET6 datagram sockets accept IPPROTO_ICMPV6; AF_INET does not, nor does AF_INET6 take IPPROTO_ICMP.
    const np = kt.namespace_policy;
    try std.testing.expect(np.socketArgs(10, 2, 58) == .ok);
    try std.testing.expectEqual(@as(i64, -93), np.socketArgs(2, 2, 58).err);
    try std.testing.expectEqual(@as(i64, -93), np.socketArgs(10, 2, 1).err);
    try std.testing.expectEqual(@as(i64, -93), np.socketArgs(10, 1, 58).err);
    // SO_PROTOCOL 58 and SO_DOMAIN 10 on an IPv6 ping socket.
    try std.testing.expectEqual(@as(u32, 58), kt.sockopt_policy.identity(.ping, true).protocol);
    try std.testing.expectEqual(@as(u32, 10), kt.sockopt_policy.identity(.ping, true).domain);
    try std.testing.expectEqual(@as(u32, 1), kt.sockopt_policy.identity(.ping, false).protocol);

    // Wiring: echo replies reach deliverPing6 before the ICMPv6 dispatch; each family's delivery skips the other family's sockets.
    try std.testing.expect(std.mem.indexOf(u8, kt.icmpv6_source, "if (@import(\"ping_policy.zig\").replyIdent6(data[0..len])) |ident| {\n        @import(\"udp.zig\").deliverPing6(ident, src_ip, dst_ip, data[0..len], meta6);") != null);
    const us = kt.udp_source;
    try std.testing.expect(std.mem.indexOf(u8, us, "if (!port_ping[k] or port_v6[k] or portNumber(ports[k]) != ident) continue;") != null);
    try std.testing.expect(std.mem.indexOf(u8, us, "if (!port_ping[k] or !port_v6[k] or portNumber(ports[k]) != ident) continue;") != null);
    try std.testing.expect(std.mem.indexOf(u8, us, "const i = newSlotLocked(key, is_v6, uid);") != null);
    // A requester on this host is answered over lo (an echo request to ::1 used to need an NDP entry and was never answered).
    try std.testing.expect(std.mem.indexOf(u8, kt.icmpv6_source, "const via_lo = netif.isLoopbackV6(requester_ip) or ndp.isOwnAddress(requester_ip, our_mac);") != null);
    // getpeername on any ping socket is ENOTCONN (it has no peer port).
    const ss = kt.socket_syscall_source;
    try std.testing.expect(std.mem.indexOf(u8, ss, "if (!desc.udp_connected or desc.udp_ping) return ENOTCONN;") != null);
    try std.testing.expect(std.mem.indexOf(u8, ss, "const is_ping = parsed.sock_type == 2 and ((domain == 2 and protocol == 1) or (domain == 10 and protocol == 58));") != null);
    const prof = kt.capability_profile.profileForLaunch("hello374", true, false);
    try std.testing.expectEqual(@as(u32, 0), prof.uid);
}

test "ping sockets sharing an ident: the reply goes to the one hashed last that takes it (hello372)" {
    const pp = kt.ping_policy;
    const any = [4]u8{ 0, 0, 0, 0 };
    const lo1 = [4]u8{ 127, 0, 0, 1 };
    const lo2 = [4]u8{ 127, 0, 0, 2 };
    const own = [4]u8{ 10, 0, 2, 15 };
    // ping_lookup walks the hash chain from its head, and sk_add_node_rcu puts a newly hashed socket at the head: the last one wins.
    const two = [_]pp.Holder{ .{ .seq = 1, .bound = any }, .{ .seq = 2, .bound = any } };
    try std.testing.expectEqual(@as(?usize, 1), pp.pickReceiver(&two, lo1, lo1));
    // A later socket bound to another address does not take it, so the earlier one does.
    const spec = [_]pp.Holder{ .{ .seq = 1, .bound = any }, .{ .seq = 2, .bound = own } };
    try std.testing.expectEqual(@as(?usize, 0), pp.pickReceiver(&spec, lo1, lo1));
    // Bound to the reply's destination: taken whatever the order.
    const later_spec = [_]pp.Holder{ .{ .seq = 5, .bound = any }, .{ .seq = 9, .bound = lo1 } };
    try std.testing.expectEqual(@as(?usize, 1), pp.pickReceiver(&later_spec, lo1, lo1));
    const earlier_spec = [_]pp.Holder{ .{ .seq = 9, .bound = any }, .{ .seq = 5, .bound = lo1 } };
    try std.testing.expectEqual(@as(?usize, 0), pp.pickReceiver(&earlier_spec, lo1, lo1));
    // ping_lookup does not look at the peer: a connected socket hashed last takes a reply from anybody.
    const conn = [_]pp.Holder{ .{ .seq = 1, .bound = any }, .{ .seq = 2, .bound = any, .peer = lo1 } };
    try std.testing.expectEqual(@as(?usize, 1), pp.pickReceiver(&conn, lo2, lo1));
    try std.testing.expectEqual(@as(?usize, null), pp.pickReceiver(&[_]pp.Holder{.{ .seq = 1, .bound = own }}, lo1, lo1));
    try std.testing.expectEqual(@as(?usize, null), pp.pickReceiver(&[_]pp.Holder{}, lo1, lo1));

    const us = kt.udp_source;
    // deliverPing gathers every holder of the ident and lets the policy pick; pingBind and the first send rehash (a new sequence).
    try std.testing.expect(std.mem.indexOf(u8, us, "const pick = pp.pickReceiver(holders[0..n], src_ip, dst_ip) orelse break :blk;") != null);
    try std.testing.expect(std.mem.indexOf(u8, us, "pub fn pingRehash(key: u32) void {") != null);
    try std.testing.expect(std.mem.indexOf(u8, us, "    port_seq[oi] = next_seq;\n    next_seq +%= 1;\n    port_local_ip[oi] = addr;") != null);
    const ss = kt.socket_syscall_source;
    try std.testing.expect(std.mem.indexOf(u8, ss, "    if (!d.udp_ping_bound) udp.pingRehash(d.udpKey());\n    d.udp_ping_bound = true;") != null);
    // connect() of a ping socket hashes it too (ip4_datagram_connect autobinds), so getsockname names its ident.
    try std.testing.expect(std.mem.indexOf(u8, ss, "        if (t.fd_table.fds[fd].udp_ping and !t.fd_table.fds[fd].udp_ping_bound) {\n            udp.pingRehash(t.fd_table.fds[fd].udpKey());\n            t.fd_table.fds[fd].udp_ping_bound = true;\n        }") != null);
}

test "IPv4 traffic to our own address goes over lo like 127/8 (hello370)" {
    const r = kt.route4_policy;
    const our = [4]u8{ 10, 0, 2, 15 };
    try std.testing.expect(r.isLocal4(.{ 127, 0, 0, 1 }, our));
    try std.testing.expect(r.isLocal4(.{ 127, 9, 9, 9 }, our));
    try std.testing.expect(r.isLocal4(our, our));
    try std.testing.expect(!r.isLocal4(.{ 10, 0, 2, 2 }, our));
    try std.testing.expect(!r.isLocal4(.{ 10, 0, 2, 16 }, our));
    try std.testing.expect(!r.isLocal4(.{ 0, 0, 0, 0 }, our));

    const ts = kt.tcp_source;
    // TX: segments to our own address are queued on lo; the SYN that lo dropped is resent like any loopback one.
    try std.testing.expect(std.mem.indexOf(u8, ts, "    const loopback = netif.isLocal4(hdr_dst);\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, ts, "if (!synLostOnLoopback(tcb, netif.isLocal4(remote_ip))) {") != null);
    try std.testing.expect(std.mem.indexOf(u8, ts, "loop_dst = tcb.active and !tcb.is_v6 and netif.isLocal4(tcb.remote_ip);") != null);
    // RX: the checksum covers the address the segment was sent to, and a segment no connection takes is answered with a RST.
    try std.testing.expect(std.mem.indexOf(u8, ts, "    const csum_dst = if (netif.isLocal4(dst_ip)) dst_ip else netif.getOurIp();\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, ts, "    if (!netif.isLocal4(src_ip) or !netif.isLocal4(dst_ip)) return;\n") != null);
    const us = kt.udp_source;
    try std.testing.expect(std.mem.indexOf(u8, us, "    const loopback = netif.isLocal4(dst_ip);\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, us, "unreach.shouldReply(netif.isLocal4(src_ip) and netif.isLocal4(dst_ip), false, bound)") != null);
    try std.testing.expect(std.mem.indexOf(u8, kt.icmp_source, "        const via_lo = netif.isLocal4(src_ip);\n") != null);
}

test "a connect whose neighbor never resolves fails with EHOSTUNREACH after 3 s (hello369)" {
    const rp = kt.tcp_recv_policy;
    // Measured on the monotonic clock: the 100 ms maintenance pass runs late under load, so counting passes stretched 3 s to 7.8 s.
    const start: u64 = 5_000_000_000;
    try std.testing.expect(!rp.neighborGaveUp(start, start));
    try std.testing.expect(!rp.neighborGaveUp(start, start + rp.NEIGH_RESOLVE_NS - 1));
    try std.testing.expect(rp.neighborGaveUp(start, start + rp.NEIGH_RESOLVE_NS));
    try std.testing.expect(!rp.neighborGaveUp(start, start - 1));
    try std.testing.expectEqual(@as(u64, 3_000_000_000), rp.NEIGH_RESOLVE_NS);
    try std.testing.expectEqual(@as(i64, -113), rp.connectFailure(rp.EHOSTUNREACH));

    const ts = kt.tcp_source;
    try std.testing.expect(std.mem.indexOf(u8, ts, "    if (!pending) return false;\n    tcb.neigh_wait = true;\n    tcb.neigh_wait_since_ns = @import(\"../arch/arch.zig\").tsc.nanos();\n    advanceSndNxt(tcb, SYN, 0);") != null);
    try std.testing.expect(std.mem.indexOf(u8, ts, "    t.neigh_wait = false;\n    t.neigh_wait_since_ns = 0;\n") != null);
    const tick = std.mem.indexOf(u8, ts, "fn timerTickOne(idx: u32, ms_elapsed: u32) void {").?;
    const give = std.mem.indexOfPos(u8, ts, tick, "if (tcp_recv_policy.neighborGaveUp(tcb.neigh_wait_since_ns, @import(\"../arch/arch.zig\").tsc.nanos())) {").?;
    try std.testing.expect(give < std.mem.indexOfPos(u8, ts, tick, "if (tcb.state == .fin_wait_2) {").?);
    try std.testing.expect(std.mem.indexOfPos(u8, ts, give, "tcb.options.so_error = tcp_recv_policy.EHOSTUNREACH;").? <
        std.mem.indexOfPos(u8, ts, give, "closeTcbRemote(tcb);").?);
}

test "IPv4 next hop: an off-link address goes through the gateway, and a SYN waiting for ARP counts as sent (hello368)" {
    const r = kt.route4_policy;
    const our = [4]u8{ 10, 0, 2, 15 };
    const mask = [4]u8{ 255, 255, 255, 0 };
    const gw = [4]u8{ 10, 0, 2, 2 };
    try std.testing.expectEqual([4]u8{ 10, 0, 2, 99 }, r.nextHop4(.{ 10, 0, 2, 99 }, our, mask, gw));
    try std.testing.expectEqual(gw, r.nextHop4(gw, our, mask, gw));
    try std.testing.expectEqual(gw, r.nextHop4(.{ 192, 0, 2, 1 }, our, mask, gw));
    try std.testing.expectEqual(gw, r.nextHop4(.{ 10, 0, 3, 1 }, our, mask, gw));
    // No gateway: every address is tried on the link.
    try std.testing.expectEqual([4]u8{ 192, 0, 2, 1 }, r.nextHop4(.{ 192, 0, 2, 1 }, our, mask, .{ 0, 0, 0, 0 }));
    // A /16 subnet keeps 10.0.3.1 on the link.
    try std.testing.expectEqual([4]u8{ 10, 0, 3, 1 }, r.nextHop4(.{ 10, 0, 3, 1 }, our, .{ 255, 255, 0, 0 }, gw));

    const us = kt.udp_source;
    try std.testing.expect(std.mem.indexOf(u8, us, "break :resolve arp.resolve(hop) orelse blk: {\n            wait_hop = hop;") != null);
    const ts = kt.tcp_source;
    try std.testing.expect(std.mem.indexOf(u8, ts, "const hop = netif.nextHop4(hdr_dst);") != null);
    try std.testing.expect(std.mem.indexOf(u8, ts, "arp.resolve(hop) orelse {\n        arp.sendArpRequest(hop);") != null);
    // An echo reply goes back the way any other datagram would: through the gateway to an off-link requester, over lo to a loopback one.
    const is = kt.icmp_source;
    try std.testing.expect(std.mem.indexOf(u8, is, "const hop = netif.nextHop4(src_ip);") != null);
    try std.testing.expect(std.mem.indexOf(u8, is, "arp.resolve(hop) orelse {\n                arp.sendArpRequest(hop);") != null);
    try std.testing.expect(std.mem.indexOf(u8, is, "if (via_lo) _ = lo.sendPacket(&pkt, frame_len) else _ = nic.sendPacket(&pkt, frame_len);") != null);
    const lost = std.mem.indexOf(u8, ts, "if (!synLostOnLoopback(tcb, netif.isLocal4(remote_ip))) {").?;
    try std.testing.expect(std.mem.indexOfPos(u8, ts, lost, "if (!synAwaitsNeighbor(tcb, arp.resolve(netif.nextHop4(remote_ip)) == null)) {").? <
        std.mem.indexOfPos(u8, ts, lost, "tcb.state = .closed;").?);
}

test "IPv6 TCP connect: a group is ENETUNREACH, a link-local peer needs an interface and ties the socket to it (hello367)" {
    const bp = kt.bind_addr_policy;
    var ff02: [16]u8 = @splat(0);
    ff02[0] = 0xff;
    ff02[1] = 0x02;
    ff02[15] = 1;
    var ff0e = ff02;
    ff0e[1] = 0x0e;
    var ll: [16]u8 = @splat(0);
    ll[0] = 0xfe;
    ll[1] = 0x80;
    ll[15] = 7;
    var lo6: [16]u8 = @splat(0);
    lo6[15] = 1;
    var uni: [16]u8 = @splat(0);
    uni[0] = 0x20;
    uni[1] = 0x01;
    uni[15] = 9;
    // tcp_v6_connect: any group is ENETUNREACH before the scope is looked at.
    try std.testing.expectEqual(bp.Connect6{ .dev = 0, .err = bp.ENETUNREACH }, bp.streamConnectDev6(ff02, 2, 0));
    try std.testing.expectEqual(bp.Connect6{ .dev = 0, .err = bp.ENETUNREACH }, bp.streamConnectDev6(ff02, 0, 0));
    try std.testing.expectEqual(bp.Connect6{ .dev = 0, .err = bp.ENETUNREACH }, bp.streamConnectDev6(ff0e, 0, 0));
    // A link-local peer: the scope must match the bound interface, and some interface is required.
    try std.testing.expectEqual(bp.Connect6{ .dev = 0, .err = bp.EINVAL }, bp.streamConnectDev6(ll, 0, 0));
    try std.testing.expectEqual(bp.Connect6{ .dev = 2, .err = 0 }, bp.streamConnectDev6(ll, 2, 0));
    try std.testing.expectEqual(bp.Connect6{ .dev = 9, .err = bp.ENETUNREACH }, bp.streamConnectDev6(ll, 9, 0));
    try std.testing.expectEqual(bp.Connect6{ .dev = 9, .err = bp.EINVAL }, bp.streamConnectDev6(ll, 2, 9));
    try std.testing.expectEqual(bp.Connect6{ .dev = 2, .err = bp.EINVAL }, bp.streamConnectDev6(ll, 1, 2));
    try std.testing.expectEqual(bp.Connect6{ .dev = 2, .err = 0 }, bp.streamConnectDev6(ll, 0, 2));
    try std.testing.expectEqual(bp.Connect6{ .dev = 1, .err = bp.ENETUNREACH }, bp.streamConnectDev6(ll, 1, 0));
    // Any other address ignores the scope.
    try std.testing.expectEqual(bp.Connect6{ .dev = 0, .err = 0 }, bp.streamConnectDev6(lo6, 9, 0));
    try std.testing.expectEqual(bp.Connect6{ .dev = 0, .err = 0 }, bp.streamConnectDev6(uni, 9, 0));

    const ss = kt.socket_syscall_source;
    const dev_at = std.mem.indexOf(u8, ss, "const dev_rc = net_mod.tcp.tcpConnectDev6(tcb_idx, parsed.addr, parsed.scope_id);").?;
    try std.testing.expect(dev_at < std.mem.indexOfPos(u8, ss, dev_at, "net_mod.tcp.tcpConnectSocketV6Flow(tcb_idx, parsed.addr, parsed.port,").?);
    try std.testing.expect(std.mem.indexOf(u8, ss, "return net_mod.tcp.tcpBindAddr46(tcb_idx, parsed.port, net_mod.tcp_port_policy.WILDCARD4, parsed.addr, bind_addr_policy.boundDev6(parsed.addr, parsed.scope_id));") != null);
    const ts = kt.tcp_source;
    const f = std.mem.indexOf(u8, ts, "pub fn tcpConnectDev6(").?;
    const fe = std.mem.indexOfPos(u8, ts, f, "\n}\n").?;
    // Only a socket that may still connect is retied; a connected or connecting one gets its connect error from tcpConnectSocketV6.
    try std.testing.expect(std.mem.indexOf(u8, ts[f..fe], "if (tcb.state != .closed) return 0;") != null);
    try std.testing.expect(std.mem.indexOf(u8, ts[f..fe], "tcb.bound_dev6 = r.dev;") != null);
    try std.testing.expect(std.mem.indexOf(u8, ts, "    t.bound_dev6 = 0;\n") != null);
    // A SYN held back while the neighbor is being solicited counts as sent, so connect() is EINPROGRESS and the retransmit timer
    // resends it (and solicits again), as Linux queues it on the neighbor entry.
    const lost = std.mem.indexOf(u8, ts, "if (!synLostOnLoopback(tcb, netif.isLoopbackV6(remote_ip6))) {").?;
    try std.testing.expect(std.mem.indexOfPos(u8, ts, lost, "if (!synAwaitsNeighbor(tcb, ndp.resolveNextHop(remote_ip6).solicit != null)) {").? <
        std.mem.indexOfPos(u8, ts, lost, "tcb.state = .closed;").?);
    try std.testing.expect(std.mem.indexOf(u8, ts, "fn synAwaitsNeighbor(tcb: *TcpTcb, pending: bool) bool {\n    if (!pending) return false;\n    tcb.neigh_wait = true;\n    tcb.neigh_wait_since_ns = @import(\"../arch/arch.zig\").tsc.nanos();\n    advanceSndNxt(tcb, SYN, 0);\n    return true;\n}") != null);
}

test "an IPv6 TCP socket's bound address takes part in conflicts, listener choice, lookup, source address and naming (hello359)" {
    const ts = kt.tcp_source;
    try std.testing.expect(std.mem.indexOf(u8, ts, "        if (tcb.is_v6 and !tcp_port_policy.addrsConflict6(tcb.local_ip6, tcbs[i].local_ip6)) continue;\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, ts, "    tcb.local_ip6 = if (tcb.is_v6) addr6 else @splat(0);\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, ts, "    listen_slots[i].local_ip6 = tcb.local_ip6;\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, ts, "    return if (is_v6) tcp_port_policy.listenerTakes6(ls.local_ip6, dst_ip6, exact) else tcp_port_policy.listenerTakes(ls.local_ip, dst_ip, exact);\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, ts, "(local_ip6 == null or tcp_port_policy.localAddrMatches6(tcbs[i].local_ip6, remote_ip6, local_ip6.?))") != null);
    try std.testing.expect(std.mem.indexOf(u8, ts, "    const tcb = findTcbByTupleV6(dst_ip, dst_port, src_port, src_ip) orelse {\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, ts, "    new_tcb.local_ip6 = dst_ip;\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, ts, "            reuse_tcb.local_ip6 = dst_ip;\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, ts, "if (!tcp_port_policy.sameLocalAddr6(o.local_ip6, tcb.local_ip6, ip6, ndp.selectSourceAddress(ip6, netif.getMac()))) continue;") != null);
    try std.testing.expect(std.mem.indexOf(u8, ts, "    const our_ip = tcp_port_policy.sourceAddr6(tcb.local_ip6, tcb.remote_ip6, if (is_loop) tcb.remote_ip6 else ndp.selectSourceAddress(tcb.remote_ip6, our_mac));\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, ts, "tcp_port_policy.nameAddr6(tcb.local_ip6, tcb.remote_port != 0, tcb.remote_ip6,") != null);
    try std.testing.expect(std.mem.indexOf(u8, ts, "    const is_loop = netif.isLoopbackV6(tcb.remote_ip6) or ndp.isOwnAddress(tcb.remote_ip6, netif.getMac());\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, kt.udp_source, "    const is_loop = netif.isLoopbackV6(dst_ip) or ndp.isOwnAddress(dst_ip, netif.getMac());\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, kt.socket_syscall_source, "return net_mod.tcp.tcpBindAddr46(tcb_idx, parsed.port, net_mod.tcp_port_policy.WILDCARD4, parsed.addr, bind_addr_policy.boundDev6(parsed.addr, parsed.scope_id));") != null);
    const p = kt.tcp_port_policy;
    const wild: [16]u8 = @splat(0);
    var loop6 = wild;
    loop6[15] = 1;
    var g = wild;
    g[0] = 0xfe;
    g[1] = 0xc0;
    g[15] = 7;
    var peer = g;
    peer[15] = 9;
    // A connection to ::1 is matched by the source address its segments carry.
    try std.testing.expect(p.localAddrMatches6(g, loop6, g));
    try std.testing.expect(!p.localAddrMatches6(g, loop6, loop6));
    try std.testing.expect(p.localAddrMatches6(wild, loop6, loop6));
    try std.testing.expect(!p.localAddrMatches6(wild, loop6, g));
    try std.testing.expect(p.localAddrMatches6(loop6, loop6, loop6));
    // Any other connection by its bound address, or any address when bound to ::.
    try std.testing.expect(p.localAddrMatches6(wild, peer, g));
    try std.testing.expect(p.localAddrMatches6(g, peer, g));
    try std.testing.expect(!p.localAddrMatches6(g, peer, loop6));
    try std.testing.expect(p.sameLocalAddr6(wild, loop6, loop6, g));
    try std.testing.expect(!p.sameLocalAddr6(g, loop6, loop6, g));
    try std.testing.expect(p.sameLocalAddr6(wild, g, peer, g));
}

