    try std.testing.expect(!np.raisesSigpipe(-104, 0));
    try std.testing.expect(!np.raisesSigpipe(5, 0));
    try std.testing.expectEqual(@as(u32, 0x4000), np.MSG_NOSIGNAL);
}

