test "O_APPEND writes to ext2 and FAT32 find the end and stage the data under one append lock" {
    // hello266: with a tmpfs-only fix, four appenders on ext2 or FAT32 still lost lines (10 and 4 of 20 rounds); Linux loses none.
    const v = kt.vfs_source;
    // Four sites: write() and writeAtOffset() (pwrite/pwritev), for each of ext2 and FAT32.
    try std.testing.expectEqual(@as(usize, 4), std.mem.count(u8, v, "if (appending) appendLockOf(desc).lock();\n                defer if (appending) appendLockOf(desc).unlock();"));
    try std.testing.expect(std.mem.indexOf(u8, v, "var append_locks: [@import(\"append_lock_policy.zig\").STRIPES]@import(\"../sync/task_sleep_lock.zig\").SleepLock = @splat(.{});") != null);
    // ext2 takes the end from currentSize (disk size or the end still staged by another appender), not from this descriptor's cached size.
    try std.testing.expect(std.mem.indexOf(u8, v, "desc.file_size = @import(\"ext2.zig\").currentSize(desc.ext2_file_idx);\n                    desc.offset = desc.file_size;") != null);
}

test "bind(): an address the host does not have is EADDRNOTAVAIL, checked before the port rules" {
    const bp = kt.bind_addr_policy;
    const down: bp.Nic = .{};
    const up: bp.Nic = .{ .active = true, .ip = .{ 10, 0, 2, 15 }, .netmask = .{ 255, 255, 255, 0 }, .link_local6 = .{ 0xfe, 0x80, 0, 0, 0, 0, 0, 0, 0x52, 0x54, 0, 0xff, 0xfe, 0x12, 0x34, 0x56 } };
    try std.testing.expectEqual(@as(i64, -99), bp.EADDRNOTAVAIL);
    // IPv4: wildcard, all of 127/8, multicast and limited broadcast are always bindable.
    for ([_]bp.Nic{ down, up }) |n| {
        try std.testing.expect(bp.inet4Bindable(.{ 0, 0, 0, 0 }, n));
        try std.testing.expect(bp.inet4Bindable(.{ 127, 0, 0, 1 }, n));
        try std.testing.expect(bp.inet4Bindable(.{ 127, 9, 8, 7 }, n));
        try std.testing.expect(bp.inet4Bindable(.{ 224, 0, 0, 251 }, n));
        try std.testing.expect(bp.inet4Bindable(.{ 239, 255, 255, 250 }, n));
        try std.testing.expect(bp.inet4Bindable(.{ 255, 255, 255, 255 }, n));
        try std.testing.expect(!bp.inet4Bindable(.{ 192, 0, 2, 1 }, n));
        try std.testing.expect(!bp.inet4Bindable(.{ 240, 0, 0, 1 }, n));
    }
    // The NIC's own address and its subnet broadcast only exist while the NIC does.
    try std.testing.expect(bp.inet4Bindable(.{ 10, 0, 2, 15 }, up));
    try std.testing.expect(bp.inet4Bindable(.{ 10, 0, 2, 255 }, up));
    try std.testing.expect(!bp.inet4Bindable(.{ 10, 0, 2, 16 }, up));
    try std.testing.expect(!bp.inet4Bindable(.{ 10, 0, 2, 15 }, down));
    // IPv6: ::, ::1, multicast, the link-local address and configured addresses; v4-mapped follows IPv4.
    const any6: [16]u8 = @splat(0);
    var lo6: [16]u8 = @splat(0);
    lo6[15] = 1;
    var two: [16]u8 = @splat(0);
    two[15] = 2;
    var doc: [16]u8 = @splat(0);
    doc[0] = 0x20;
    doc[1] = 0x01;
    doc[2] = 0x0d;
    doc[3] = 0xb8;
    doc[15] = 1;
    var mc: [16]u8 = @splat(0);
    mc[0] = 0xff;
    mc[1] = 0x02;
    mc[15] = 1;
    var mapped_lo: [16]u8 = @splat(0);
    mapped_lo[10] = 0xff;
    mapped_lo[11] = 0xff;
    mapped_lo[12] = 127;
    mapped_lo[15] = 1;
    var mapped_foreign = mapped_lo;
    mapped_foreign[12] = 192;
    mapped_foreign[13] = 0;
    mapped_foreign[14] = 2;
    for ([_]bp.Nic{ down, up }) |n| {
        try std.testing.expect(bp.inet6Bindable(any6, n, false));
        try std.testing.expect(bp.inet6Bindable(lo6, n, false));
        try std.testing.expect(bp.inet6Bindable(mc, n, false));
        try std.testing.expect(bp.inet6Bindable(mapped_lo, n, false));
        try std.testing.expect(!bp.inet6Bindable(mapped_foreign, n, false));
        try std.testing.expect(!bp.inet6Bindable(two, n, false));
        try std.testing.expect(!bp.inet6Bindable(doc, n, false));
    }
    try std.testing.expect(bp.inet6Bindable(up.link_local6, up, false));
    try std.testing.expect(!bp.inet6Bindable(up.link_local6, down, false));
    try std.testing.expect(bp.inet6Bindable(doc, up, true));
    // Wiring: every bind path (TCP/UDP x IPv4/IPv6, and the IPv6 raw socket) asks the policy before the port rules.
    const ss = kt.socket_syscall_source;
    try std.testing.expectEqual(@as(usize, 2), std.mem.count(u8, ss, "if (bindAddrNotAvail4For("));
    try std.testing.expectEqual(@as(usize, 3), std.mem.count(u8, ss, "if (bindAddrNotAvail6For("));
    try std.testing.expect(std.mem.indexOf(u8, ss, "if (bindAddrNotAvail6For(&t.fd_table.fds[fd], parsed.addr)) return bind_addr_policy.EADDRNOTAVAIL;\n        if (bindNeedsPrivilege(parsed.port)") != null);
    try std.testing.expect(std.mem.indexOf(u8, ss, "if (bindAddrNotAvail4For(&t.fd_table.fds[fd], .{ sock_addr[4], sock_addr[5], sock_addr[6], sock_addr[7] })) return bind_addr_policy.EADDRNOTAVAIL;\n    if (bindNeedsPrivilege(port)") != null);
}

test "SIGSTOP on a task running on another CPU kicks that CPU instead of waiting for its next tick" {
    const sig = kt.signal_source;
    const start = std.mem.indexOf(u8, sig, "pub fn stopTask(t: *task.Task, signum: u32) void {") orelse return error.TestUnexpectedResult;
    const body = sig[start..][0..std.mem.indexOf(u8, sig[start..], "\n}\n").?];
    // A task marked ready can still be executing on its CPU (the scheduler marks the outgoing task ready before publishing it); the kick comes after the state change.
    try std.testing.expect(std.mem.indexOf(u8, body, "if (s == .running or s == .ready) sc.store(&t.state, .blocked);\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, body, "\n    if (s == .running) kickUntilStopped(t) else if (s == .ready) kickRunningCpu(t);") != null);
    try std.testing.expect(std.mem.indexOf(u8, body, "sc.store(&t.state, .blocked);").? < std.mem.indexOf(u8, body, "kickUntilStopped(t)").?);
    // The parent's WUNTRACED report comes from the member that completes the group's stop, on the leader's behalf (hello286).
    try std.testing.expect(std.mem.indexOf(u8, body, "const progress = task.markStopped(t, signum);\n    if (progress == .already) return;") != null);
    try std.testing.expect(std.mem.indexOf(u8, body, "if (progress == .group_complete) if (task.groupLeaderOf(t)) |leader| notifyParentOfChange(leader, .{ .stopped = @intCast(signum) });") != null);
    // A stop taken on the syscall-return path must leave the CPU instead of returning to user mode (hello286 F).
    try std.testing.expect(std.mem.indexOf(u8, kt.syscall_entry_source, ".stop => {\n                sig_mod.stopTask(current, signum);\n                // A stop taken on the way out of a system call leaves the CPU here: returning to user mode would run the stopped task's code.\n                const sched = @import(\"../../proc/sched.zig\");\n                while (@atomicLoad(bool, &current.stopped, .acquire)) sched.forceReschedule();\n                sched.repairCurrentAfterBlock();\n                // SIGKILL ends a stop by clearing `stopped`; the task dies here rather than running user code first.\n                if (sig_mod.pendingFatal(current)) |s| @import(\"../../proc/task.zig\").exitTask(128 + @as(i32, @intCast(s)));\n            },") != null);
    // A plain tick must not resume a stopped task's frame just because this CPU has no other ready task.
    try std.testing.expect(std.mem.indexOf(u8, kt.sched_source, "if (!force_pick and ct_state == .blocked) {\n                if (task.hasReadyOnCpu(cpu) or ct.stopped) {") != null);
    // The BSP idle thread is pinned to CPU 0: an unpinned one is the first priority-255 match every CPU's idle pick sees, so an idle AP would
    // take it and CPU 0 would have no idle thread to switch a stopped task out for (hello286 G).
    try std.testing.expect(std.mem.indexOf(u8, kt.sched_boot_source, "return task.createKernelThreadAffinity(sched.kernelIdleLoop, 255, 0);") != null);
    // And the idle pick prefers the thread pinned exactly to this CPU over an unpinned one, so a CPU keeps its own idle thread.
    try std.testing.expect(std.mem.indexOf(u8, kt.task_source, "if (t.cpu_mask == @as(u64, 1) << @intCast(cpu)) return i;") != null);
    // One kick can be coalesced away by a scheduler pass that already started, so a running target is kicked until it leaves.
    try std.testing.expect(std.mem.indexOf(u8, sig, "while (tries < STOP_KICK_TRIES) : (tries += 1) {\n        if (@import(\"sched_claim.zig\").load(&t.state) != .running) return;\n        kickRunningCpu(t);") != null);
    // The kick aims at the CPU the target itself publishes at every tick and syscall entry.
    try std.testing.expect(std.mem.indexOf(u8, sig, "if (published < se.MAX_CPUS) sched.kickCpu(published);") != null);
    try std.testing.expect(std.mem.indexOf(u8, kt.sched_source, "if (getCurrentIdx()) |ci| task.publishRunningCpu(ci, @intCast(currentCpuId()));") != null);
    // The helper finds the CPU by the per-CPU current task index, skips the caller's own CPU, and sends the reschedule IPI.
    try std.testing.expect(std.mem.indexOf(u8, sig, "se.percpu_array[cpu].current_task_idx, .acquire) == t.self_idx) sched.kickCpu(@intCast(cpu));") != null);
    try std.testing.expect(std.mem.indexOf(u8, sig, "if (here != null and here.? == cpu) continue;") != null);
    // A signal queued for a running target (the kill() path, where SIGSTOP is only pending) keeps kicking until it is off the CPU.
    try std.testing.expect(std.mem.indexOf(u8, sig, "if (t.state == .running and defaultAction(signum) == .stop) {") != null);
    try std.testing.expect(std.mem.indexOf(u8, sig, "kickUntilStopped(t);") != null);
    // A task stopping itself (kill(getpid(), SIGSTOP)) is not kicked: kickRunningCpu skips the caller's CPU, so the loop would spin all its tries.
    try std.testing.expect(std.mem.indexOf(u8, sig, "if (!isCallerTask(@intCast(i))) kickUntilStopped(t);") != null);
}

test "currentSize reads the staged end before the recorded size so a concurrent flush cannot make both reads short" {
    const e = kt.ext2_source;
    const es = std.mem.indexOf(u8, e, "pub fn currentSize(file_idx: u32) u64 {") orelse return error.TestUnexpectedResult;
    const eb = e[es..][0..std.mem.indexOf(u8, e[es..], "\n}\n").?];
    const e_staged = std.mem.indexOf(u8, eb, "stagedEnd(inode_id, .ext2)") orelse return error.TestUnexpectedResult;
    const e_disk = std.mem.indexOf(u8, eb, "refreshSize(file_idx)") orelse return error.TestUnexpectedResult;
    try std.testing.expect(e_staged < e_disk);
    const f = kt.fat32_source;
    const fs_ = std.mem.indexOf(u8, f, "pub fn currentSize(idx: u32) u64 {") orelse return error.TestUnexpectedResult;
    const fb = f[fs_..][0..std.mem.indexOf(u8, f[fs_..], "\n}\n").?];
    const f_staged = std.mem.indexOf(u8, fb, "stagedEnd(inode_id, .fat32)") orelse return error.TestUnexpectedResult;
    const f_rec = std.mem.indexOf(u8, fb, "files[idx].size else 0") orelse return error.TestUnexpectedResult;
    try std.testing.expect(f_staged < f_rec);
}

test "write() and writev() on an O_APPEND file hold one lock across all their pieces" {
    const v = kt.vfs_source;
    // Regular files only, opened for append and writing.
    try std.testing.expect(std.mem.indexOf(u8, v, "pub fn isAppendFile(self: *FdTable, fd: u32) bool {") != null);
    try std.testing.expect(std.mem.indexOf(u8, v, "return d.fd_type == .tmpfs_file or d.fd_type == .fat32_file or d.fd_type == .ext2_file;") != null);
    // write(): the lock covers the 4 KiB piece loop; writev(): it covers every iovec.
    const w = kt.file_io_source;
    const wl = std.mem.indexOf(u8, w, "if (append_call) cur.fd_table.lockAppendCall(fdIndex(fd));") orelse return error.TestUnexpectedResult;
    const wo = std.mem.indexOf(u8, w, "vfs_mod.lockOffset(&cur.fd_table.fds[fdIndex(fd)])") orelse return error.TestUnexpectedResult;
    const wp = std.mem.indexOf(u8, w, "                    cur.fd_table.writeHeld(fdIndex(fd), &kbuf, copied, held);") orelse return error.TestUnexpectedResult;
    try std.testing.expect(wl < wo and wo < wp);
    const r = kt.readv_source;
    const rs = std.mem.indexOf(u8, r, "pub fn writev(") orelse return error.TestUnexpectedResult;
    const rl = std.mem.indexOf(u8, r[rs..], "cur.fd_table.lockAppendCall(fd)") orelse return error.TestUnexpectedResult;
    const ro = std.mem.indexOf(u8, r[rs..], "vfs_mod.lockOffset(&cur.fd_table.fds[fd])") orelse return error.TestUnexpectedResult;
    const rp = std.mem.indexOf(u8, r[rs..], "cur.fd_table.writeHeld(fd, &kbuf, from_user, held)") orelse return error.TestUnexpectedResult;
    try std.testing.expect(rl < ro and ro < rp);
    // Order: the call lock is the outer one, taken before the description's offset lock and the same file's per-piece append lock stripe.
    try std.testing.expect(std.mem.indexOf(u8, v, "Outer lock of an O_APPEND write()/writev() as a whole") != null);
}

test "AF_UNIX abstract name vs pathname policies" {
    const sa = kt.socket_address_policy;
    const name_abs = "\x00h134";
    const name_path = "/tmp/h134";
    try std.testing.expect(sa.unixIsAbstract(name_abs));
    try std.testing.expect(!sa.unixIsAbstract(name_path));
    try std.testing.expectEqual(@as(usize, 5), sa.unixNameLen(name_abs));
    try std.testing.expectEqual(@as(usize, 9), sa.unixNameLen(name_path));
    var out: [120]u8 = undefined;
    @memset(&out, 0xaa);
    // Abstract name: no trailing NUL in encoding, length is 2 + name.len.
    try std.testing.expectEqual(@as(u32, 2 + 5), sa.unixNameEncode(name_abs, &out));
    try std.testing.expectEqual(@as(u8, 0), out[2]);
    try std.testing.expectEqual(@as(u8, 0xaa), out[7]); // no NUL after
}

test "AF_UNIX: a stream client that closes while queued stays acceptable with its bytes" {
    const us = kt.unix_socket_source;
    // close(): a connector still sitting in a listener's queue is parked (closed_queued), not freed and not purged.
    const park = std.mem.indexOf(u8, us, "if (connectionOriented(sock.sock_type) and !sock.connected and !sock.listening and queuedOnBacklogLocked(idx)) {\n        sock.closed_queued = true;") orelse return error.TestUnexpectedResult;
    const purge = std.mem.indexOf(u8, us, "    purgeFromBacklogsLocked(idx);\n\n    // Notify peer that we closed") orelse return error.TestUnexpectedResult;
    try std.testing.expect(park < purge);
    // accept(): such a slot yields a peerless socket holding the pending bytes, and the parked slot is released.
    try std.testing.expect(std.mem.indexOf(u8, us, "if (unix_sockets[conn_idx].closed_queued) {") != null);
    try std.testing.expect(std.mem.indexOf(u8, us, "        unix_sockets[conn_idx] = .{};\n        return @intCast(new_idx);") != null);
    // The listener closing frees parked connectors it still queues, so the table cannot fill up.
    try std.testing.expect(std.mem.indexOf(u8, us, "if (queued < MAX_UNIX_SOCKETS and unix_sockets[queued].closed_queued) {\n                freeStampsLocked(&unix_sockets[queued]);\n                unix_sockets[queued] = .{};") != null);
}

test "AF_UNIX autobind: a family-only bind() takes a kernel-chosen abstract name" {
    const us = kt.unix_socket_source;
    // A bound socket keeps its address (returns 0); an accepted (name-only) socket is EINVAL.
    try std.testing.expect(std.mem.indexOf(u8, us, "pub fn unixAutobind(idx: u32) i32 {") != null);
    try std.testing.expect(std.mem.indexOf(u8, us, "    if (sock.bound) return 0;\n    if (sock.name_only) return -22;") != null);
    // The name is NUL + five hex digits, skipped while another socket owns it.
    try std.testing.expect(std.mem.indexOf(u8, us, "if (findBoundLocked(&name) != null) continue;") != null);
    try std.testing.expect(std.mem.indexOf(u8, us, "sock.path_len = 6;") != null);
    // bind(): exactly two bytes (the family) is the autobind request, checked before the "at least one path byte" rule.
    const ss = kt.socket_syscall_source;
    const auto = std.mem.indexOf(u8, ss, "if (addr_len == SOCKADDR_UN_PATH_OFFSET) {") orelse return error.TestUnexpectedResult;
    const rule = std.mem.indexOf(u8, ss[auto..], "unixLengthValid(addr_len, SOCKADDR_UN_PATH_OFFSET)") orelse return error.TestUnexpectedResult;
    try std.testing.expect(rule > 0);
    try std.testing.expect(std.mem.indexOf(u8, ss, "net_mod.unix_socket.unixAutobind(unix_idx)") != null);
}

test "TCP SO_REUSEPORT: shared ports need both sides to opt in, same user; connections are spread by peer hash" {
    const tp = kt.tcp_port_policy;
    const RP = tp.REUSEPORT_FLAG;
    try std.testing.expectEqual(@as(u16, 8), RP);
    try std.testing.expect(tp.reusePortMayShare(RP, RP, 1000, 1000));
    try std.testing.expect(!tp.reusePortMayShare(RP, 0, 1000, 1000));
    try std.testing.expect(!tp.reusePortMayShare(0, RP, 1000, 1000));
    try std.testing.expect(!tp.reusePortMayShare(RP, RP, 1000, 1001));
    // Other flag bits do not matter.
    try std.testing.expect(tp.reusePortMayShare(RP | 4, RP | 16, 0, 0));
    // pickListener: stable for a peer, in range, and uses every listener across many peers.
    try std.testing.expectEqual(@as(u32, 0), tp.pickListener(1, .{ 1, 2, 3, 4 }, 5));
    try std.testing.expectEqual(tp.pickListener(3, .{ 10, 0, 2, 2 }, 40000), tp.pickListener(3, .{ 10, 0, 2, 2 }, 40000));
    var seen = [_]bool{ false, false, false };
    var port: u16 = 49152;
    while (port < 49152 + 60) : (port += 1) {
        const k = tp.pickListener(3, .{ 127, 0, 0, 1 }, port);
        try std.testing.expect(k < 3);
        seen[k] = true;
    }
    try std.testing.expect(seen[0] and seen[1] and seen[2]);
    // Wiring: a listener owns its slot (by TCB), bind consults the rule, SYNs pick through pickListenSlot.
    const t = kt.tcp_source;
    try std.testing.expect(std.mem.indexOf(u8, t, "listen_slots[i].tcb_idx = tcbIdx(tcb);") != null);
    try std.testing.expect(std.mem.indexOf(u8, t, "tcp_port_policy.reusePortMayShare(tcb.options.extra_flags, tcbs[i].options.extra_flags, tcb.sock_uid, tcbs[i].sock_uid)") != null);
    try std.testing.expectEqual(@as(usize, 2), std.mem.count(u8, t, "pickListenSlot(dst_port, "));
    try std.testing.expect(std.mem.indexOf(u8, t, "if (listen_slots[i].tcb_idx == tcb_idx) {") != null);
    try std.testing.expect(std.mem.indexOf(u8, t, "if (ls.tcb_idx == tcbIdx(tcb)) {") != null);
}

test "epoll nesting depth: EP_MAX_NESTS = 4 edges counted below the added epoll and above the receiver" {
    const ep = kt.epoll_policy;
    try std.testing.expectEqual(@as(u32, 4), ep.EP_MAX_NESTS);
    // (below, above): total edges = below + 1 + above.
    try std.testing.expect(!ep.nestDepthExceeded(0, 0));
    try std.testing.expect(!ep.nestDepthExceeded(3, 0)); // a three-deep tree under a plain epoll: four edges
    try std.testing.expect(!ep.nestDepthExceeded(2, 1)); // two below, one above: four
    try std.testing.expect(!ep.nestDepthExceeded(0, 3));
    try std.testing.expect(ep.nestDepthExceeded(4, 0)); // a four-deep tree under a plain epoll: five
    try std.testing.expect(ep.nestDepthExceeded(2, 2)); // five
    try std.testing.expect(ep.nestDepthExceeded(0, 4)); // a plain epoll added at the bottom of a four-deep chain: five
    // Wiring: the check follows the cycle check and uses both walks.
    const es = kt.epoll_source;
    const cyc = std.mem.indexOf(u8, es, "if (nestedChainReaches(target.instance, epfd_idx)) {") orelse return error.TestUnexpectedResult;
    const dep = std.mem.indexOf(u8, es, "epoll_policy.nestDepthExceeded(nestedDepthBelow(target.instance), nestedDepthAbove(epfd_idx))") orelse return error.TestUnexpectedResult;
    try std.testing.expect(cyc < dep);
}

test "udp port sharing: both SO_REUSEADDR, or both SO_REUSEPORT with one uid" {
    const p = kt.udp_port_policy;
    try std.testing.expect(p.mayShare(1, 1, 0, 1000));
    try std.testing.expect(p.mayShare(8, 8, 5, 5));
    try std.testing.expect(!p.mayShare(8, 8, 5, 6));
    try std.testing.expect(!p.mayShare(8, 0, 5, 5));
    try std.testing.expect(!p.mayShare(0, 8, 5, 5));
    try std.testing.expect(!p.mayShare(1, 0, 0, 0));
    try std.testing.expect(!p.mayShare(0, 0, 0, 0));
    try std.testing.expect(!p.mayShare(1, 8, 0, 0));
}

test "udp port sharing: reuseport receiver is stable per peer and covers every socket" {
    const p = kt.udp_port_policy;
    const flags = [_]u16{ 8, 8, 8 };
    const seqs = [_]u32{ 7, 3, 9 };
    var ip: [16]u8 = @splat(0);
    ip[0] = 127;
    ip[3] = 1;
    var hit = [_]bool{ false, false, false };
    var port: u16 = 49152;
    while (port < 49252) : (port += 1) {
        const a = p.pickReceiver(&flags, &seqs, ip, port);
        try std.testing.expectEqual(a, p.pickReceiver(&flags, &seqs, ip, port));
        try std.testing.expect(a < 3);
        hit[a] = true;
    }
    try std.testing.expect(hit[0] and hit[1] and hit[2]);
    try std.testing.expectEqual(@as(usize, 0), p.pickReceiver(flags[0..1], seqs[0..1], ip, 1));
}

test "udp port sharing: without SO_REUSEPORT on every socket the newest bound one receives" {
