test "arp policy: a full cache gives a new neighbour the slot of the ordinary entry updated longest ago, never a permanent one (Linux neigh_forced_gc, hello380)" {
    const ap = kt.arp_policy;
    const S = ap.CacheSlot;
    // A free slot is taken first.
    try std.testing.expectEqual(@as(?usize, 1), ap.pickCacheSlot(&[_]S{ .{ .valid = true, .updated_ns = 5 }, .{}, .{} }));
    // Full: the oldest ordinary entry, skipping an older permanent one.
    try std.testing.expectEqual(@as(?usize, 2), ap.pickCacheSlot(&[_]S{
        .{ .valid = true, .updated_ns = 50 },
        .{ .valid = true, .perm = true, .updated_ns = 1 },
        .{ .valid = true, .updated_ns = 10 },
        .{ .valid = true, .updated_ns = 30 },
    }));
    // Every entry permanent: nothing can go.
    try std.testing.expectEqual(@as(?usize, null), ap.pickCacheSlot(&[_]S{ .{ .valid = true, .perm = true }, .{ .valid = true, .perm = true } }));

    const src = kt.arp_source;
    try std.testing.expect(std.mem.indexOf(u8, src, "const i = policy.pickCacheSlot(&cache) orelse return;") != null);
    try std.testing.expect(std.mem.indexOf(u8, src, "const i = slot orelse policy.pickCacheSlot(&cache) orelse return -105; // ENOBUFS") != null);
    try std.testing.expect(std.mem.indexOf(u8, src, "cache[i].updated_ns = nowNs();") != null);
}

test "mcast policy: one IPv6 socket can join 64 groups, the 65th is ENOMEM (Linux measured 2340 within optmem_max, hello381)" {
    const m = kt.mcast_policy;
    try std.testing.expectEqual(@as(usize, 64), m.MAX_GROUPS);
    var mem: m.Membership = .{};
    var g: [16]u8 = @splat(0);
    g[0] = 0xff;
    g[1] = 0x02;
    g[11] = 1;
    for (0..64) |i| {
        g[15] = @intCast(i + 1);
        try std.testing.expectEqual(@as(i64, 0), m.join(&mem, g, 1, true));
    }
    g[15] = 65;
    try std.testing.expectEqual(m.ENOMEM, m.join(&mem, g, 1, true));
    g[15] = 1;
    try std.testing.expectEqual(m.EADDRINUSE, m.join(&mem, g, 1, true));
    for (0..64) |i| {
        g[15] = @intCast(i + 1);
        try std.testing.expectEqual(@as(i64, 0), m.drop(&mem, g, 1));
    }
    try std.testing.expectEqual(@as(u8, 0), mem.n);
}

test "arp policy: SIOCSARP / SIOCDARP with ATF_PUBL keep proxy entries per device, a zero netmask toggles proxy ARP (Linux measured, hello382)" {
    const ap = kt.arp_policy;
    const ip: [4]u8 = .{ 10, 0, 2, 90 };
    const mac: [6]u8 = .{ 0x52, 0x54, 0, 0x12, 0x34, 0x56 };
    var r = arpReq(2, ip, ap.ATF_PUBL, "eth0");
    try std.testing.expect(ap.isPublic(&r));
    try std.testing.expect(!ap.isPublic(&arpReq(2, ip, ap.ATF_COM, "eth0")));
    try std.testing.expectEqual(ap.ProxyDev.eth, ap.parsePublic(ap.SIOCSARP, &r, true, true, mac).entry.dev);
    try std.testing.expectEqual(@as(i64, -1), ap.parsePublic(ap.SIOCSARP, &r, false, true, mac).err);
    try std.testing.expectEqual(ap.ProxyDev.lo, ap.parsePublic(ap.SIOCDARP, &arpReq(2, ip, ap.ATF_PUBL, "lo"), true, true, mac).entry.dev);
    try std.testing.expectEqual(@as(i64, -19), ap.parsePublic(ap.SIOCSARP, &arpReq(2, ip, ap.ATF_PUBL, "nope0"), true, true, mac).err);
    try std.testing.expectEqual(@as(i64, -96), ap.parsePublic(ap.SIOCSARP, &arpReq(10, ip, ap.ATF_PUBL, "eth0"), true, true, mac).err);
    // No device: every device; with ATF_COM the device whose address is the given MAC (dev_getbyhwaddr), else ENODEV.
    r = arpReq(2, ip, ap.ATF_PUBL, "");
    try std.testing.expectEqual(ap.ProxyDev.any, ap.parsePublic(ap.SIOCSARP, &r, true, true, mac).entry.dev);
    r = arpSetReq(ip, ap.ATF_PUBL | ap.ATF_COM, 1, "");
    try std.testing.expectEqual(@as(i64, -19), ap.parsePublic(ap.SIOCSARP, &r, true, true, mac).err);
    @memcpy(r[18..24], &mac);
    try std.testing.expectEqual(ap.ProxyDev.eth, ap.parsePublic(ap.SIOCSARP, &r, true, true, mac).entry.dev);
    try std.testing.expectEqual(@as(i64, -19), ap.parsePublic(ap.SIOCSARP, &r, true, false, mac).err);
    // ATF_NETMASK: /32 is an entry, 0 the per-device proxy_arp switch, anything else EINVAL.
    r = arpReq(2, ip, ap.ATF_PUBL | ap.ATF_NETMASK, "eth0");
    std.mem.writeInt(u32, r[40..44], 0x00ff_ffff, .little);
    try std.testing.expectEqual(@as(i64, -22), ap.parsePublic(ap.SIOCSARP, &r, true, true, mac).err);
    std.mem.writeInt(u32, r[40..44], 0, .little);
    try std.testing.expect(ap.parsePublic(ap.SIOCSARP, &r, true, true, mac) == .toggle);
    try std.testing.expect(ap.parsePublic(ap.SIOCDARP, &r, true, true, mac) == .toggle);
    std.mem.writeInt(u32, r[40..44], 0xffff_ffff, .little);
    try std.testing.expect(ap.parsePublic(ap.SIOCSARP, &r, true, true, mac) == .entry);

    // /proc/net/arp: arp_format_pneigh_entry's line, flags ATF_PUBL|ATF_PERM, a zero MAC, the device type and name or 0 and "*".
    var buf: [160]u8 = undefined;
    var n = ap.formatProxyLine(&buf, ip, .eth);
    try std.testing.expectEqualStrings("10.0.2.90        0x1         0xc         00:00:00:00:00:00     *        eth0\n", buf[0..n]);
    n = ap.formatProxyLine(&buf, ip, .any);
    try std.testing.expectEqualStrings("10.0.2.90        0x0         0xc         00:00:00:00:00:00     *        *\n", buf[0..n]);
    n = ap.formatProxyLine(&buf, ip, .lo);
    try std.testing.expectEqualStrings("10.0.2.90        0x304       0xc         00:00:00:00:00:00     *        lo\n", buf[0..n]);

    const as = kt.arp_source;
    try std.testing.expect(std.mem.indexOf(u8, as, "pub fn setProxy(ip: [4]u8, dev: policy.ProxyDev) i64 {") != null);
    try std.testing.expect(std.mem.indexOf(u8, as, "pub fn deleteProxy(ip: [4]u8, dev: policy.ProxyDev) bool {") != null);
    try std.testing.expect(std.mem.indexOf(u8, as, "n += policy.formatProxyLine(out[n..], e.ip, e.dev);") != null);
    const io = kt.ioctl_source;
    try std.testing.expect(std.mem.indexOf(u8, io, "if (cmd != ap.SIOCGARP and ap.isPublic(&req)) {") != null);
    try std.testing.expect(std.mem.indexOf(u8, io, "return if (arp.deleteProxy(p.ip, p.dev)) 0 else -2; // ENOENT") != null);
}

test "devconf policy: net.ipv4.conf.<dev>.proxy_arp paths, proc_dointvec writes, set by ATF_PUBL netmask 0 (hello383)" {
    const dp = kt.devconf_policy;
    // Paths below /proc: the conf directory, a device's directory, its proxy_arp file; eth0 only while the NIC is up.
    try std.testing.expect(dp.lookup("sys/net/ipv4/conf", true).? == .conf_dir);
    try std.testing.expect(dp.lookup("sys/net/ipv4/conf/", true).? == .conf_dir);
    try std.testing.expectEqual(dp.Dev.eth, dp.lookup("sys/net/ipv4/conf/eth0", true).?.dev_dir);
    try std.testing.expectEqual(dp.Dev.all, dp.lookup("sys/net/ipv4/conf/all/", true).?.dev_dir);
    try std.testing.expectEqual(dp.Dev.default, dp.lookup("sys/net/ipv4/conf/default/proxy_arp", true).?.conf_file.dev);
    try std.testing.expectEqual(dp.Dev.lo, dp.lookup("sys/net/ipv4/conf/lo/proxy_arp", false).?.conf_file.dev);
    try std.testing.expect(dp.lookup("sys/net/ipv4/conf/eth0/proxy_arp", false) == null);
    try std.testing.expect(dp.lookup("sys/net/ipv4/conf/nope0/proxy_arp", true) == null);
    try std.testing.expect(dp.lookup("sys/net/ipv4/conf/eth0/nope", true) == null);
    try std.testing.expect(dp.lookup("sys/net/ipv4/confx", true) == null);
    try std.testing.expect(dp.lookup("sys/net/ipv4/ping_group_range", true) == null);

    // Writes as measured on Linux (hello383 W): the return value and, when it parsed, the new value.
    const Case = struct { t: []const u8, ret: i64, v: ?i32 };
    const cases = [_]Case{
        .{ .t = "1\n", .ret = 2, .v = 1 },         .{ .t = "-3", .ret = 2, .v = -3 },
        .{ .t = "x", .ret = -22, .v = null },      .{ .t = "  7  \n", .ret = 6, .v = 7 },
        .{ .t = "7 8", .ret = 2, .v = 7 },         .{ .t = "", .ret = 0, .v = null },
        .{ .t = "99999999999", .ret = -22, .v = null }, .{ .t = "0x10", .ret = 4, .v = 16 },
        .{ .t = "010", .ret = 3, .v = 8 },         .{ .t = "12abc", .ret = -22, .v = null },
        .{ .t = "4\r", .ret = -22, .v = null },    .{ .t = "\n\n", .ret = -22, .v = null },
        .{ .t = "-2147483648", .ret = 11, .v = -2147483648 }, .{ .t = "2147483648", .ret = -22, .v = null },
        .{ .t = "000000000000000000001", .ret = -22, .v = null }, .{ .t = "00000000000000000002", .ret = 20, .v = 2 },
        .{ .t = "4\t", .ret = 2, .v = 4 },         .{ .t = "-", .ret = -22, .v = null },
        .{ .t = "+1", .ret = -22, .v = null },     .{ .t = "0", .ret = 1, .v = 0 },
    };
    for (cases) |c| {
        const w = dp.writeInt(c.t);
        try std.testing.expectEqual(c.ret, w.ret);
        try std.testing.expectEqual(c.v, w.value);
    }
    var buf: [16]u8 = undefined;
    try std.testing.expectEqualStrings("0\n", buf[0..dp.formatInt(&buf, 0)]);
    try std.testing.expectEqualStrings("-2147483648\n", buf[0..dp.formatInt(&buf, -2147483648)]);

    // Wiring: the values live in arp.zig; SIOCSARP / SIOCDARP with netmask 0 set them; /proc lists and opens the files; a holder of
    // CAP_NET_ADMIN may open them (and ping_group_range) for writing (net_ctl_permissions); a sysctl reads nothing past offset 0 and
    // a write there is swallowed (sysctl_writes_strict).
    const as = kt.arp_source;
    try std.testing.expect(std.mem.indexOf(u8, as, "pub fn confWrite(cf: devconf.ConfFile, text: []const u8) i64 {") != null);
    try std.testing.expect(std.mem.indexOf(u8, as, "pub fn setProxyArp(dev: devconf.Dev, v: i32) void {") != null);
    const io = kt.ioctl_source;
    try std.testing.expect(std.mem.indexOf(u8, io, ".toggle => |d| {") != null);
    try std.testing.expect(std.mem.indexOf(u8, io, "arp.setProxyArp(arp.confDev(d), if (cmd == ap.SIOCSARP) 1 else 0);") != null);
    const pf = kt.procfs_source;
    try std.testing.expect(std.mem.indexOf(u8, pf, ".sys_ipv4_dir => &.{ .{ .name = \"conf\", .dtype = DT_DIR }, .{ .name = \"ip_local_port_range\", .dtype = DT_REG }, .{ .name = \"ip_local_reserved_ports\", .dtype = DT_REG }, .{ .name = \"ip_unprivileged_port_start\", .dtype = DT_REG }, .{ .name = \"ip_nonlocal_bind\", .dtype = DT_REG }, .{ .name = \"ping_group_range\", .dtype = DT_REG }, .{ .name = \"tcp_notsent_lowat\", .dtype = DT_REG } },") != null);
    try std.testing.expect(std.mem.indexOf(u8, pf, ".conf_file => @intCast(@import(\"../net/arp.zig\").confRead(@import(\"../net/devconf_policy.zig\").decode(pid), buf[0..@min(max_len, 16)])),") != null);
    try std.testing.expect(std.mem.indexOf(u8, pf, "pub fn isSysctl(file: ProcFile) bool {") != null);
    const vs = kt.vfs_source;
    try std.testing.expect(std.mem.indexOf(u8, vs, "@import(\"../net/devconf_policy.zig\").lookup(rest, @import(\"../net/nic.zig\").isActive())") != null);
    try std.testing.expect(std.mem.indexOf(u8, vs, "if (is_writable and euid != 0 and !effective_caps.cap_net_admin) {") != null);
    try std.testing.expect(std.mem.indexOf(u8, vs, "fn sysctlWrite(desc: *FileDescriptor, buf: [*]const u8, count: usize, offset: u64) i64 {") != null);
    try std.testing.expect(std.mem.indexOf(u8, vs, "if (procfs.isSysctl(desc.proc_file_type) and offset != 0) return 0;") != null);
}

test "arp policy: an incomplete neighbour (no MAC yet) reads flags 0 in SIOCGARP and /proc/net/arp (Linux measured, hello384)" {
    const ap = kt.arp_policy;
    // arp_state_to_flags: NUD_PERMANENT is ATF_PERM|ATF_COM, another valid state ATF_COM, INCOMPLETE / FAILED 0.
    try std.testing.expectEqual(@as(u32, 0), ap.entryFlags(false, false));
    try std.testing.expectEqual(ap.ATF_COM, ap.entryFlags(true, false));
    try std.testing.expectEqual(ap.ATF_COM | ap.ATF_PERM, ap.entryFlags(true, true));
    var buf: [160]u8 = undefined;
    const n = ap.formatProcLine(&buf, .{ 10, 0, 2, 98 }, .{ 0, 0, 0, 0, 0, 0 }, ap.entryFlags(false, false), "eth0");
    try std.testing.expectEqualStrings("10.0.2.98        0x1         0x0         00:00:00:00:00:00     *        eth0\n", buf[0..n]);
    var r = arpReq(2, .{ 10, 0, 2, 98 }, 0, "eth0");
    @memset(r[16..32], 0xAA);
    ap.answerGet(&r, .{ 0, 0, 0, 0, 0, 0 }, ap.entryFlags(false, false));
    try std.testing.expectEqual(@as(u16, 1), std.mem.readInt(u16, r[16..18], .little));
    try std.testing.expect(std.mem.allEqual(u8, r[18..24], 0));
    try std.testing.expectEqual(@as(u32, 0), std.mem.readInt(u32, r[32..36], .little));

    // The cache keeps entries without a MAC: an ARP request for an address not in the table adds one (__neigh_event_send), resolve
    // skips it, a reply completes it, SIOCSARP without a MAC on it is EINVAL (__neigh_update with no lladdr on an invalid entry).
    const as = kt.arp_source;
    try std.testing.expect(std.mem.indexOf(u8, as, "    has_mac: bool = true,\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, as, "fn noteIncomplete(ip: [4]u8) void {") != null);
    try std.testing.expect(std.mem.indexOf(u8, as, "pub fn sendArpRequest(target_ip: [4]u8) void {\n    noteIncomplete(target_ip);") != null);
    try std.testing.expect(std.mem.indexOf(u8, as, "if (cache[i].valid and cache[i].has_mac and @as(u32, @bitCast(cache[i].ip)) == @as(u32, @bitCast(ip))) {") != null);
    try std.testing.expect(std.mem.indexOf(u8, as, "            const m = mac orelse if (cache[i].has_mac) cache[i].mac else return -22; // EINVAL") != null);
    try std.testing.expect(std.mem.indexOf(u8, as, "n += policy.formatProcLine(out[n..], e.ip, e.mac, policy.entryFlags(e.has_mac, e.perm), \"eth0\");") != null);
    try std.testing.expect(std.mem.indexOf(u8, kt.ioctl_source, "ap.answerGet(&req, e.mac, ap.entryFlags(e.has_mac, e.perm));") != null);
}

test "udp autobind: an unbound UDP socket has no port until bind, connect or a send names it; disconnect gives an auto-picked port up (Linux measured, hello385)" {
    const up = kt.udp_port_policy;
    // The reserved port is taken unless a named socket holds it now; then the first ephemeral port nobody named holds.
    try std.testing.expectEqual(@as(?u16, 50000), up.pickAutobindPort(50000, &.{ 40000, 50001 }));
    try std.testing.expectEqual(@as(?u16, 49153), up.pickAutobindPort(50000, &.{ 50000, 49152 }));
    try std.testing.expectEqual(@as(?u16, 49152), up.pickAutobindPort(0, &.{}));
    try std.testing.expect(up.disconnectKeepsPort(true));
    try std.testing.expect(!up.disconnectKeepsPort(false));

    // udp.zig: a slot from socket() is unnamed; unnamed slots take no datagrams and hold no port against bind; naming and the
    // disconnect go through the policy.
    const us = kt.udp_source;
    try std.testing.expect(std.mem.indexOf(u8, us, "var port_named: [MAX_PORTS]bool = @splat(true);") != null);
    try std.testing.expect(std.mem.indexOf(u8, us, "var port_user_port: [MAX_PORTS]bool = @splat(false);") != null);
    try std.testing.expect(std.mem.indexOf(u8, us, "    const idx = newSlotLocked(port, is_v6, uid);\n    port_named[idx] = false;") != null);
    try std.testing.expect(std.mem.indexOf(u8, us, "pub fn autobind(key: u32, out_port: *u16, out_disc: *u16) i64 {") != null);
    try std.testing.expect(std.mem.indexOf(u8, us, "if (!policy.disconnectKeepsPort(port_user_port[i])) port_named[i] = false;") != null);
    try std.testing.expect(std.mem.indexOf(u8, us, "pub fn isNamed(key: u32) bool {") != null);
    try std.testing.expect(std.mem.count(u8, us, "if (port_ping[i] or !port_named[i]) continue;") + std.mem.count(u8, us, "if (port_ping[i] or port_v6[i] or !port_named[i]) continue;") >= 4);
    // socket_syscall.zig: every UDP send names the socket first (inet_send_prepare), connect names it, getsockname reports 0 for
    // an unnamed socket.
    const ss = kt.socket_syscall_source;
    try std.testing.expect(std.mem.count(u8, ss, "const ab = udpAutobind(&t.fd_table.fds[fd]);") >= 2);
    try std.testing.expect(std.mem.indexOf(u8, ss, "if (desc.udp_ping and !desc.udp_ping_bound) 0 else if (!desc.udp_ping and !udp.isNamed(desc.udpKey())) 0 else desc.udp_port;") != null);
}

test "route4 policy: a socket bound to 127/8 cannot send or connect out through the NIC (Linux __mkroute_output, hello386)" {
    const rp = kt.route4_policy;
    const our = [4]u8{ 10, 0, 2, 15 };
    const lb = [4]u8{ 127, 0, 0, 1 };
    try std.testing.expectEqual(@as(i64, -22), rp.loopbackSourceErrno(lb, .{ 10, 0, 2, 2 }, our, false));
    try std.testing.expectEqual(@as(i64, -22), rp.loopbackSourceErrno(lb, .{ 8, 8, 8, 8 }, our, false));
    try std.testing.expectEqual(@as(i64, -22), rp.loopbackSourceErrno(lb, .{ 10, 0, 2, 255 }, our, false));
    try std.testing.expectEqual(@as(i64, 0), rp.loopbackSourceErrno(lb, .{ 127, 9, 9, 9 }, our, false));
    try std.testing.expectEqual(@as(i64, 0), rp.loopbackSourceErrno(lb, our, our, false));
    try std.testing.expectEqual(@as(i64, 0), rp.loopbackSourceErrno(lb, .{ 255, 255, 255, 255 }, our, false));
    try std.testing.expectEqual(@as(i64, 0), rp.loopbackSourceErrno(lb, .{ 224, 0, 0, 1 }, our, false));
    try std.testing.expectEqual(@as(i64, 0), rp.loopbackSourceErrno(.{ 0, 0, 0, 0 }, .{ 10, 0, 2, 2 }, our, false));
    try std.testing.expectEqual(@as(i64, 0), rp.loopbackSourceErrno(our, lb, our, false));

    // Wired into UDP sendto / sendmsg / connect, the ping send and connect, and TCP connect, before anything is sent.
    const ss = kt.socket_syscall_source;
    // Six call sites: the ping send, sendto and sendmsg of UDP, the raw ICMP send, the UDP/ping connect and the TCP connect.
    try std.testing.expectEqual(@as(usize, 6), std.mem.count(u8, ss, "route4_policy.zig\").loopbackSourceErrno("));
}

test "devconf policy: net.ipv4.conf.<dev>.route_localnet gates the loopback-source check on the output device (Linux IN_DEV_ROUTE_LOCALNET, hello387)" {
    const dp = kt.devconf_policy;
    // Two parameters share the same path shape: the file name picks which one.
    try std.testing.expectEqual(dp.Param.proxy_arp, dp.lookup("sys/net/ipv4/conf/eth0/proxy_arp", true).?.conf_file.param);
    try std.testing.expectEqual(dp.Param.route_localnet, dp.lookup("sys/net/ipv4/conf/eth0/route_localnet", true).?.conf_file.param);
    try std.testing.expectEqual(dp.Dev.all, dp.lookup("sys/net/ipv4/conf/all/route_localnet", true).?.conf_file.dev);
    try std.testing.expect(dp.lookup("sys/net/ipv4/conf/eth0/nope", true) == null);
    try std.testing.expect(dp.lookup("sys/net/ipv4/conf/lo/route_localnet", false) != null);

    // The conf table: the output device's value or all's lets a 127/8 source out through the NIC.
    const Conf = dp.Conf;
    const off: Conf = .{};
    const eth_on: Conf = .{ .eth = 1 };
    const all_on: Conf = .{ .all = 1 };
    const lo_on: Conf = .{ .lo = 1 };
    const dflt_on: Conf = .{ .default = 1 };
    const neg: Conf = .{ .eth = -1 };
    const seven: Conf = .{ .eth = 7 };
    try std.testing.expect(!off.routeLocalnet(.eth));
    try std.testing.expect(eth_on.routeLocalnet(.eth));
    try std.testing.expect(all_on.routeLocalnet(.eth));
    try std.testing.expect(!lo_on.routeLocalnet(.eth));
    try std.testing.expect(!dflt_on.routeLocalnet(.eth));
    try std.testing.expect(neg.routeLocalnet(.eth));
    try std.testing.expect(seven.routeLocalnet(.eth));

    // route4_policy takes the switch as an argument: on, the bound 127/8 address is fine; off, EINVAL.
    const rp = kt.route4_policy;
    const our = [4]u8{ 10, 0, 2, 15 };
    const lb = [4]u8{ 127, 0, 0, 1 };
    try std.testing.expectEqual(@as(i64, -22), rp.loopbackSourceErrno(lb, .{ 10, 0, 2, 2 }, our, false));
    try std.testing.expectEqual(@as(i64, 0), rp.loopbackSourceErrno(lb, .{ 10, 0, 2, 2 }, our, true));
    try std.testing.expectEqual(@as(i64, 0), rp.loopbackSourceErrno(lb, .{ 127, 9, 9, 9 }, our, false));

    // Wiring: the six call sites pass the conf switch of the output device (the NIC here), procfs and vfs serve the new file.
    const ss = kt.socket_syscall_source;
    try std.testing.expectEqual(@as(usize, 6), std.mem.count(u8, ss, "loopbackSourceErrno("));
    try std.testing.expectEqual(@as(usize, 6), std.mem.count(u8, ss, ".loopbackAllowed()"));
    const pf = kt.procfs_source;
    try std.testing.expect(std.mem.indexOf(u8, pf, ".conf_dev_dir => &.{ .{ .name = \"proxy_arp\", .dtype = DT_REG }, .{ .name = \"route_localnet\", .dtype = DT_REG } },") != null);
    try std.testing.expect(std.mem.indexOf(u8, pf, ".conf_file => @intCast(@import(\"../net/arp.zig\").confRead(@import(\"../net/devconf_policy.zig\").decode(pid), buf[0..@min(max_len, 16)])),") != null);
    const vs = kt.vfs_source;
    try std.testing.expect(std.mem.indexOf(u8, vs, ".conf_file => @import(\"../net/arp.zig\").confWrite(@import(\"../net/devconf_policy.zig\").decode(desc.proc_pid), text),") != null);
    const as = kt.arp_source;
    try std.testing.expect(std.mem.indexOf(u8, as, "pub fn confWrite(cf: devconf.ConfFile, text: []const u8) i64 {") != null);
    try std.testing.expect(std.mem.indexOf(u8, as, "pub fn loopbackAllowed() bool {") != null);
}

