    try std.testing.expect(std.mem.indexOf(u8, ss, "return @import(\"raw_icmp.zig\").shutdown(cur.fd_table.fds[fd].raw_idx, how);") != null);
    try std.testing.expect(std.mem.indexOf(u8, ss, "if (len == 0) return -90;") == null);
    const so = kt.socket_opt_source;
    try std.testing.expect(std.mem.indexOf(u8, so, ".raw_socket => if (@import(\"raw_icmp.zig\").isV6(d.raw_idx))") != null);
    try std.testing.expect(std.mem.indexOf(u8, so, "ICMP6_FILTER") != null);
    const rs = kt.raw_icmp_source;
    try std.testing.expect(std.mem.indexOf(u8, rs, "if (s.v6) continue;") != null);
    try std.testing.expect(std.mem.indexOf(u8, rs, "policy.filterBlocks(s.filter, msg[0])") != null);
    try std.testing.expect(std.mem.indexOf(u8, kt.epoll_source, ".raw_socket => revents |= @import(\"raw_icmp.zig\").pollEvents(resource_idx),") != null);
}

test "ICMPv6 errors (hello392): hard errors map to errnos, the quote names a UDP datagram or an echo request (Linux icmpv6_err_convert)" {
    const up = kt.icmp_unreach_policy;
    const udp_want = [8]i32{ 0, 13, 0, 0, 111, 13, 13, 71 };
    for (udp_want, 0..) |w, code| {
        try std.testing.expectEqual(w, up.errnoFor6(1, @intCast(code), false));
        try std.testing.expectEqual(w, up.errnoFor6(1, @intCast(code), true));
    }
    try std.testing.expectEqual(@as(i32, 71), up.errnoFor6(1, 200, false));
    try std.testing.expectEqual(@as(i32, 90), up.errnoFor6(2, 0, false)); // packet too big: EMSGSIZE, hard for UDP
    try std.testing.expectEqual(@as(i32, 0), up.errnoFor6(2, 0, true)); // soft for a ping socket
    try std.testing.expectEqual(@as(i32, 0), up.errnoFor6(3, 0, false)); // time exceeded: soft
    for ([_]u8{ 0, 1, 2 }) |c| try std.testing.expectEqual(@as(i32, 71), up.errnoFor6(4, c, false)); // parameter problem: EPROTO
    try std.testing.expectEqual(@as(i32, 0), up.errnoFor6(5, 0, false));
    try std.testing.expectEqual(@as(i32, 0), up.errnoFor6(100, 0, false));
    try std.testing.expect(up.isError6(1) and up.isError6(4) and up.isError6(100) and up.isError6(127));
    try std.testing.expect(!up.isError6(128) and !up.isError6(129) and !up.isError6(135));

    var m: [8 + 40 + 8]u8 = @splat(0);
    m[0] = 1;
    m[1] = 4;
    m[8] = 0x60;
    m[8 + 6] = 17;
    m[8 + 39] = 2;
    std.mem.writeInt(u16, m[48..50], 40000, .big);
    std.mem.writeInt(u16, m[50..52], 9, .big);
    const u = up.parseErrorQuote6(&m).?;
    try std.testing.expect(u.kind == .udp and u.src_port == 40000 and u.dst_port == 9 and u.dst[15] == 2 and u.dst[0] == 0);
    m[8 + 6] = 58;
    m[48] = 128;
    m[49] = 0;
    std.mem.writeInt(u16, m[52..54], 0x4a8f, .big);
    const e = up.parseErrorQuote6(&m).?;
    try std.testing.expect(e.kind == .echo and e.src_port == 0x4a8f);
    m[48] = 129;
    try std.testing.expect(up.parseErrorQuote6(&m) == null);
    m[48] = 128;
    m[49] = 1;
    try std.testing.expect(up.parseErrorQuote6(&m) == null);
    m[49] = 0;
    m[8 + 6] = 6;
    try std.testing.expect(up.parseErrorQuote6(&m) == null);
    m[8 + 6] = 58;
    try std.testing.expect(up.parseErrorQuote6(m[0..55]) == null);
    m[8] = 0x40;
    try std.testing.expect(up.parseErrorQuote6(&m) == null);
}

test "ICMPv6 errors wiring (hello392): every error type reaches connected IPv6 UDP and ping sockets, a ping send reports it" {
    const vs = kt.icmpv6_source;
    const at = std.mem.indexOf(u8, vs, "if (unreach.isError6(icmp_type)) {") orelse return error.TestUnexpectedResult;
    const pt = std.mem.indexOfPos(u8, vs, at, "if (icmp_type == PACKET_TOO_BIG) handlePacketTooBig(data, len);") orelse return error.TestUnexpectedResult;
    const q = std.mem.indexOfPos(u8, vs, pt, "const q = unreach.parseErrorQuote6(data[0..len]) orelse return;") orelse return error.TestUnexpectedResult;
    const ue = std.mem.indexOfPos(u8, vs, q, "@import(\"udp.zig\").notifyIcmpError6(.{") orelse return error.TestUnexpectedResult;
    _ = std.mem.indexOfPos(u8, vs, ue, "@import(\"udp.zig\").notifyPingIcmpError6(q.src_port, .{") orelse return error.TestUnexpectedResult;
    // The error branch runs before the type switch, which no longer handles Destination Unreachable or Packet Too Big itself.
    try std.testing.expect(at < std.mem.indexOf(u8, vs, "switch (icmp_type) {").?);
    try std.testing.expect(std.mem.indexOf(u8, vs, "notifyUnreachable(") == null);
    try std.testing.expect(std.mem.indexOf(u8, vs, "PACKET_TOO_BIG => handlePacketTooBig(data, len),") == null);
    const us = kt.udp_source;
    const n6 = std.mem.indexOf(u8, us, "pub fn notifyIcmpError6(e: IcmpError6) void {") orelse return error.TestUnexpectedResult;
    _ = std.mem.indexOfPos(u8, us, n6, "if (port_ping[i] or !port_named[i] or !port_v6[i]) continue;") orelse return error.TestUnexpectedResult;
    _ = std.mem.indexOfPos(u8, us, n6, "const connected = port_peer[i] == e.peer_port and std.mem.eql(u8, &port_peer_ip[i], &e.peer_ip);") orelse return error.TestUnexpectedResult;
    // Without IPV6_RECVERR only a hard error on a socket connected to that peer is taken (errqueue_policy.route).
    try std.testing.expect(!kt.errqueue_policy.route(false, false, true).set_err);
    try std.testing.expect(!kt.errqueue_policy.route(false, true, false).set_err);
    const p6 = std.mem.indexOf(u8, us, "pub fn notifyPingIcmpError6(ident: u16, e: IcmpError6, queue: bool) void {") orelse return error.TestUnexpectedResult;
    _ = std.mem.indexOfPos(u8, us, p6, "if (!port_ping[i] or !port_v6[i] or portNumber(ports[i]) != ident) continue;") orelse return error.TestUnexpectedResult;
    const ss = kt.socket_syscall_source;
    const ps = std.mem.indexOf(u8, ss, "fn pingSend6(d: *vfs_mod.FileDescriptor") orelse return error.TestUnexpectedResult;
    const pend = std.mem.indexOfPos(u8, ss, ps, "const pending = udp.takePendingError(d.udpKey());") orelse return error.TestUnexpectedResult;
    try std.testing.expect(pend < std.mem.indexOfPos(u8, ss, ps, "const sent = @import(\"icmpv6.zig\").sendProto6Ov(").?);
}

test "ICMPv6 error quotes skip extension headers (hello393): hop-by-hop, routing, destination options, AH and a first fragment (Linux ipv6_skip_exthdr)" {
    const up = kt.icmp_unreach_policy;
    for ([_]u8{ 0, 43, 44, 51, 59, 60 }) |h| try std.testing.expect(up.isExtHdr6(h));
    for ([_]u8{ 6, 17, 41, 50, 58, 135 }) |h| try std.testing.expect(!up.isExtHdr6(h));

    // ICMPv6 header, IPv6 header (next header 0), hop-by-hop 8 bytes -> destination options 16 bytes -> fragment 8 bytes -> UDP.
    var m: [8 + 40 + 8 + 16 + 8 + 8]u8 = @splat(0);
    m[0] = 1;
    m[1] = 4;
    m[8] = 0x60;
    m[8 + 6] = 0;
    m[8 + 39] = 1;
    m[48] = 60; // hop-by-hop: next destination options, length 0 -> 8 bytes
    m[56] = 44; // destination options: next fragment, length 1 -> 16 bytes
    m[57] = 1;
    m[72] = 17; // fragment: next UDP, offset 0 with M set (a first fragment)
    m[75] = 1;
    std.mem.writeInt(u16, m[80..82], 40000, .big);
    std.mem.writeInt(u16, m[82..84], 9, .big);
    const s = up.skipExtHdr6(m[8..], 40, 0).?;
    try std.testing.expectEqual(@as(usize, 72), s.off);
    try std.testing.expectEqual(@as(u8, 17), s.nh);
    const u = up.parseErrorQuote6(&m).?;
    try std.testing.expect(u.kind == .udp and u.src_port == 40000 and u.dst_port == 9 and u.dst[15] == 1);
    // A later fragment (offset 8 units) carries no transport header: the walk stops at the fragment header.
    m[74] = 0;
    m[75] = 8 << 3;
    try std.testing.expectEqual(@as(u8, 44), up.skipExtHdr6(m[8..], 40, 0).?.nh);
    try std.testing.expect(up.parseErrorQuote6(&m) == null);
    m[75] = 1;
    // "No next header" ends the walk with nothing.
    m[56] = 59;
    try std.testing.expect(up.skipExtHdr6(m[8..], 40, 0) == null);
    try std.testing.expect(up.parseErrorQuote6(&m) == null);
    m[56] = 44;
    // A quote cut inside the transport header, or inside an extension header, is not parsed.
    try std.testing.expect(up.parseErrorQuote6(m[0 .. m.len - 1]) == null);
    try std.testing.expect(up.skipExtHdr6(m[8..60], 40, 0) == null);
    // Routing header (next 43), and AH whose length counts 4-byte units plus 2: (1 + 2) * 4 = 12 bytes.
    var r: [8 + 40 + 8 + 12 + 8]u8 = @splat(0);
    r[8] = 0x60;
    r[8 + 6] = 43;
    r[48] = 51;
    r[56] = 58;
    r[57] = 1;
    r[68] = 128;
    std.mem.writeInt(u16, r[72..74], 0x1234, .big);
    const e = up.parseErrorQuote6(&r).?;
    try std.testing.expect(e.kind == .echo and e.src_port == 0x1234);
}

