test "raw ICMP queue is a ring and MSG_PEEK leaves the head (hello398)" {
    const rp = kt.raw_icmp_policy;
    try std.testing.expectEqual(@as(?u8, 0), rp.enqueueSlot(0, 0));
    try std.testing.expectEqual(@as(?u8, 3), rp.enqueueSlot(1, 2));
    try std.testing.expectEqual(@as(?u8, 1), rp.enqueueSlot(6, 3));
    try std.testing.expectEqual(@as(?u8, null), rp.enqueueSlot(5, rp.QUEUE_DEPTH));
    const peeked = rp.afterRecv(2, 3, true);
    try std.testing.expectEqual(@as(u8, 2), peeked.head);
    try std.testing.expectEqual(@as(u8, 3), peeked.count);
    const taken = rp.afterRecv(7, 3, false);
    try std.testing.expectEqual(@as(u8, 0), taken.head);
    try std.testing.expectEqual(@as(u8, 2), taken.count);
    // Request A and reply A queue, A is read, request B arrives: B goes behind reply A, which the next read gets.
    var head: u8 = 0;
    var count: u8 = 2;
    const after_a = rp.afterRecv(head, count, false);
    head = after_a.head;
    count = after_a.count;
    try std.testing.expectEqual(@as(?u8, 2), rp.enqueueSlot(head, count));
    try std.testing.expectEqual(@as(u8, 1), head);
    const rs = kt.raw_icmp_source;
    try std.testing.expect(std.mem.indexOf(u8, rs, "pub fn recv(idx: u32, out: []u8, peek: bool) RecvResult {") != null);
    // hello475: the ring became a kmalloc'd list, oldest first; MSG_PEEK still leaves the head.
    try std.testing.expect(std.mem.indexOf(u8, rs, "const e = newEntry(s) orelse continue;") != null);
    try std.testing.expect(std.mem.indexOf(u8, rs, "    if (!peek) popEntry(s);") != null);
    const ss = kt.socket_syscall_source;
    try std.testing.expect(std.mem.indexOf(u8, ss, "switch (raw.recv(d.raw_idx, out, (flags & 0x02) != 0)) {") != null);
}

test "ICMP_FILTER on IPv4 raw ICMP sockets (hello399): a set bit blocks that type below 32 (Linux icmp_filter)" {
    const rp = kt.raw_icmp_policy;
    try std.testing.expect(!rp.icmpFilterBlocks(0, 8));
    try std.testing.expect(rp.icmpFilterBlocks(1 << 8, 8));
    try std.testing.expect(!rp.icmpFilterBlocks(1 << 8, 0));
    try std.testing.expect(rp.icmpFilterBlocks(0x8000_0000, 31));
    try std.testing.expect(!rp.icmpFilterBlocks(0xffff_ffff, 32));
    try std.testing.expect(!rp.icmpFilterBlocks(0xffff_ffff, 255));
    // The ICMP type sits at the IP header's length into the datagram; a datagram too short to hold it passes (no ICMP header).
    var dg: [28]u8 = @splat(0);
    dg[0] = 0x45;
    dg[20] = 8;
    try std.testing.expectEqual(@as(?u8, 8), rp.icmpTypeOf(&dg));
    try std.testing.expectEqual(@as(?u8, null), rp.icmpTypeOf(dg[0..20]));
    dg[0] = 0x46;
    try std.testing.expectEqual(@as(?u8, null), rp.icmpTypeOf(dg[0..24]));
    // setsockopt takes at most 4 bytes over the current mask, little-endian.
    try std.testing.expectEqual(@as(u32, 0x1111_bbaa), rp.setIcmpFilter(0x1111_1111, &.{ 0xaa, 0xbb }));
    try std.testing.expectEqual(@as(u32, 0x0403_0201), rp.setIcmpFilter(0, &.{ 1, 2, 3, 4, 5, 6 }));
    const rs = kt.raw_icmp_source;
    try std.testing.expect(std.mem.indexOf(u8, rs, "if (icmpType(hdr, payload)) |ty| if (policy.icmpFilterBlocks(s.icmp_filter, ty)) continue;") != null);
    const so = kt.socket_opt_source;
    try std.testing.expect(std.mem.indexOf(u8, so, "if (!v6 and optname == ICMP_FILTER) return .icmp_filter;\n        if (v6 and optname == IPV6_CHECKSUM) return .checksum_raw;\n        return .noprotoopt;") != null);
    try std.testing.expect(std.mem.indexOf(u8, so, "if (which != .checksum and which != .checksum_raw and which != .hdrincl6 and @as(i32, @bitCast(user_len)) < 0) return -22;") != null);
    try std.testing.expect(std.mem.indexOf(u8, so, "bo.writeU32Le(val[0..4], @import(\"raw_icmp.zig\").getIcmpFilter(idx));") != null);
}

test "getsockopt / setsockopt at a level the socket does not know (hello400): EOPNOTSUPP or ENOPROTOOPT as Linux answers" {
    const ip = kt.ip_opt_policy;
    // IPv4 inet sockets: ip_getsockopt is EOPNOTSUPP for a level other than SOL_IP, ip_setsockopt ENOPROTOOPT.
    try std.testing.expectEqual(@as(i64, -95), ip.unknownLevelErrno(.inet4, true));
    try std.testing.expectEqual(@as(i64, -92), ip.unknownLevelErrno(.inet4, false));
    // IPv6: ipv6_getsockopt / ipv6_setsockopt are ENOPROTOOPT.
    try std.testing.expectEqual(@as(i64, -92), ip.unknownLevelErrno(.inet6, true));
    try std.testing.expectEqual(@as(i64, -92), ip.unknownLevelErrno(.inet6, false));
    // AF_UNIX has no ops->getsockopt / setsockopt: EOPNOTSUPP both ways (do_sock_getsockopt / do_sock_setsockopt).
    try std.testing.expectEqual(@as(i64, -95), ip.unknownLevelErrno(.unix, true));
    try std.testing.expectEqual(@as(i64, -95), ip.unknownLevelErrno(.unix, false));
    const so = kt.socket_opt_source;
    try std.testing.expect(std.mem.indexOf(u8, so, "if (level != SOL_SOCKET and level != SOL_TCP) return unknownLevel(ref, resolved_v6, false);") != null);
    try std.testing.expect(std.mem.indexOf(u8, so, "if (level != SOL_SOCKET and level != SOL_TCP) return unknownLevel(ref, v6, true);") != null);
    try std.testing.expect(std.mem.indexOf(u8, so, "if (level != SOL_SOCKET) return unknownLevel(ref, v6, true);") != null);
    // A UNIX socket at SOL_IP / SOL_IPV6 is EOPNOTSUPP too; an IPv6 socket's SOL_IP get stays ENOPROTOOPT.
    try std.testing.expect(std.mem.indexOf(u8, so, "const fam = socketFamily(ref, v6_hint) orelse return unknownLevel(ref, v6_hint, true);") != null);
    try std.testing.expect(std.mem.indexOf(u8, so, "const fam = socketFamily(ref, v6_hint) orelse return unknownLevel(ref, v6_hint, false);") != null);
    // UDP's own level (SOL_UDP / SOL_UDPLITE, udp_lib_getsockopt): an option it does not know is ENOPROTOOPT, not EOPNOTSUPP.
    try std.testing.expect(std.mem.indexOf(u8, so, "if (ref == .udp and (ref.udp & @import(\"udp.zig\").PING_KEY) == 0 and (level == SOL_UDP or level == SOL_UDPLITE)) return -92;") != null);
    // SOL_ICMPV6 on an IPv4 raw socket goes to ip_getsockopt / ip_setsockopt like any other level it does not know.
    try std.testing.expect(std.mem.indexOf(u8, so, "if (level == SOL_ICMPV6) return if (!v6) null else if (optname == ICMP6_FILTER) .filter else .icmpv6_level;") != null);
}

test "IPv4 raw sockets of any protocol (hello401): creation, delivery and protocol unreachable (Linux raw_v4_input)" {
    const rp = kt.raw_icmp_policy;
    try std.testing.expectEqual(@as(i64, -93), rp.protocolErrno(0));
    try std.testing.expectEqual(@as(i64, 0), rp.protocolErrno(6));
    try std.testing.expectEqual(@as(i64, 0), rp.protocolErrno(253));
    try std.testing.expectEqual(@as(i64, 0), rp.protocolErrno(255));
    try std.testing.expectEqual(@as(i64, -93), rp.protocolErrno(256));
    try std.testing.expectEqual(@as(i64, -22), rp.protocolErrno(263));
    try std.testing.expectEqual(@as(i64, -22), rp.protocolErrno(0xffff_ffff));
    // IPPROTO_RAW starts with IP_HDRINCL (inet_create).
    try std.testing.expect(rp.startsHdrincl(255));
    try std.testing.expect(!rp.startsHdrincl(253));
    // getsockname's port is the protocol.
    const n = rp.sockName(.{ 127, 0, 0, 1 }, 253);
    try std.testing.expectEqual(@as(u8, 253), n[3]);
    try std.testing.expectEqual(@as(u8, 0), n[2]);
    // A send that is not ICMP needs no ICMP header: 0 and 1 bytes are fine (raw_probe_proto_opt reads 2 bytes for ICMP only).
    try std.testing.expectEqual(@as(i64, 0), rp.sendLengthErrno(253, 0));
    try std.testing.expectEqual(@as(i64, 0), rp.sendLengthErrno(253, 1));
    try std.testing.expectEqual(@as(i64, -14), rp.sendLengthErrno(1, 1));
    // ip_protocol_deliver_rcu: protocol unreachable for a local datagram no handler and no raw socket took, never for ICMP, TCP, UDP.
    try std.testing.expect(rp.protoUnreachable(252, false));
    try std.testing.expect(!rp.protoUnreachable(252, true));
    try std.testing.expect(!rp.protoUnreachable(1, false));
    try std.testing.expect(!rp.protoUnreachable(6, false));
    try std.testing.expect(!rp.protoUnreachable(17, false));
    // ICMP_FILTER only on an IPPROTO_ICMP socket: EOPNOTSUPP on any other (do_raw_setsockopt).
    try std.testing.expectEqual(@as(i64, -95), rp.icmpFilterErrno(253));
    try std.testing.expectEqual(@as(i64, 0), rp.icmpFilterErrno(1));
    const m = kt.net_mod_source;
    // Every IPv4 datagram reaches the raw sockets of its protocol before the protocol handler (raw_local_deliver first).
    const at_raw = std.mem.indexOf(u8, m, "@import(\"raw_icmp.zig\").deliverInfo(info.protocol, data[14 .. payload_start + info.payload_len], info.src_ip, info.dst_ip, meta4)\n            else\n                @import(\"raw_icmp.zig\").deliverHdr(") orelse return error.TestUnexpectedResult;
    const at_tcp = std.mem.indexOf(u8, m, "tcp.handlePacketOpts(info.src_ip, info.dst_ip, data + payload_start, info.payload_len, info.ecn_ce, rx_opts, .{ .ifindex = ifindex, .ttl = info.ttl, .tos = info.tos });").?;
    try std.testing.expect(at_raw < at_tcp);
    try std.testing.expect(std.mem.indexOf(u8, m, "else => if (rp.protoUnreachable(info.protocol, raw_took)) icmp.sendProtoUnreachable(data[14 .. payload_start + info.payload_len], info.src_ip, info.dst_ip),") != null);
    const rs = kt.raw_icmp_source;
    try std.testing.expect(std.mem.indexOf(u8, rs, "if (s.protocol != protocol) continue;") != null);
    try std.testing.expect(std.mem.indexOf(u8, rs, "if (protocol == policy.IPPROTO_ICMP) if (icmpType(hdr, payload)) |ty| if (policy.icmpFilterBlocks(s.icmp_filter, ty)) continue;") != null);
    const ss = kt.socket_syscall_source;
    try std.testing.expect(std.mem.indexOf(u8, ss, "const idx = raw.open(v6, protocol) orelse return -105; // ENOBUFS") != null);
    const so = kt.socket_opt_source;
    try std.testing.expect(std.mem.indexOf(u8, so, "facts.id.protocol = @import(\"raw_icmp.zig\").protocolOf(idx);") != null);
}

test "IP_HDRINCL id 0 is chosen unless DF (hello402): Linux raw_send_hdrinc / ip_select_ident" {
    const rp = kt.raw_icmp_policy;
    var p: [24]u8 = @splat(0);
    p[0] = 0x45;
    // No DF, id 0: the generator's value goes in, and the checksum covers it.
    try std.testing.expect(rp.needsIdent(&p));
    rp.completeHdrinclId(&p, .{ 127, 0, 0, 1 }, 0xbeef);
    try std.testing.expectEqual(@as(u8, 0xbe), p[4]);
    try std.testing.expectEqual(@as(u8, 0xef), p[5]);
    try std.testing.expectEqual(@as(u16, 0), rp.headerSum(p[0..20]));
    // DF set: id 0 stays 0 (ip_select_ident_segs).
    var q: [24]u8 = @splat(0);
    q[0] = 0x45;
    q[6] = 0x40;
    try std.testing.expect(!rp.needsIdent(&q));
    rp.completeHdrinclId(&q, .{ 127, 0, 0, 1 }, 0xbeef);
    try std.testing.expectEqual(@as(u8, 0), q[4]);
    try std.testing.expectEqual(@as(u8, 0), q[5]);
    // A given id is kept.
    var g: [24]u8 = @splat(0);
    g[0] = 0x45;
    g[4] = 0x12;
    g[5] = 0x34;
    try std.testing.expect(!rp.needsIdent(&g));
    rp.completeHdrinclId(&g, .{ 127, 0, 0, 1 }, 0xbeef);
    try std.testing.expectEqual(@as(u8, 0x12), g[4]);
    try std.testing.expectEqual(@as(u8, 0x34), g[5]);
    const rs = kt.raw_icmp_source;
    try std.testing.expect(std.mem.indexOf(u8, rs, "policy.completeHdrinclId(pkt_buf[14..][0..pkt.len], src, if (policy.needsIdent(pkt)) ipid.globalNonzero(dst, src, pkt[9]) else 0);") != null);
}

test "IPv6 raw sockets of any protocol (hello403): creation, IPV6_CHECKSUM, delivery (Linux inet6_create / rawv6_sendmsg / rawv6_rcv)" {
    const rp = kt.raw_icmp_policy;
    // inet6_create: any protocol but IPPROTO_IP.
    try std.testing.expectEqual(@as(i64, 0), rp.protocolErrno6(58));
    try std.testing.expectEqual(@as(i64, 0), rp.protocolErrno6(253));
    try std.testing.expectEqual(@as(i64, 0), rp.protocolErrno6(6));
    try std.testing.expectEqual(@as(i64, -93), rp.protocolErrno6(0));
    try std.testing.expectEqual(@as(i64, 0), rp.protocolErrno6(255)); // hello404: IPPROTO_RAW, with IPV6_HDRINCL
    try std.testing.expectEqual(@as(i64, -93), rp.protocolErrno6(256));
    try std.testing.expectEqual(@as(i64, -22), rp.protocolErrno6(263));
    try std.testing.expectEqual(@as(i64, -22), rp.protocolErrno6(0xffff_ffff));
    // rawv6_init_sk: ICMPv6 sums at offset 2, MH at 4, anything else not at all.
    try std.testing.expectEqual(@as(?u32, 2), rp.initialChecksum6(58));
    try std.testing.expectEqual(@as(?u32, 4), rp.initialChecksum6(135));
    try std.testing.expectEqual(@as(?u32, null), rp.initialChecksum6(253));
    // rawv6_sendmsg: sin6_port is the protocol, 0 meaning the socket's own.
    try std.testing.expectEqual(@as(i64, 0), rp.sendtoErrno6(true, 28, 10, 253, false, 253));
    try std.testing.expectEqual(@as(i64, 0), rp.sendtoErrno6(true, 28, 10, 0, false, 253));
    try std.testing.expectEqual(@as(i64, -22), rp.sendtoErrno6(true, 28, 10, 17, false, 253));
    try std.testing.expectEqual(@as(i64, -22), rp.sendtoErrno6(true, 28, 10, 58, false, 253));
    // The length: ICMPv6 needs its type and code (EFAULT); with a checksum offset, offset >= len - 1 is EINVAL.
    try std.testing.expectEqual(@as(i64, -14), rp.lengthErrno6(58, 2, 1));
    try std.testing.expectEqual(@as(i64, -22), rp.lengthErrno6(58, 2, 3));
    try std.testing.expectEqual(@as(i64, 0), rp.lengthErrno6(58, 2, 4));
    try std.testing.expectEqual(@as(i64, 0), rp.lengthErrno6(253, null, 0));
    try std.testing.expectEqual(@as(i64, -22), rp.lengthErrno6(253, 4, 5));
    try std.testing.expectEqual(@as(i64, 0), rp.lengthErrno6(253, 4, 6));
    try std.testing.expectEqual(@as(i64, -22), rp.lengthErrno6(253, 0, 0));
    try std.testing.expectEqual(@as(i64, -22), rp.lengthErrno6(253, 0, 1));
    try std.testing.expectEqual(@as(i64, 0), rp.lengthErrno6(253, 0, 2));
    // IPV6_CHECKSUM (do_rawv6_setsockopt): not at SOL_IPV6 on ICMPv6 (SOL_RAW may), no odd offset, a negative value turns it off.
    try std.testing.expectEqual(@as(i64, -22), rp.checksumOptErrno(58, false, 4));
    try std.testing.expectEqual(@as(i64, 0), rp.checksumOptErrno(58, true, 4));
    try std.testing.expectEqual(@as(i64, -22), rp.checksumOptErrno(253, false, 3));
    try std.testing.expectEqual(@as(i64, 0), rp.checksumOptErrno(253, false, 4));
    try std.testing.expectEqual(@as(i64, 0), rp.checksumOptErrno(253, false, -1));
    try std.testing.expectEqual(@as(i64, 0), rp.checksumOptErrno(253, false, -3));
    try std.testing.expectEqual(@as(?u32, null), rp.checksumOptValue(-1));
    try std.testing.expectEqual(@as(?u32, 4), rp.checksumOptValue(4));
    try std.testing.expectEqual(@as(i32, -1), rp.checksumOptRead(null));
    try std.testing.expectEqual(@as(i32, 2), rp.checksumOptRead(2));
    // The RFC 2460 sum over the pseudo-header (next header = the socket's protocol) and the message.
    var l6: [16]u8 = @splat(0);
    l6[15] = 1;
    var msg = [_]u8{ 1, 2, 3, 4, 0, 0, 7, 8 };
    const sum = rp.sum6(l6, l6, 253, &msg);
    try std.testing.expectEqual(@as(u16, 0xf3ea), sum);
    msg[4] = @truncate(sum >> 8);
    msg[5] = @truncate(sum);
    try std.testing.expectEqual(@as(u16, 0), rp.sum6(l6, l6, 253, &msg));
    try std.testing.expect(rp.sum6(l6, l6, 254, &msg) != 0);
    var odd = [_]u8{ 1, 2, 3 };
    try std.testing.expectEqual(@as(u16, ~@as(u16, 0x0102 + 0x0300 + 1 + 1 + 3 + 253)), rp.sum6(l6, l6, 253, &odd));
    // A UDP sum of 0 goes out as 0xffff (CSUM_MANGLED_0), any other protocol's as 0.
    try std.testing.expectEqual(@as(u16, 0xffff), rp.finishSum6(0, 17));
    try std.testing.expectEqual(@as(u16, 0), rp.finishSum6(0, 253));
    try std.testing.expectEqual(@as(u16, 0x1234), rp.finishSum6(0x1234, 17));
    // getsockname's port is the protocol; ICMP6_FILTER is EOPNOTSUPP unless the socket is ICMPv6.
    try std.testing.expectEqual(@as(u8, 253), rp.sockName6(l6, 253)[3]);
    try std.testing.expectEqual(@as(i64, -95), rp.icmp6FilterErrno(253));
    try std.testing.expectEqual(@as(i64, 0), rp.icmp6FilterErrno(58));
    const rs = kt.raw_icmp_source;
    try std.testing.expect(std.mem.count(u8, rs, "if (s.protocol != protocol) continue;") >= 2);
    try std.testing.expect(std.mem.indexOf(u8, rs, "if (s.csum_off != null and policy.sum6(src, dst, s.protocol, msg) != 0) continue;") != null);
    try std.testing.expect(std.mem.indexOf(u8, rs, "if (protocol == policy.IPPROTO_ICMPV6 and (msg.len < 4 or policy.filterBlocks(s.filter, msg[0]))) continue;") != null);
    const ss = kt.socket_syscall_source;
    try std.testing.expect(std.mem.indexOf(u8, ss, "const lrc = rp.lengthErrno6(raw.protocolOf(d.raw_idx), raw.checksumOffset(d.raw_idx), msg.len);") != null);
}

test "IPV6_HDRINCL, IPPROTO_RAW and the ICMPv6 parameter problem (hello404): Linux rawv6_send_hdrinc / ip6_protocol_deliver_rcu" {
    const rp = kt.raw_icmp_policy;
    // inet6_create: IPPROTO_RAW is a raw socket and starts with HDRINCL (the same bit IP_HDRINCL sets).
    try std.testing.expectEqual(@as(i64, 0), rp.protocolErrno6(255));
    try std.testing.expectEqual(@as(i64, -93), rp.protocolErrno6(256));
    try std.testing.expect(rp.startsHdrincl(255));
    // rawv6_send_hdrinc: past the device MTU is EMSGSIZE, shorter than an IPv6 header EINVAL.
    try std.testing.expectEqual(@as(i64, -90), rp.hdrinclErrno6(1501, 1500));
    try std.testing.expectEqual(@as(i64, 0), rp.hdrinclErrno6(1500, 1500));
    try std.testing.expectEqual(@as(i64, 0), rp.hdrinclErrno6(40, 1500));
    try std.testing.expectEqual(@as(i64, -22), rp.hdrinclErrno6(39, 1500));
    try std.testing.expectEqual(@as(i64, -22), rp.hdrinclErrno6(0, 1500));
    // rawv6_sendmsg: an IPPROTO_RAW socket takes any sin6_port up to 255; past 255 is EINVAL for every socket.
    try std.testing.expectEqual(@as(i64, 0), rp.sendtoErrno6(true, 28, 10, 17, false, 255));
    try std.testing.expectEqual(@as(i64, -22), rp.sendtoErrno6(true, 28, 10, 256, false, 255));
    try std.testing.expectEqual(@as(i64, -22), rp.sendtoErrno6(true, 28, 10, 17, false, 253));
    try std.testing.expectEqual(@as(i64, 0), rp.sendtoErrno6(true, 28, 10, 253, false, 253));
    // ip6_protocol_deliver_rcu: a next header with no handler that no raw socket took gets a parameter problem; ICMPv6, TCP, UDP and
    // the headers Linux handles itself (hop-by-hop, routing, fragment, AH, no next header, destination options) never do.
    try std.testing.expect(rp.paramProblem6(252, false));
    try std.testing.expect(rp.paramProblem6(255, false));
    try std.testing.expect(!rp.paramProblem6(252, true));
    for ([_]u8{ 6, 17, 58, 0, 43, 44, 51, 59, 60 }) |nh| try std.testing.expect(!rp.paramProblem6(nh, false));
    // The message: type 4 code 1, the pointer at the next-header field (offset 6), then as much of the packet as fits 1280 bytes.
    var pkt: [44]u8 = @splat(0);
    pkt[0] = 0x60;
    pkt[6] = 252;
    var out: [rp.PARAM_PROBLEM_MAX]u8 = undefined;
    const n = rp.paramProblemMsg(&out, &pkt);
    try std.testing.expectEqual(@as(usize, 52), n);
    try std.testing.expectEqualSlices(u8, &[_]u8{ 4, 1, 0, 0, 0, 0, 0, 6 }, out[0..8]);
    try std.testing.expectEqualSlices(u8, &pkt, out[8..52]);
    const big: [1400]u8 = @splat(0x5a);
    try std.testing.expectEqual(@as(usize, 1240), rp.paramProblemMsg(&out, &big));
    try std.testing.expectEqual(@as(usize, 1240), rp.PARAM_PROBLEM_MAX);
    const m = kt.net_mod_source;
    // hello410: the next header after any extension headers decides, and the pointer names the field that named it.
    try std.testing.expect(std.mem.indexOf(u8, m, "const raw_took6 = raw6.deliver6Skb(ext.nh, data[up_start .. up_start + up_len], info6.src_ip, info6.dst_ip, ifindex, info6.hop_limit, info6.tclass, info6.flowinfo, skb);") != null);
    const rs = kt.raw_icmp_source;
    try std.testing.expect(std.mem.indexOf(u8, rs, "if (policy.startsHdrincl(protocol)) s.opts.ip.hdrincl = true;") != null);
    const ss = kt.socket_syscall_source;
    try std.testing.expect(std.mem.indexOf(u8, ss, "const hs = raw.sendHdrincl6(to6, msg);") != null);
    const so = kt.socket_opt_source;
    try std.testing.expect(std.mem.indexOf(u8, so, "if (v6 and level == ipo.SOL_IPV6 and optname == IPV6_HDRINCL) return .hdrincl6;") != null);
}

test "IPv4 neighbour unreachability detection (hello405): STALE, DELAY, PROBE, FAILED (Linux neigh_timer_handler)" {
    const ap = kt.arp_policy;
    const s: u64 = 1_000_000_000;
    // SIOCSARP leaves an ordinary entry STALE (arp_req_set); nothing sent to it, it stays so.
    var e = ap.NudEntry.init(.stale, 0);
    try std.testing.expectEqual(ap.TickAction.none, ap.onTick(&e, 100 * s));
    try std.testing.expectEqual(ap.Nud.stale, e.state);
    // A send moves it to DELAY (__neigh_event_send); DELAY_PROBE_TIME later, unconfirmed, it is PROBE and asks at once.
    ap.onUse(&e, 100 * s);
    try std.testing.expectEqual(ap.Nud.delay, e.state);
    try std.testing.expectEqual(ap.TickAction.none, ap.onTick(&e, 104 * s));
    try std.testing.expectEqual(ap.TickAction.probe, ap.onTick(&e, 105 * s));
    try std.testing.expectEqual(ap.Nud.probe, e.state);
    // A probe each RETRANS_TIME; after UCAST_PROBES unanswered ones it is FAILED (neigh_invalidate).
    try std.testing.expectEqual(ap.TickAction.none, ap.onTick(&e, 105 * s + s / 2));
    try std.testing.expectEqual(ap.TickAction.probe, ap.onTick(&e, 106 * s));
    try std.testing.expectEqual(ap.TickAction.probe, ap.onTick(&e, 107 * s));
    try std.testing.expectEqual(ap.TickAction.failed, ap.onTick(&e, 108 * s));
    try std.testing.expectEqual(ap.Nud.failed, e.state);
    try std.testing.expect(!ap.usable(e.state));
    try std.testing.expectEqual(ap.TickAction.none, ap.onTick(&e, 200 * s));
    // A unicast reply in PROBE makes it REACHABLE; REACHABLE_TIME later it is STALE again.
    var p = ap.NudEntry.init(.stale, 0);
    ap.onUse(&p, 0);
    _ = ap.onTick(&p, 5 * s);
    ap.onReceive(&p, 5 * s + 1, true, true);
    try std.testing.expectEqual(ap.Nud.reachable, p.state);
    try std.testing.expectEqual(ap.TickAction.none, ap.onTick(&p, 5 * s + ap.REACHABLE_NS - 1));
    try std.testing.expectEqual(ap.Nud.reachable, p.state);
    _ = ap.onTick(&p, 5 * s + 1 + ap.REACHABLE_NS);
    try std.testing.expectEqual(ap.Nud.stale, p.state);
    // A use of a REACHABLE, DELAY or PROBE entry changes nothing.
    var r = ap.NudEntry.init(.reachable, 0);
    ap.onUse(&r, 1);
    try std.testing.expectEqual(ap.Nud.reachable, r.state);
    // DELAY with a confirmation since the send goes back to REACHABLE, without a probe.
    var d = ap.NudEntry.init(.stale, 0);
    ap.onUse(&d, 10 * s);
    ap.onReceive(&d, 12 * s, true, true);
    try std.testing.expectEqual(ap.Nud.reachable, d.state);
    // A request (or a broadcast reply) with the same MAC leaves a usable entry's state alone; a new MAC, or one for an entry without
    // a usable MAC, makes it STALE (arp_process: NUD_STALE; neigh_update keeps the old state when nothing changes).
    var q = ap.NudEntry.init(.reachable, 0);
    ap.onReceive(&q, 1, false, true);
    try std.testing.expectEqual(ap.Nud.reachable, q.state);
    ap.onReceive(&q, 2, false, false);
    try std.testing.expectEqual(ap.Nud.stale, q.state);
    var f = ap.NudEntry.init(.failed, 0);
    ap.onReceive(&f, 3, false, true);
    try std.testing.expectEqual(ap.Nud.stale, f.state);
    var inc = ap.NudEntry.init(.incomplete, 0);
    ap.onReceive(&inc, 3, true, false);
    try std.testing.expectEqual(ap.Nud.reachable, inc.state);
    // A permanent entry never ages.
    var pm = ap.NudEntry.init(.permanent, 0);
    ap.onUse(&pm, 0);
    try std.testing.expectEqual(ap.TickAction.none, ap.onTick(&pm, 1000 * s));
    try std.testing.expectEqual(ap.Nud.permanent, pm.state);
    for ([_]ap.Nud{ .reachable, .stale, .delay, .probe, .permanent }) |st| try std.testing.expect(ap.usable(st));
    try std.testing.expect(!ap.usable(.incomplete));
    // The unicast probe (arp_solicit with the cached MAC): an ARP request sent to that MAC, target hardware address zero.
    var pkt: [42]u8 = undefined;
    ap.buildRequest(&pkt, .{ 2, 0, 0, 0, 0, 0x60 }, .{ 0x52, 0x54, 0, 0x12, 0x34, 0x56 }, .{ 10, 0, 2, 15 }, .{ 10, 0, 2, 96 });
    try std.testing.expectEqualSlices(u8, &[_]u8{ 2, 0, 0, 0, 0, 0x60, 0x52, 0x54, 0, 0x12, 0x34, 0x56, 8, 6 }, pkt[0..14]);
    try std.testing.expectEqualSlices(u8, &[_]u8{ 0, 1, 8, 0, 6, 4, 0, 1 }, pkt[14..22]);
    try std.testing.expectEqualSlices(u8, &[_]u8{ 10, 0, 2, 15 }, pkt[28..32]);
    try std.testing.expect(std.mem.allEqual(u8, pkt[32..38], 0));
    try std.testing.expectEqualSlices(u8, &[_]u8{ 10, 0, 2, 96 }, pkt[38..42]);
    const as = kt.arp_source;
    try std.testing.expect(std.mem.indexOf(u8, as, "policy.onUse(&cache[i].nud, nowNs());") != null);
    try std.testing.expect(std.mem.indexOf(u8, as, "switch (policy.onTick(&cache[i].nud, now)) {") != null);
    try std.testing.expect(std.mem.indexOf(u8, as, "addToCache(sender_ip, sender_mac, opcode == 2 and std.mem.eql(u8, data[0..6], &netif.getMac()));") != null);
}

test "ICMP errors for TCP (hello406): errno, the sequence window, hard in SYN_SENT and soft once connected (Linux tcp_v4_err / tcp_v6_err)" {
    const up = kt.icmp_unreach_policy;
    // tcp_v4_err: destination unreachable through icmp_err_convert (fragmentation needed is path MTU only, past 15 nothing),
    // time exceeded EHOSTUNREACH, parameter problem EPROTO; source quench and redirect nothing.
    try std.testing.expectEqual(@as(i32, 101), up.tcpErrno(3, 0));
    try std.testing.expectEqual(@as(i32, 113), up.tcpErrno(3, 1));
    try std.testing.expectEqual(@as(i32, 92), up.tcpErrno(3, 2));
    try std.testing.expectEqual(@as(i32, 111), up.tcpErrno(3, 3));
    try std.testing.expectEqual(@as(i32, 0), up.tcpErrno(3, 4));
    try std.testing.expectEqual(@as(i32, 113), up.tcpErrno(3, 15));
    try std.testing.expectEqual(@as(i32, 0), up.tcpErrno(3, 16));
    try std.testing.expectEqual(@as(i32, 113), up.tcpErrno(11, 0));
    try std.testing.expectEqual(@as(i32, 71), up.tcpErrno(12, 0));
    try std.testing.expectEqual(@as(i32, 0), up.tcpErrno(4, 0));
    try std.testing.expectEqual(@as(i32, 0), up.tcpErrno(5, 1));
    // tcp_v6_err / icmpv6_err_convert: every destination unreachable code (an unknown one EPROTO), time exceeded, parameter
    // problem; packet too big is path MTU only.
    try std.testing.expectEqual(@as(i32, 111), up.tcpErrno6(1, 4));
    try std.testing.expectEqual(@as(i32, 101), up.tcpErrno6(1, 0));
    try std.testing.expectEqual(@as(i32, 13), up.tcpErrno6(1, 1));
    try std.testing.expectEqual(@as(i32, 113), up.tcpErrno6(1, 3));
    try std.testing.expectEqual(@as(i32, 71), up.tcpErrno6(1, 7));
    try std.testing.expectEqual(@as(i32, 113), up.tcpErrno6(3, 0));
    try std.testing.expectEqual(@as(i32, 71), up.tcpErrno6(4, 0));
    try std.testing.expectEqual(@as(i32, 0), up.tcpErrno6(2, 0));
    // The quoted segment's sequence number must lie in [snd_una, snd_nxt] (between), wrapping included.
    try std.testing.expect(up.tcpSeqOk(100, 100, 101));
    try std.testing.expect(up.tcpSeqOk(101, 100, 101));
    try std.testing.expect(!up.tcpSeqOk(99, 100, 101));
    try std.testing.expect(!up.tcpSeqOk(102, 100, 101));
    try std.testing.expect(up.tcpSeqOk(2, 0xffff_fff0, 5));
    // What the error does: SYN_SENT and SYN_RECEIVED end the connection, any other state only keeps it as the soft error.
    try std.testing.expectEqual(up.TcpErrAction.abort, up.tcpErrAction(.syn_sent));
    try std.testing.expectEqual(up.TcpErrAction.request, up.tcpErrAction(.syn_received));
    // tcp_req_err: a queued connection is dropped for parameter problem, time exceeded, net or host unreachable only.
    try std.testing.expect(up.tcpReqAborts(3, 0) and up.tcpReqAborts(3, 1) and up.tcpReqAborts(11, 0) and up.tcpReqAborts(12, 0));
    try std.testing.expect(!up.tcpReqAborts(3, 3) and !up.tcpReqAborts(3, 2));
    try std.testing.expect(up.tcpReqAborts6(1, 1) and up.tcpReqAborts6(1, 4) and up.tcpReqAborts6(4, 0) and up.tcpReqAborts6(1, 9));
    try std.testing.expect(!up.tcpReqAborts6(1, 0) and !up.tcpReqAborts6(1, 3) and !up.tcpReqAborts6(3, 0) and !up.tcpReqAborts6(2, 0));
    try std.testing.expectEqual(up.TcpErrAction.soft, up.tcpErrAction(.established));
    try std.testing.expectEqual(up.TcpErrAction.soft, up.tcpErrAction(.close_wait));
    try std.testing.expectEqual(up.TcpErrAction.ignore, up.tcpErrAction(.time_wait));
    try std.testing.expectEqual(up.TcpErrAction.ignore, up.tcpErrAction(.listen));
    try std.testing.expectEqual(up.TcpErrAction.ignore, up.tcpErrAction(.closed));
    // The quote: the TCP ports and sequence number after the quoted IPv4 header, or after the IPv6 header and its extensions.
    var m4: [8 + 20 + 8]u8 = @splat(0);
    m4[0] = 3;
    m4[8] = 0x45;
    m4[8 + 9] = 6;
    m4[28..36].* = .{ 0x9e, 0x26, 0x00, 0x50, 0xde, 0xad, 0xbe, 0xef };
    const q4 = up.parseTcpQuote(&m4).?;
    try std.testing.expectEqual(@as(u16, 0x9e26), q4.src_port);
    try std.testing.expectEqual(@as(u16, 80), q4.dst_port);
    try std.testing.expectEqual(@as(u32, 0xdeadbeef), q4.seq);
    m4[8 + 9] = 17;
    try std.testing.expect(up.parseTcpQuote(&m4) == null);
    var m6: [8 + 40 + 8]u8 = @splat(0);
    m6[0] = 1;
    m6[8] = 0x60;
    m6[8 + 6] = 6;
    m6[8 + 39] = 1;
    m6[48..56].* = .{ 0x9e, 0x27, 0x01, 0xbb, 0, 0, 0, 7 };
    const q6 = up.parseTcpQuote6(&m6).?;
    try std.testing.expectEqual(@as(u16, 443), q6.dst_port);
    try std.testing.expectEqual(@as(u32, 7), q6.seq);
    try std.testing.expectEqual(@as(u8, 1), q6.dst[15]);
    const ts = kt.tcp_source;
    try std.testing.expect(std.mem.indexOf(u8, ts, "if (!up.tcpSeqOk(seq, tcb.snd_una, tcb.snd_nxt)) return false;") != null);
    try std.testing.expect(std.mem.indexOf(u8, ts, "if (tcb.options.so_error != 0) return tcb.options.so_error;\n    if (tcb.reset_by_peer) return ECONNRESET;\n    if (tcb.fin_reset_err != 0) return tcb.fin_reset_err;\n    return tcb.soft_err;") != null);
    const ic = kt.icmp_source;
    try std.testing.expect(std.mem.indexOf(u8, ic, "@import(\"tcp.zig\").icmpError(tq, unreach.tcpErrno(icmp_type, icmp_code), unreach.tcpReqAborts(icmp_type, icmp_code), .{") != null);
    const iv = kt.icmpv6_source;
    try std.testing.expect(std.mem.indexOf(u8, iv, "@import(\"tcp.zig\").icmpError6(tq, unreach.tcpErrno6(icmp_type, icmp_code), unreach.tcpReqAborts6(icmp_type, icmp_code), .{") != null);
}

test "listen backlog (hello406): the accept queue holds backlog + 1, clamped to somaxconn and the ring (Linux sk_acceptq_is_full)" {
    const rp = kt.tcp_recv_policy;
    // __sys_listen_socket clamps (unsigned) backlog to somaxconn (4096); sk_acceptq_is_full is ack_backlog > max_ack_backlog, so
    // backlog + 1 connections wait. MoQiOS also stops at its own queue size.
    try std.testing.expectEqual(@as(u32, 1), rp.acceptLimit(0, 32));
    try std.testing.expectEqual(@as(u32, 2), rp.acceptLimit(1, 32));
    try std.testing.expectEqual(@as(u32, 4), rp.acceptLimit(3, 32));
    try std.testing.expectEqual(@as(u32, 32), rp.acceptLimit(40, 32));
    try std.testing.expectEqual(@as(u32, 32), rp.acceptLimit(0xffff_ffff, 32));
    try std.testing.expectEqual(@as(u32, 41), rp.acceptLimit(40, 128));
    const ts = kt.tcp_source;
    try std.testing.expectEqual(@as(usize, 3), std.mem.count(u8, ts, "if (ls.pending_tail -% ls.pending_head >= ls.accept_limit) return;"));
    try std.testing.expect(std.mem.indexOf(u8, ts, "pub fn tcpListen(tcb_idx: u32, backlog: u32) i64 {") != null);
    try std.testing.expect(std.mem.indexOf(u8, kt.socket_syscall_source, "const result = net_mod.tcp.tcpListen(tcb_idx, backlog);") != null);
}

test "TCP_USER_TIMEOUT and the end of an unanswered connection (hello407): Linux tcp_write_timeout / tcp_keepalive_timer / tcp_write_err" {
    const rp = kt.tcp_recv_policy;
    // tcp_sock_set_user_timeout: any value from 0 (off), a negative one is EINVAL.
    try std.testing.expectEqual(@as(i64, 0), rp.userTimeoutErrno(0));
    try std.testing.expectEqual(@as(i64, 0), rp.userTimeoutErrno(1500));
    try std.testing.expectEqual(@as(i64, -22), rp.userTimeoutErrno(-1));
    // tcp_write_timeout: without a user timeout the tcp_retries2 time model decides (hello411); with one, the time since the first
    // unanswered retransmission (retrans_stamp), whatever the count.
    try std.testing.expect(!rp.retransGiveUp(.{ .retransmits = 6, .elapsed_ms = 99_000 }));
    try std.testing.expect(!rp.retransGiveUp(.{ .retransmits = 2, .elapsed_ms = 999, .user_timeout_ms = 1000 }));
    try std.testing.expect(rp.retransGiveUp(.{ .retransmits = 2, .elapsed_ms = 1000, .user_timeout_ms = 1000 }));
    // The first expiry only retransmits (retransmits_timed_out is false while icsk_retransmits is 0).
    try std.testing.expect(!rp.retransGiveUp(.{ .retransmits = 1, .elapsed_ms = 5000, .user_timeout_ms = 1000 }));
    try std.testing.expect(!rp.retransGiveUp(.{ .retransmits = 6, .elapsed_ms = 30_000, .user_timeout_ms = 60_000 }));
    // tcp_clamp_rto_to_user_timeout: the next timer never waits past the user timeout (at least 1 ms once it has passed).
    try std.testing.expectEqual(@as(u32, 2000), rp.clampRto(2000, 0, 500));
    try std.testing.expectEqual(@as(u32, 500), rp.clampRto(2000, 1000, 500));
    try std.testing.expectEqual(@as(u32, 1), rp.clampRto(2000, 1000, 1200));
    try std.testing.expectEqual(@as(u32, 300), rp.clampRto(300, 1000, 200));
    // tcp_keepalive_timer: with a user timeout, the probes stop once that much time passed since the last data (and one probe
    // went out); without one, after keepcnt probes.
    try std.testing.expect(rp.keepaliveGiveUp(2, 2, 0, 3000));
    try std.testing.expect(!rp.keepaliveGiveUp(1, 2, 0, 3000));
    try std.testing.expect(!rp.keepaliveGiveUp(2, 9, 0, 3000));
    try std.testing.expect(rp.keepaliveGiveUp(2, 9, 2500, 2500));
    try std.testing.expect(!rp.keepaliveGiveUp(0, 9, 2500, 2600));
    try std.testing.expect(!rp.keepaliveGiveUp(2, 2, 60_000, 3000));
    // tcp_write_err: the connection ends with its soft error, else ETIMEDOUT, and reports it once.
    try std.testing.expectEqual(@as(i32, 110), rp.timeoutErrno(0));
    try std.testing.expectEqual(@as(i32, 113), rp.timeoutErrno(113));
    const ts = kt.tcp_source;
    // hello408: SYN_SENT follows synGiveUp, every other state retransGiveUp.
    try std.testing.expect(std.mem.indexOf(u8, ts, "            });\n            if (give_up) {") != null);
    try std.testing.expect(std.mem.indexOf(u8, ts, "tcb.options.so_error = tcp_recv_policy.timeoutErrno(tcb.soft_err);") != null);
    try std.testing.expect(std.mem.indexOf(u8, ts, "if (tcp_recv_policy.keepaliveGiveUp(tcb.keepalive_probes, tcb.options.keep_cnt, tcb.options.user_timeout_ms, tcb.idle_ms)) {") != null);
    const so = kt.socket_opt_source;
    try std.testing.expect(std.mem.indexOf(u8, so, "opts.user_timeout_ms = @intCast(v);") != null);
}

test "TCP timers run on measured time (hello407): a late maintenance pass under emulation still ages connections by the real interval" {
    const rp = kt.tcp_recv_policy;
    // The pass reports the milliseconds since the previous one, at least 1 and at most 1 s (a stall must not fire every timer at once).
    try std.testing.expectEqual(@as(u32, 100), rp.passElapsedMs(0, 100_000_000));
    try std.testing.expectEqual(@as(u32, 280), rp.passElapsedMs(1_000_000_000, 1_280_000_000));
    try std.testing.expectEqual(@as(u32, 1), rp.passElapsedMs(5, 5));
    try std.testing.expectEqual(@as(u32, 1000), rp.passElapsedMs(0, 9_000_000_000));
    try std.testing.expectEqual(@as(u32, 1), rp.passElapsedMs(10, 5));
    const ss = kt.sched_source;
    try std.testing.expect(std.mem.indexOf(u8, ss, "tcp.zig\").timerTick(100)") == null);
    try std.testing.expectEqual(@as(usize, 0), std.mem.count(u8, ss, "tcp.timerTick(100)"));
    try std.testing.expectEqual(@as(usize, 2), std.mem.count(u8, ss, "timerTickNow(@import(\"../arch/arch.zig\").tsc.nanos());"));
    try std.testing.expect(std.mem.indexOf(u8, kt.tcp_source, "timerTick(tcp_recv_policy.passElapsedMs(last, now_ns));") != null);
}

test "TCP_SYNCNT and the SYN retransmission schedule (hello408): Linux tcp_write_timeout / tcp_model_timeout / tcp_syn_linear_timeouts" {
    const rp = kt.tcp_recv_policy;
    // tcp_sock_set_syncnt: 1..MAX_TCP_SYNCNT (127); unset reads tcp_syn_retries (6).
    try std.testing.expectEqual(@as(i64, -22), rp.syncntErrno(0));
    try std.testing.expectEqual(@as(i64, -22), rp.syncntErrno(128));
    try std.testing.expectEqual(@as(i64, -22), rp.syncntErrno(-1));
    try std.testing.expectEqual(@as(i64, 0), rp.syncntErrno(1));
    try std.testing.expectEqual(@as(i64, 0), rp.syncntErrno(127));
    try std.testing.expectEqual(@as(u32, 6), rp.effectiveSyncnt(0));
    try std.testing.expectEqual(@as(u32, 3), rp.effectiveSyncnt(3));
    // The wait before the k-th expiry: 1 s for the first five (tcp_syn_linear_timeouts 4, then the doubling starts), then 2, 4, ...
    // up to TCP_RTO_MAX (120 s).
    for (1..6) |k| try std.testing.expectEqual(@as(u32, 1000), rp.synRtoMs(@intCast(k), 120_000));
    try std.testing.expectEqual(@as(u32, 2000), rp.synRtoMs(6, 120_000));
    try std.testing.expectEqual(@as(u32, 4000), rp.synRtoMs(7, 120_000));
    try std.testing.expectEqual(@as(u32, 120_000), rp.synRtoMs(20, 120_000));
    // An expiry, after `retransmits` retransmissions so far, gives up (instead of resending) once TCP_SYNCNT + 4 went out, or
    // ((2 << syncnt) - 1) s passed since the SYN; with a user timeout, once that passed (never at the first expiry).
    try std.testing.expect(!rp.synGiveUp(1, 1, 2000, 0, 120_000));
    try std.testing.expect(rp.synGiveUp(2, 1, 3000, 0, 120_000));
    try std.testing.expect(!rp.synGiveUp(4, 2, 5000, 0, 120_000));
    try std.testing.expect(rp.synGiveUp(6, 2, 7000, 0, 120_000));
    try std.testing.expect(!rp.synGiveUp(6, 3, 11000, 0, 120_000));
    try std.testing.expect(rp.synGiveUp(7, 3, 11000, 0, 120_000));
    try std.testing.expect(!rp.synGiveUp(1, 6, 2400, 2500, 120_000));
    try std.testing.expect(rp.synGiveUp(2, 6, 2500, 2500, 120_000));
    try std.testing.expect(!rp.synGiveUp(0, 6, 5000, 2500, 120_000));
    // Large syncnt: the time model saturates instead of overflowing.
    try std.testing.expect(!rp.synGiveUp(10, 127, 1_000_000, 0, 120_000));
    try std.testing.expect(rp.synGiveUp(131, 127, 1_000_000, 0, 120_000));
    const ts = kt.tcp_source;
    try std.testing.expect(std.mem.indexOf(u8, ts, "const base_rto = @min(if (tcb.state == .syn_sent) tcp_recv_policy.synRtoMs(@as(u32, tcb.retransmit_count) + 1, tcb.options.rto_max_ms) else if (tcb.state == .syn_received) tcp_recv_policy.synAckRtoMs(@as(u32, tcb.retransmit_count) + 1, tcb.options.rto_max_ms) else if (tcb.rto > 0) tcb.rto else RETRANSMIT_MS, tcb.options.rto_max_ms);") != null);
    try std.testing.expect(std.mem.indexOf(u8, ts, "tcp_recv_policy.synGiveUp(tcb.retransmit_count - 1, tcp_recv_policy.effectiveSyncnt(tcb.options.syn_cnt), rtxElapsedMs(tcb), tcb.options.user_timeout_ms, tcb.options.rto_max_ms)") != null);
}

test "zero-window probes (hello409): probing goes on while the window stays shut, TCP_USER_TIMEOUT bounds it (Linux tcp_probe_timer / tcp_xmit_probe_skb)" {
    const rp = kt.tcp_recv_policy;
    // RFC 1122 4.2.2.17: without a user timeout probing goes on as long as the peer answers; with one, the connection ends once
    // the window has been shut for that long (probes_tstamp is the first probe).
    try std.testing.expect(!rp.persistGiveUp(0, 600_000));
    try std.testing.expect(!rp.persistGiveUp(2000, 1999));
    try std.testing.expect(rp.persistGiveUp(2000, 2000));
    const ts = kt.tcp_source;
    try std.testing.expect(std.mem.indexOf(u8, ts, "if (tcp_recv_policy.persistGiveUp(tcb.options.user_timeout_ms, tcb.persist_shut_ms)) {") != null);
    // tcp_xmit_probe_skb: the probe carries no data and an old sequence number (snd_una - 1), so nothing it sends waits for an
    // acknowledgement and the retransmission timer stays out of it.
    const p = std.mem.indexOf(u8, ts, "fn sendPersistProbe(tcb: *TcpTcb) bool {") orelse return error.TestUnexpectedResult;
    const end = std.mem.indexOfPos(u8, ts, p, "\n}\n") orelse return error.TestUnexpectedResult;
    const body = ts[p..end];
    try std.testing.expect(std.mem.indexOf(u8, body, "return sendSegmentSeq(tcb, ACK, undefined, 0, probeKeepaliveSeq(tcb.snd_una));") != null);
    try std.testing.expect(std.mem.indexOf(u8, body, "ringRead") == null);
}

test "retransmissions into a zero window are probes (hello409): Linux tcp_retransmit_timer / tcp_rtx_probe0_timed_out" {
    const rp = kt.tcp_recv_policy;
    // While the peer keeps answering (rcv_delta small) the connection never times out on its zero window; with a user timeout
    // it ends once retransmitting has gone on past it; without one, only once the peer has been silent for 2 x TCP_RTO_MAX.
    try std.testing.expect(!rp.zeroWindowGiveUp(0, 600_000, 1_000));
    try std.testing.expect(!rp.zeroWindowGiveUp(0, 240_000, 240_000));
    try std.testing.expect(rp.zeroWindowGiveUp(0, 240_001, 240_001));
    try std.testing.expect(!rp.zeroWindowGiveUp(2000, 2000, 100));
    try std.testing.expect(rp.zeroWindowGiveUp(2000, 2001, 100));
    try std.testing.expect(!rp.zeroWindowGiveUp(2000, 1500, 3000));
    const ts = kt.tcp_source;
    try std.testing.expect(std.mem.indexOf(u8, ts, "else if (tcb.snd_wnd == 0 and tcp_recv_policy.zeroWindowState(tcb.state))\n                tcp_recv_policy.zeroWindowGiveUp(tcb.options.user_timeout_ms, rtxElapsedMs(tcb), tcb.peer_silent_ms)") != null);
    try std.testing.expect(std.mem.indexOf(u8, ts, "tcb.peer_silent_ms = 0;") != null);
}

test "established connections give up on time (hello411): Linux tcp_write_timeout / retransmits_timed_out / tcp_model_timeout, TCP_RTO_MAX_MS" {
    const rp = kt.tcp_recv_policy;
    // TCP_RTO_MAX_MS: 1000..120000 ms (TCP_RTO_MAX_SEC), anything else EINVAL.
    try std.testing.expectEqual(@as(i64, -22), rp.rtoMaxErrno(999));
    try std.testing.expectEqual(@as(i64, -22), rp.rtoMaxErrno(120_001));
    try std.testing.expectEqual(@as(i64, -22), rp.rtoMaxErrno(-1));
    try std.testing.expectEqual(@as(i64, 0), rp.rtoMaxErrno(1000));
    try std.testing.expectEqual(@as(i64, 0), rp.rtoMaxErrno(120_000));
    // tcp_model_timeout(boundary, rto_base): doubling from rto_base until the cap, then one cap per retransmission.
    try std.testing.expectEqual(@as(u64, 924_600), rp.modelTimeoutMs(15, 200, 120_000));
    try std.testing.expectEqual(@as(u64, 14_400), rp.modelTimeoutMs(15, 200, 1000));
    try std.testing.expectEqual(@as(u64, 102_200), rp.modelTimeoutMs(8, 200, 120_000));
    try std.testing.expectEqual(@as(u64, 200), rp.modelTimeoutMs(0, 200, 120_000));
    try std.testing.expectEqual(@as(u64, 127_000), rp.modelTimeoutMs(6, 1000, 120_000));
    try std.testing.expectEqual(@as(u64, 4000), rp.modelTimeoutMs(3, 1000, 1000));
    // Without a user timeout an established connection gives up once the oldest unacknowledged data waited the time tcp_retries2
    // (15) backed-off retransmissions take, whatever the count, and never at the first expiry.
    try std.testing.expect(!rp.retransGiveUp(.{ .retransmits = 2, .elapsed_ms = 924_599 }));
    try std.testing.expect(rp.retransGiveUp(.{ .retransmits = 2, .elapsed_ms = 924_600 }));
    try std.testing.expect(!rp.retransGiveUp(.{ .retransmits = 40, .elapsed_ms = 900_000 }));
    try std.testing.expect(!rp.retransGiveUp(.{ .retransmits = 1, .elapsed_ms = 2_000_000 }));
    try std.testing.expect(!rp.retransGiveUp(.{ .retransmits = 9, .elapsed_ms = 14_399, .rto_max_ms = 1000 }));
    try std.testing.expect(rp.retransGiveUp(.{ .retransmits = 9, .elapsed_ms = 14_400, .rto_max_ms = 1000 }));
    // With a user timeout, that decides (hello407).
    try std.testing.expect(!rp.retransGiveUp(.{ .retransmits = 2, .elapsed_ms = 999, .user_timeout_ms = 1000 }));
    try std.testing.expect(rp.retransGiveUp(.{ .retransmits = 2, .elapsed_ms = 1000, .user_timeout_ms = 1000 }));
    try std.testing.expect(!rp.retransGiveUp(.{ .retransmits = 1, .elapsed_ms = 5000, .user_timeout_ms = 1000 }));
    try std.testing.expect(!rp.retransGiveUp(.{ .retransmits = 30, .elapsed_ms = 30_000, .user_timeout_ms = 60_000 }));
    // An orphan (closed, SOCK_DEAD) gets tcp_orphan_retries: 8 while its RTO is below the cap, 0 once it reached it.
    try std.testing.expect(!rp.retransGiveUp(.{ .retransmits = 2, .elapsed_ms = 102_199, .orphan = true, .rto_ms = 400 }));
    try std.testing.expect(rp.retransGiveUp(.{ .retransmits = 2, .elapsed_ms = 102_200, .orphan = true, .rto_ms = 400 }));
    try std.testing.expect(rp.retransGiveUp(.{ .retransmits = 2, .elapsed_ms = 200, .orphan = true, .rto_ms = 1000, .rto_max_ms = 1000 }));
    try std.testing.expect(!rp.retransGiveUp(.{ .retransmits = 2, .elapsed_ms = 7399, .orphan = true, .rto_ms = 800, .rto_max_ms = 1000 }));
    // The SYN schedule and its time model follow the cap too.
    try std.testing.expectEqual(@as(u32, 1000), rp.synRtoMs(9, 1000));
    try std.testing.expectEqual(@as(u32, 2000), rp.synRtoMs(6, 120_000));
    try std.testing.expect(!rp.synGiveUp(3, 3, 3999, 0, 1000));
    try std.testing.expect(rp.synGiveUp(3, 3, 4000, 0, 1000));
    // The backed-off RTO stops at the socket's cap.
    try std.testing.expectEqual(@as(u32, 1000), rp.backoffRto(800, 1000));
    try std.testing.expectEqual(@as(u32, 120_000), rp.backoffRto(100_000, 120_000));
    try std.testing.expectEqual(@as(u32, 1600), rp.backoffRto(800, 120_000));
    const ts = kt.tcp_source;
    try std.testing.expect(std.mem.indexOf(u8, ts, "TCP_RETRIES") == null);
    try std.testing.expect(std.mem.indexOf(u8, ts, "tcp_recv_policy.retransGiveUp(.{\n                    .retransmits = tcb.retransmit_count,") != null);
    try std.testing.expect(std.mem.indexOf(u8, ts, ".orphan = tcb.ref_count == 0,") != null);
    try std.testing.expect(std.mem.indexOf(u8, ts, "tcb.rto = tcp_recv_policy.backoffRto(tcb.rto, tcb.options.rto_max_ms);") != null);
    try std.testing.expect(std.mem.indexOf(u8, ts, "if (tcb.rto > tcb.options.rto_max_ms) tcb.rto = tcb.options.rto_max_ms;") != null);
    try std.testing.expect(std.mem.indexOf(u8, ts, "else RETRANSMIT_MS, tcb.options.rto_max_ms);") != null);
    const so = kt.socket_opt_source;
    try std.testing.expect(std.mem.indexOf(u8, so, "opts.rto_max_ms = @intCast(v);") != null);
    try std.testing.expect(std.mem.indexOf(u8, so, "bo.writeU32Le(val_buf[0..4], opts.rto_max_ms);") != null);
}

test "accepted connections start with the listener's options (hello412): Linux sk_clone_lock / inet_csk_clone_lock" {
    const rp = kt.tcp_recv_policy;
    const Opts = struct { user_timeout_ms: u32 = 0, rto_max_ms: u32 = 120_000, keep_alive: bool = false, priority: i32 = 0, so_error: i32 = 0 };
    // Everything is copied but the error and SO_PRIORITY (sk_clone_lock clears sk_err, sk_err_soft and sk_priority).
    const child = rp.childOptions(Opts, .{ .user_timeout_ms = 1500, .rto_max_ms = 2000, .keep_alive = true, .priority = 3, .so_error = 104 });
    try std.testing.expectEqual(@as(u32, 1500), child.user_timeout_ms);
    try std.testing.expectEqual(@as(u32, 2000), child.rto_max_ms);
    try std.testing.expect(child.keep_alive);
    try std.testing.expectEqual(@as(i32, 0), child.priority);
    try std.testing.expectEqual(@as(i32, 0), child.so_error);
    const ts = kt.tcp_source;
    // Both families' SYN paths (fresh slot and TIME_WAIT reuse) take the listener's options.
    try std.testing.expectEqual(@as(usize, 4), std.mem.count(u8, ts, ".options = listenerOptions(ls);"));
    try std.testing.expect(std.mem.indexOf(u8, ts, "return tcp_recv_policy.childOptions(socket_opt.SocketOptions, tcbs[slot.tcb_idx].options);") != null);
}

test "SYN-ACK retransmissions of a half-open connection (hello413): Linux reqsk_timer_handler / syn_ack_recalc / tcp_reqsk_timeout" {
    const rp = kt.tcp_recv_policy;
    // tcp_reqsk_timeout: TCP_TIMEOUT_INIT (1 s) doubled per earlier expiry, at most the RTO cap.
    try std.testing.expectEqual(@as(u32, 1000), rp.synAckRtoMs(1, 120_000));
    try std.testing.expectEqual(@as(u32, 2000), rp.synAckRtoMs(2, 120_000));
    try std.testing.expectEqual(@as(u32, 16_000), rp.synAckRtoMs(5, 120_000));
    try std.testing.expectEqual(@as(u32, 120_000), rp.synAckRtoMs(40, 120_000));
    try std.testing.expectEqual(@as(u32, 1000), rp.synAckRtoMs(3, 1000));
    // tcp_synack_retries (5), or the listener's TCP_SYNCNT, which the child inherits.
    try std.testing.expectEqual(@as(u32, 5), rp.effectiveSynAckRetries(0));
    try std.testing.expectEqual(@as(u32, 2), rp.effectiveSynAckRetries(2));
    // syn_ack_recalc: the k-th expiry (num_timeout = k - 1 earlier ones) drops the request once num_timeout reaches the limit.
    try std.testing.expect(!rp.synAckGiveUp(1, 2));
    try std.testing.expect(!rp.synAckGiveUp(2, 2));
    try std.testing.expect(rp.synAckGiveUp(3, 2));
    try std.testing.expect(!rp.synAckGiveUp(5, 5));
    try std.testing.expect(rp.synAckGiveUp(6, 5));
    const ts = kt.tcp_source;
    try std.testing.expect(std.mem.indexOf(u8, ts, "else if (tcb.state == .syn_received) tcp_recv_policy.synAckRtoMs(@as(u32, tcb.retransmit_count) + 1, tcb.options.rto_max_ms)") != null);
    try std.testing.expect(std.mem.indexOf(u8, ts, "else if (tcb.state == .syn_received)\n                tcp_recv_policy.synAckExpiry(tcb.retransmit_count, tcp_recv_policy.effectiveSynAckRetries(tcb.options.syn_cnt), tcb.options.defer_accept, tcb.defer_acked).give_up") != null);
}

test "the first RTO comes from the handshake (hello414): Linux tcp_clean_rtx_queue / tcp_synack_rtt_meas / tcp_init_metrics" {
    const rp = kt.tcp_recv_policy;
    // A SYN or SYN-ACK that went out once gives an RTT sample: the time since it was sent (Karn: none after a retransmission).
    try std.testing.expectEqual(@as(?u32, 0), rp.handshakeRttSample(0, 0));
    try std.testing.expectEqual(@as(?u32, 120), rp.handshakeRttSample(0, 120));
    try std.testing.expectEqual(@as(?u32, null), rp.handshakeRttSample(1, 120));
    try std.testing.expectEqual(@as(?u32, null), rp.handshakeRttSample(3, 9000));
    try std.testing.expectEqual(@as(?u32, std.math.maxInt(u32)), rp.handshakeRttSample(0, 1 << 40));
    // Without any sample the first RTO is TCP_TIMEOUT_FALLBACK (RFC 6298 5.7).
    try std.testing.expectEqual(@as(u32, 3000), rp.TIMEOUT_FALLBACK_MS);
    const ts = kt.tcp_source;
    const p = std.mem.indexOf(u8, ts, "fn noteHandshakeRtt(tcb: *TcpTcb, sampled: bool) void {") orelse return error.TestUnexpectedResult;
    const end = std.mem.indexOfPos(u8, ts, p, "\n}\n") orelse return error.TestUnexpectedResult;
    const body = ts[p..end];
    try std.testing.expect(std.mem.indexOf(u8, body, "if (tcp_recv_policy.handshakeRttSample(tcb.retransmit_count, waited)) |m| updateRtt(tcb, m) else tcb.rto = tcp_recv_policy.TIMEOUT_FALLBACK_MS;") != null);
    try std.testing.expect(std.mem.indexOf(u8, body, "tcb.retransmit_count = 0;") != null);
    try std.testing.expect(std.mem.indexOf(u8, body, "tcb.rtx_elapsed_ms = 0;") != null);
    // Both ends of the handshake take it: the client on the SYN-ACK, the server on the final ACK.
    try std.testing.expect(std.mem.indexOf(u8, ts, "noteHandshakeRtt(tcb, ts_sampled);") != null);
    try std.testing.expect(std.mem.indexOf(u8, ts, "noteHandshakeRtt(tcb, false);\n                tcpLog(\"[tcp] server: connection established (ACK received)\\n\");") != null);
}

test "retransmission time counts from the send (hello414): the first timer pass after a segment went out charges only the time since then" {
    const rp = kt.tcp_recv_policy;
    // Sent 30 ms before a 100 ms pass ended: 30 ms, not the whole pass (Linux measures from retrans_stamp, the send time).
    try std.testing.expectEqual(@as(u32, 30), rp.firstChargeMs(100, 1_000_000_000, 1_030_000_000));
    // Sent before the previous pass (nothing charged yet): at most the pass.
    try std.testing.expectEqual(@as(u32, 100), rp.firstChargeMs(100, 1_000_000_000, 1_500_000_000));
    // No usable clock (no send stamp, no pass time, or a stamp after it): the whole pass, as before.
    try std.testing.expectEqual(@as(u32, 100), rp.firstChargeMs(100, 0, 1_030_000_000));
    try std.testing.expectEqual(@as(u32, 100), rp.firstChargeMs(100, 1_000_000_000, 0));
    try std.testing.expectEqual(@as(u32, 100), rp.firstChargeMs(100, 2_000_000_000, 1_000_000_000));
    const ts = kt.tcp_source;
    try std.testing.expect(std.mem.indexOf(u8, ts, "const charge = if (tcb.rtx_elapsed_ms == 0) tcp_recv_policy.firstChargeMs(ms_elapsed, tcb.rtx_start_ns, timer_now_ns) else ms_elapsed;") != null);
    try std.testing.expect(std.mem.indexOf(u8, ts, "tcb.retransmit_timer +%= charge;\n        tcb.rtx_elapsed_ms +|= charge;") != null);
    // The stamp is taken when a segment that uses sequence space goes out with none outstanding, and cleared with rtx_elapsed_ms.
    try std.testing.expect(std.mem.indexOf(u8, ts, "if (tcb.rtx_start_ns == 0 and (data_len > 0 or flags & (SYN | FIN) != 0)) tcb.rtx_start_ns = @import(\"../arch/arch.zig\").tsc.nanos();") != null);
    try std.testing.expectEqual(std.mem.count(u8, ts, "tcb.rtx_elapsed_ms = 0;"), std.mem.count(u8, ts, "tcb.rtx_start_ns = 0;"));
}

test "TCP_DEFER_ACCEPT (hello415): Linux secs_to_retrans / retrans_to_secs / tcp_check_req / syn_ack_recalc" {
    const rp = kt.tcp_recv_policy;
    // Seconds become SYN-ACK retransmissions on the 1 s doubling schedule (capped at TCP_RTO_MAX 120 s); a value <= 0 turns it off.
    try std.testing.expectEqual(@as(u8, 0), rp.deferSecsToRetrans(0));
    try std.testing.expectEqual(@as(u8, 0), rp.deferSecsToRetrans(-5));
    try std.testing.expectEqual(@as(u8, 1), rp.deferSecsToRetrans(1));
    try std.testing.expectEqual(@as(u8, 2), rp.deferSecsToRetrans(3));
    try std.testing.expectEqual(@as(u8, 3), rp.deferSecsToRetrans(5));
    try std.testing.expectEqual(@as(u8, 7), rp.deferSecsToRetrans(100));
    try std.testing.expectEqual(@as(u8, 255), rp.deferSecsToRetrans(std.math.maxInt(i32)));
    // getsockopt reads back the time those retransmissions cover.
    try std.testing.expectEqual(@as(i32, 0), rp.deferRetransToSecs(0));
    try std.testing.expectEqual(@as(i32, 1), rp.deferRetransToSecs(1));
    try std.testing.expectEqual(@as(i32, 3), rp.deferRetransToSecs(2));
    try std.testing.expectEqual(@as(i32, 7), rp.deferRetransToSecs(3));
    try std.testing.expectEqual(@as(i32, 127), rp.deferRetransToSecs(7));
    try std.testing.expectEqual(@as(i32, 247), rp.deferRetransToSecs(8));
    // tcp_check_req: a bare ACK (no data, no FIN) is dropped while fewer timeouts than the defer count have passed.
    try std.testing.expect(rp.deferDropsBareAck(0, 3, 0, false));
    try std.testing.expect(rp.deferDropsBareAck(2, 3, 0, false));
    try std.testing.expect(!rp.deferDropsBareAck(3, 3, 0, false));
    try std.testing.expect(!rp.deferDropsBareAck(0, 3, 4, false));
    try std.testing.expect(!rp.deferDropsBareAck(0, 3, 0, true));
    try std.testing.expect(!rp.deferDropsBareAck(0, 0, 0, false));
    // syn_ack_recalc at the k-th expiry (num_timeout = k - 1): without defer, resend until tcp_synack_retries; with it, a request
    // the client acknowledged is not resent until the last deferred timeout and not dropped before it.
    try std.testing.expectEqual(rp.SynAckExpiry{ .give_up = false, .resend = true }, rp.synAckExpiry(1, 5, 0, false));
    try std.testing.expectEqual(rp.SynAckExpiry{ .give_up = true, .resend = true }, rp.synAckExpiry(6, 5, 0, false));
    try std.testing.expectEqual(rp.SynAckExpiry{ .give_up = false, .resend = false }, rp.synAckExpiry(1, 5, 3, true));
    try std.testing.expectEqual(rp.SynAckExpiry{ .give_up = false, .resend = true }, rp.synAckExpiry(3, 5, 3, true));
    try std.testing.expectEqual(rp.SynAckExpiry{ .give_up = false, .resend = true }, rp.synAckExpiry(1, 5, 1, true));
    try std.testing.expectEqual(rp.SynAckExpiry{ .give_up = false, .resend = false }, rp.synAckExpiry(6, 5, 7, true));
    try std.testing.expectEqual(rp.SynAckExpiry{ .give_up = true, .resend = true }, rp.synAckExpiry(8, 5, 7, true));
    try std.testing.expectEqual(rp.SynAckExpiry{ .give_up = true, .resend = true }, rp.synAckExpiry(6, 5, 7, false));
    const ts = kt.tcp_source;
    try std.testing.expect(std.mem.indexOf(u8, ts, "if (tcp_recv_policy.deferDropsBareAck(tcb.retransmit_count, tcb.options.defer_accept, payload_len, flags & FIN != 0)) {\n                    tcb.defer_acked = true;\n                    return;\n                }") != null);
    // The segment that completes the handshake is processed as an established one, so its data (or FIN) is not lost.
    try std.testing.expect(std.mem.indexOf(u8, ts, "if (payload_len > 0 or flags & FIN != 0) return driveTcbStateMachine(tcb, seq_num, ack_num, flags, raw_window, opts, data, payload_offset, payload_len, pending_events, pending_idx, ecn_ce);") != null);
    try std.testing.expectEqual(@as(usize, 2), std.mem.count(u8, ts, "tcp_recv_policy.synAckExpiry(tcb.retransmit_count, tcp_recv_policy.effectiveSynAckRetries(tcb.options.syn_cnt), tcb.options.defer_accept, tcb.defer_acked)"));
    const so = kt.socket_opt_source;
    try std.testing.expect(std.mem.indexOf(u8, so, "opts.defer_accept = @import(\"tcp_recv_policy.zig\").deferSecsToRetrans(v);") != null);
    try std.testing.expect(std.mem.indexOf(u8, so, "@bitCast(@import(\"tcp_recv_policy.zig\").deferRetransToSecs(opts.defer_accept))") != null);
}

test "IPv6 extension headers on input (hello410): hop-by-hop and destination options are stepped over (Linux ipv6_parse_hopopts / ip6_parse_tlv)" {
    const rp = kt.raw_icmp_policy;
    // A destination-options header (next header 17, length 0, PadN of 4) before an 8-byte UDP header: UDP at offset 8.
    var dst = [_]u8{ 17, 0, 1, 4, 0, 0, 0, 0, 0x30, 0x39, 0x1f, 0x90, 0, 12, 0, 0 };
    const w = rp.walkExt6(60, &dst);
    try std.testing.expectEqual(rp.Ext6.Kind.deliver, w.kind);
    try std.testing.expectEqual(@as(u8, 17), w.nh);
    try std.testing.expectEqual(@as(usize, 8), w.off);
    // Pad1 options (type 0, one byte each) are fine too.
    var pad1 = [_]u8{ 17, 0, 0, 0, 0, 0, 0, 0 };
    try std.testing.expectEqual(rp.Ext6.Kind.deliver, rp.walkExt6(60, &pad1).kind);
    // Hop-by-hop works the same way; only it may come first.
    try std.testing.expectEqual(rp.Ext6.Kind.deliver, rp.walkExt6(0, &dst).kind);
    // An unknown option: top bits 00 skip it, 01 drop silently, 10 parameter problem code 2 (pointer at the option), 11 the same
    // unless the destination is multicast.
    dst[2] = 0x01;
    try std.testing.expectEqual(rp.Ext6.Kind.deliver, rp.walkExt6(60, &dst).kind);
    dst[2] = 0x40;
    try std.testing.expectEqual(rp.Ext6.Kind.drop, rp.walkExt6(60, &dst).kind);
    dst[2] = 0x80;
    const u = rp.walkExt6(60, &dst);
    try std.testing.expectEqual(rp.Ext6.Kind.bad_option, u.kind);
    try std.testing.expectEqual(@as(usize, 2), u.off);
    dst[2] = 0xc0;
    try std.testing.expectEqual(rp.Ext6.Kind.bad_option, rp.walkExt6(60, &dst).kind);
    dst[2] = 1;
    // An option running past its header, and a header running past the packet, are dropped.
    var over = [_]u8{ 17, 0, 1, 9, 0, 0, 0, 0 };
    try std.testing.expectEqual(rp.Ext6.Kind.drop, rp.walkExt6(60, &over).kind);
    var short = [_]u8{ 17, 1, 1, 4, 0, 0, 0, 0 };
    try std.testing.expectEqual(rp.Ext6.Kind.drop, rp.walkExt6(60, &short).kind);
    // No next header (59) ends the packet: nothing is delivered and nothing is answered.
    var none = [_]u8{ 59, 0, 1, 4, 0, 0, 0, 0 };
    try std.testing.expectEqual(rp.Ext6.Kind.drop, rp.walkExt6(60, &none).kind);
    // A next header that is not an extension MoQiOS parses is where the walk stops, offset 0 when there is none.
    try std.testing.expectEqual(@as(usize, 0), rp.walkExt6(17, &dst).off);
    try std.testing.expectEqual(@as(u32, 6), rp.walkExt6(17, &dst).nh_field);
    try std.testing.expectEqual(@as(u32, 40), rp.walkExt6(60, &dst).nh_field);
    try std.testing.expectEqual(@as(u8, 252), rp.walkExt6(252, &dst).nh);
    // A hop-by-hop header after the first one is a parameter problem code 1 pointing at its next-header field.
    var hbh2 = [_]u8{ 0, 0, 1, 4, 0, 0, 0, 0, 17, 0, 1, 4, 0, 0, 0, 0 };
    const h = rp.walkExt6(60, &hbh2);
    try std.testing.expectEqual(rp.Ext6.Kind.bad_header, h.kind);
    try std.testing.expectEqual(@as(usize, 0), h.off);
    // The parameter problem names its code and the offset in the packet (IPv6 header included).
    var out: [rp.PARAM_PROBLEM_MAX]u8 = undefined;
    var pkt: [48]u8 = @splat(0);
    const n = rp.paramProblemMsgAt(&out, &pkt, 2, 42);
    try std.testing.expectEqual(@as(usize, 56), n);
    try std.testing.expectEqualSlices(u8, &[_]u8{ 4, 2, 0, 0, 0, 0, 0, 42 }, out[0..8]);
    const m = kt.net_mod_source;
    try std.testing.expect(std.mem.indexOf(u8, m, "const ext = rp6.walkExt6(info6.next_header, data[payload_start6 .. payload_start6 + info6.payload_len]);") != null);
    try std.testing.expect(std.mem.indexOf(u8, m, "else => if (rp6.paramProblem6(ext.nh, raw_took6)) icmpv6.sendParamProblemAt(pkt6, 1, ext.nh_field, info6.src_ip, info6.dst_ip),") != null);
}

test "TCP_NOTSENT_LOWAT (hello416): Linux tcp_stream_memory_free / tcp_poll / do_tcp_setsockopt" {
    const rp = kt.tcp_recv_policy;
    // 0 is the sysctl default tcp_notsent_lowat (UINT_MAX): no limit; any other value is used as a u32 (-5 is huge).
    try std.testing.expectEqual(@as(u32, std.math.maxInt(u32)), rp.notsentLimit(0));
    try std.testing.expectEqual(@as(u32, 1024), rp.notsentLimit(1024));
    try std.testing.expectEqual(@as(u32, 0xFFFF_FFFB), rp.notsentLimit(-5));
    // A send may queue more while the unsent bytes are below the limit (sk_stream_memory_free, wake 0).
    try std.testing.expect(rp.notsentAllowsQueue(1023, 1024));
    try std.testing.expect(!rp.notsentAllowsQueue(1024, 1024));
    try std.testing.expect(rp.notsentAllowsQueue(60000, 0));
    // poll/epoll report writable while twice the unsent bytes are below it (tcp_poll, wake 1).
    try std.testing.expect(rp.notsentWritable(0, 1024));
    try std.testing.expect(rp.notsentWritable(511, 1024));
    try std.testing.expect(!rp.notsentWritable(512, 1024));
    try std.testing.expect(!rp.notsentWritable(8000, 16000));
    try std.testing.expect(rp.notsentWritable(8000, 16001));
    try std.testing.expect(rp.notsentWritable(65535, 0));
    const so = kt.socket_opt_source;
    try std.testing.expect(std.mem.indexOf(u8, so, "opts.notsent_lowat = @bitCast(bo.readU32Le(&buf));") != null);
    try std.testing.expect(std.mem.indexOf(u8, so, "bo.writeU32Le(val_buf[0..4], @bitCast(opts.notsent_lowat));") != null);
    const ts = kt.tcp_source;
    // Every path that queues send data, and the blocking writer's wait, use the same room.
    try std.testing.expectEqual(@as(usize, 4), std.mem.count(u8, ts, "sendRoom(tcb)"));
    try std.testing.expect(std.mem.indexOf(u8, ts, "if (!tcp_recv_policy.notsentAllowsQueueWith(notsentBytes(tcb), tcb.options.notsent_lowat, @import(\"notsent_lowat_sysctl.zig\").get())) return 0;") != null);
    try std.testing.expect(std.mem.indexOf(u8, ts, "if (!tcp_recv_policy.notsentWritableWith(notsentBytes(tcb), tcb.options.notsent_lowat, @import(\"notsent_lowat_sysctl.zig\").get())) 0 else") != null);
}

test "TCP_NOTSENT_LOWAT wake on new data sent (hello420): Linux tcp_event_new_data_sent -> tcp_check_space -> sk_stream_write_space" {
    const rp = kt.tcp_recv_policy;
    // Sending data only lowers the unsent bytes: the writer and pollers hear it when the socket became writable by the poll rule.
    try std.testing.expect(rp.notsentWakeOnSend(1500, 400, 1024));
    try std.testing.expect(!rp.notsentWakeOnSend(1500, 600, 1024));
    try std.testing.expect(!rp.notsentWakeOnSend(400, 300, 1024));
    try std.testing.expect(!rp.notsentWakeOnSend(1500, 1500, 1024));
    // No limit set: the ACK path's own wake already covers it.
    try std.testing.expect(!rp.notsentWakeOnSend(1500, 0, 0));
    const ts = kt.tcp_source;
    try std.testing.expect(std.mem.indexOf(u8, ts, "const unsent_before = notsentBytes(tcb);") != null);
    try std.testing.expect(std.mem.indexOf(u8, ts, "defer if (tcp_recv_policy.notsentWakeOnSendWith(unsent_before, notsentBytes(tcb), tcb.options.notsent_lowat, @import(\"notsent_lowat_sysctl.zig\").get())) {") != null);
    try std.testing.expect(std.mem.indexOf(u8, ts, "write_space_pending.set(tcbIdx(tcb));") != null);
    // The EPOLLOUT notes are sent after tcp_lock is released, wherever the lock is released.
    try std.testing.expect(std.mem.indexOf(u8, ts, "if (!write_space_pending.isEmpty()) ws = write_space_pending.takeAll();") != null);
    try std.testing.expect(std.mem.indexOf(u8, ts, "if (!ws.isEmpty()) notifyWriteSpace(&ws);") != null);
}

test "TCP_LINGER2 (hello417): Linux do_tcp_setsockopt / tcp_fin_time / orphan FIN_WAIT2 in tcp_close and tcp_rcv_state_process" {
    const rp = kt.tcp_recv_policy;
    // setsockopt: a negative value is kept as -1, one above TCP_FIN_TIMEOUT_MAX (120 s) as 120 s, else the seconds (stored in ms).
    try std.testing.expectEqual(@as(i32, -1), rp.linger2FromUser(-7));
    try std.testing.expectEqual(@as(i32, -1), rp.linger2FromUser(-1));
    try std.testing.expectEqual(@as(i32, 0), rp.linger2FromUser(0));
    try std.testing.expectEqual(@as(i32, 5000), rp.linger2FromUser(5));
    try std.testing.expectEqual(@as(i32, 120_000), rp.linger2FromUser(120));
    try std.testing.expectEqual(@as(i32, 120_000), rp.linger2FromUser(121));
    try std.testing.expectEqual(@as(i32, 120_000), rp.linger2FromUser(std.math.maxInt(i32)));
    // getsockopt: 0 reads back the tcp_fin_timeout default (60 s), -1 stays -1.
    try std.testing.expectEqual(@as(i32, 60), rp.linger2ToUser(0));
    try std.testing.expectEqual(@as(i32, 5), rp.linger2ToUser(5000));
    try std.testing.expectEqual(@as(i32, 120), rp.linger2ToUser(120_000));
    try std.testing.expectEqual(@as(i32, -1), rp.linger2ToUser(-1));
    // tcp_fin_time: 0 is the 60 s default; never below 3.5 RTO.
    try std.testing.expectEqual(@as(u32, 60_000), rp.finTimeoutMs(0, 200));
    try std.testing.expectEqual(@as(u32, 1000), rp.finTimeoutMs(1000, 200));
    try std.testing.expectEqual(@as(u32, 7000), rp.finTimeoutMs(1000, 2000));
    try std.testing.expectEqual(@as(u32, 120_000), rp.finTimeoutMs(120_000, 200));
    // Only an orphan (no descriptor left) times out or aborts; a half-closed socket still open waits for the peer.
    try std.testing.expect(rp.finWait2Aborts(true, -1));
    try std.testing.expect(!rp.finWait2Aborts(false, -1));
    try std.testing.expect(!rp.finWait2Aborts(true, 0));
    try std.testing.expect(rp.finWait2Expired(true, 1000, 1000, 200));
    try std.testing.expect(!rp.finWait2Expired(true, 999, 1000, 200));
    try std.testing.expect(!rp.finWait2Expired(false, 600_000, 1000, 200));
    try std.testing.expect(!rp.finWait2Expired(true, 600_000, -1, 200));
    try std.testing.expect(rp.finWait2Expired(true, 60_000, 0, 200));
    try std.testing.expect(!rp.finWait2Expired(true, 59_990, 0, 200));
    // tcp_reset after the peer's FIN: CLOSE_WAIT is EPIPE, CLOSING / LAST_ACK ECONNRESET; recv keeps reading EOF (SOCK_DONE).
    try std.testing.expectEqual(@as(i32, 32), rp.resetErrAfterFin(.close_wait));
    try std.testing.expectEqual(@as(i32, 104), rp.resetErrAfterFin(.last_ack));
    try std.testing.expectEqual(@as(i32, 104), rp.resetErrAfterFin(.closing));
    try std.testing.expectEqual(@as(i32, 0), rp.resetErrAfterFin(.time_wait));
    try std.testing.expectEqual(@as(i32, 0), rp.resetErrAfterFin(.fin_wait_2));
    const so = kt.socket_opt_source;
    try std.testing.expect(std.mem.indexOf(u8, so, "opts.linger2_ms = @import(\"tcp_recv_policy.zig\").linger2FromUser(@bitCast(bo.readU32Le(&buf)));") != null);
    try std.testing.expect(std.mem.indexOf(u8, so, "bo.writeU32Le(val_buf[0..4], @bitCast(@import(\"tcp_recv_policy.zig\").linger2ToUser(opts.linger2_ms)));") != null);
    const ts = kt.tcp_source;
    try std.testing.expect(std.mem.indexOf(u8, ts, "if (tcp_recv_policy.finWait2Expired(tcb.ref_count == 0, tcb.retransmit_timer, tcb.options.linger2_ms, tcb.rto)) {") != null);
    // tcp_close in FIN_WAIT2 with linger2 < 0 resets; tcp_rcv_state_process does the same for an orphan reaching FIN_WAIT2.
    try std.testing.expectEqual(@as(usize, 2), std.mem.count(u8, ts, "tcp_recv_policy.finWait2Aborts("));
    try std.testing.expect(std.mem.indexOf(u8, ts, ".fin_wait_1, .closing, .last_ack => {},") != null);
    try std.testing.expect(std.mem.indexOf(u8, ts, "tcb.fin_reset_err = tcp_recv_policy.resetErrAfterFin(tcb.state);") != null);
    try std.testing.expect(std.mem.indexOf(u8, ts, "if (tcb.fin_reset_err != 0) return tcb.fin_reset_err;") != null);
    // A segment for no connection is answered with a reset on loopback (tcp_v4_send_reset / tcp_v6_send_reset), not only a SYN, unless a
    // listener holds the port (the forged peers of hello407/411/414 rely on that).
    try std.testing.expect(std.mem.indexOf(u8, ts, "        } else if (!hasListener(dst_port, false, dst_ip, @splat(0))) sendLoopbackReset(src_ip, dst_ip, src_port, dst_port, flags, ack_num, seq_num, payload_len);\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, ts, "        } else if (!hasListener(dst_port, true, tcp_port_policy.WILDCARD4, dst_ip)) sendLoopbackResetV6(src_ip, dst_ip, src_port, dst_port, flags, ack_num, seq_num, payload_len);\n") != null);
}

test "TCP reset and timeout readiness (hello407): ERR comes with IN and HUP, the snapshot is taken under tcp_lock" {
    const rd = kt.tcp_ready_policy;
    const S = kt.tcp_recv_policy.TcpState;
    // An established connection whose retransmission (or keepalive) timed out is gone: poll reports ERR and IN, and HUP when both
    // directions are finished, like Linux tcp_poll (EPOLLERR | EPOLLHUP | EPOLLIN are always reported).
    const timed_out = rd.events(.{ .active = true, .state = S.closed, .recv_bytes = 0, .send_space = 0, .reset_by_peer = false, .shut_rd = false, .fin_pending = false, .so_error = 110 });
    try std.testing.expectEqual(@as(u32, rd.IN | rd.ERR | rd.HUP | rd.OUT | rd.RDHUP), timed_out);
    // A reset by the peer reports the same.
    const reset = rd.events(.{ .active = true, .state = S.closed, .recv_bytes = 0, .send_space = 0, .reset_by_peer = true, .shut_rd = false, .fin_pending = false });
    try std.testing.expectEqual(@as(u32, rd.IN | rd.ERR | rd.HUP | rd.OUT | rd.RDHUP), reset);
    // An errored connection that already has a RDHUP-ish state keeps IN and ERR.
    const half = rd.events(.{ .active = true, .state = S.fin_wait_2, .recv_bytes = 0, .send_space = 0, .reset_by_peer = false, .shut_rd = false, .fin_pending = false, .so_error = 110 });
    try std.testing.expect(half & rd.ERR != 0);
    const ts = kt.tcp_source;
    // The timeout paths store so_error and then close the connection; poll and epoll must not see the error without the closed
    // state (ERR without IN/HUP), so the readiness snapshot is taken under tcp_lock (Linux tcp_poll reads under the socket lock's
    // ordering: sk_err is published together with the state by tcp_done).
    try std.testing.expect(std.mem.indexOf(u8, ts, "pub fn tcpReadiness(tcb_idx: u32) u32 {\n    const ready = @import(\"tcp_ready_policy.zig\");\n    if (tcb_idx >= MAX_CONNECTIONS) return ready.events(.{ .active = false, .state = .closed, .recv_bytes = 0, .send_space = 0, .reset_by_peer = false, .shut_rd = false, .fin_pending = false });\n    const lock_flags = tcp_lock.acquire();\n    defer tcp_lock.release(lock_flags);\n") != null);
}

test "IPv4 id and DF of kernel-built headers (hello418): per-connection ids, zero on handshakes, hashed ids without DF on errors" {
    const ip = kt.ipid_policy;
    var hdr: [20]u8 = undefined;
    ipv4.buildHeader(&hdr, .{ 127, 0, 0, 1 }, .{ 127, 0, 0, 2 }, ipv4.PROTO_UDP, 8);
    // buildHeader keeps id 0 with DF (the handshake/reset form, ip_build_and_send_pkt).
    try std.testing.expectEqual(@as(u8, 0), hdr[4] | hdr[5]);
    try std.testing.expectEqual(@as(u8, 0x40), hdr[6]);
    ipv4.setIdent(&hdr, 0xbeef, false);
    try std.testing.expectEqual(@as(u16, 0xbeef), byte_order.readU16BeAt(&hdr, 4));
    try std.testing.expectEqual(@as(u8, 0), hdr[6] & 0x40);
    try std.testing.expectEqual(@as(u16, 0), ipv4.checksum(&hdr, 20));
    ipv4.setIdent(&hdr, 7, true);
    try std.testing.expectEqual(@as(u16, 7), byte_order.readU16BeAt(&hdr, 4));
    try std.testing.expectEqual(@as(u8, 0x40), hdr[6]);
    try std.testing.expectEqual(@as(u16, 0), ipv4.checksum(&hdr, 20));
    // A socket's id is used, then advanced by one (ip_select_ident_segs); it wraps through 0 like Linux.
    var cur: u16 = 0xfffe;
    try std.testing.expectEqual(@as(u16, 0xfffe), ip.take(&cur));
    try std.testing.expectEqual(@as(u16, 0xffff), ip.take(&cur));
    try std.testing.expectEqual(@as(u16, 0), ip.take(&cur));
    try std.testing.expectEqual(@as(u16, 1), cur);
    // The unowned generator (__ip_select_ident) picks a bucket from (daddr, saddr, protocol) and a boot secret.
    const a = ip.bucket(.{ 127, 0, 0, 1 }, .{ 127, 0, 0, 1 }, 1, 0x1234);
    try std.testing.expectEqual(a, ip.bucket(.{ 127, 0, 0, 1 }, .{ 127, 0, 0, 1 }, 1, 0x1234));
    var seen: u64 = 0;
    for (0..32) |k| {
        const b = ip.bucket(.{ 10, 0, 2, @intCast(k) }, .{ 10, 0, 2, 15 }, 17, 0x1234);
        try std.testing.expect(b < ip.BUCKETS);
        seen |= @as(u64, 1) << @intCast(b);
    }
    try std.testing.expect(@popCount(seen) >= 8);
    var other: bool = false;
    for (0..16) |k| other = other or ip.bucket(.{ 127, 0, 0, 1 }, .{ 127, 0, 0, 1 }, 1, @intCast(k)) != a;
    try std.testing.expect(other);
    // A shared counter used again in the same tick moves on by one; after a quiet spell it first jumps ahead by less than the ticks
    // that passed (ip_idents_reserve).
    var c: u16 = 100;
    var st: u32 = 50;
    try std.testing.expectEqual(@as(u16, 100), ip.reserve(&c, &st, 50, 0xffff_ffff));
    try std.testing.expectEqual(@as(u16, 101), ip.reserve(&c, &st, 50, 7));
    try std.testing.expectEqual(@as(u16, 102 + 7), ip.reserve(&c, &st, 60, 7));
    try std.testing.expectEqual(@as(u32, 60), st);
    try std.testing.expectEqual(@as(u16, 110 + 3), ip.reserve(&c, &st, 64, 7));
    try std.testing.expectEqual(@as(u16, 114), c);
    // A SYN-ACK leaves with id 0 (ip_build_and_send_pkt under DF); every other segment of a connection uses its own counter.
    try std.testing.expect(!ip.tcpUsesSocketId(0x12));
    try std.testing.expect(ip.tcpUsesSocketId(0x02));
    try std.testing.expect(ip.tcpUsesSocketId(0x10));
    try std.testing.expect(ip.tcpUsesSocketId(0x11));
    try std.testing.expect(ip.tcpUsesSocketId(0x18));
    const ts = kt.tcp_source;
    try std.testing.expect(std.mem.count(u8, ts, ".ip_id = ipid.initial();") >= 5);
    const us = kt.udp_source;
    try std.testing.expect(std.mem.indexOf(u8, us, "    port_ipid[idx] = 0;\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, us, "    if (port_peer[i] == 0) return null;\n    return ipid_policy.take(&port_ipid[i]);\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, us, "    port_ipid[i] = ipid.initial();\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, us, "            port_ipid[i] = port_ipid[num_ports];\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, us, "    ipv4.setIdent(pkt[14..].ptr, ipid.global(src_ip, dst_ip, ipv4.PROTO_ICMP), false);\n") != null);
    const is = kt.icmp_source;
    // hello454: the fragmented ping send and the big echo reply number their headers from the shared generator too; hello466: a
    // ping send with IP options within the MTU numbers its header as an unfragmented one.
    try std.testing.expectEqual(@as(usize, 6), std.mem.count(u8, is, "ipv4.setIdent("));
    try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, is, "ipv4.setIdent(&hdr, ipid.global(dst, src, ipv4.PROTO_ICMP), false);"));
    try std.testing.expect(std.mem.indexOf(u8, is, "if (big) ipv4.setIdent(&hdr, ipid.global(dst, src, ipv4.PROTO_ICMP), false) else ipv4.setIdent(&hdr, ipid.unowned(dst, src, ipv4.PROTO_ICMP, mode), ipo.datagramDf(mode));") != null);
    try std.testing.expect(std.mem.indexOf(u8, is, "    ipv4.setIdent(o + 14, ipid.global(reply_dst_ip, reply_src_ip, ipv4.PROTO_ICMP), false);\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, is, "    ipv4.setIdent(pkt[14..].ptr, ipid.global(src_ip, dst_ip, ipv4.PROTO_ICMP), false);\n") != null);
    const rs = kt.raw_icmp_source;
    try std.testing.expect(std.mem.indexOf(u8, rs, "var hdrincl_ident") == null);
}

test "IP_MTU_DISCOVER (hello419): values 0..5, default WANT, the DF bit and whether an unowned datagram is numbered" {
    const p = kt.ip_opt_policy;
    const ip = kt.ipid_policy;
    const none: p.IpOpts = .{};
    try std.testing.expectEqual(@as(?i32, 1), p.getValue(none, p.SOL_IP, p.IP_MTU_DISCOVER));
    var v: i32 = 0;
    while (v <= 5) : (v += 1) {
        const r = p.applySet(none, p.SOL_IP, p.IP_MTU_DISCOVER, std.mem.asBytes(&v));
        try std.testing.expect(r == .ok);
        try std.testing.expectEqual(@as(?i32, v), p.getValue(r.ok, p.SOL_IP, p.IP_MTU_DISCOVER));
    }
    for ([_]i32{ -1, 6, 100 }) |bad| {
        const r = p.applySet(none, p.SOL_IP, p.IP_MTU_DISCOVER, std.mem.asBytes(&bad));
        try std.testing.expectEqual(@as(i64, -22), r.err);
    }
    const one_byte = [1]u8{2};
    try std.testing.expectEqual(@as(u8, 2), p.applySet(none, p.SOL_IP, p.IP_MTU_DISCOVER, &one_byte).ok.pmtudisc);
    // __ip_make_skb: a datagram (UDP, raw, ping) has DF under WANT, DO and PROBE; ip_queue_xmit: a TCP segment only under WANT and DO
    // (ip_dont_fragment).
    const dgram = [6]bool{ false, true, true, true, false, false };
    const stream = [6]bool{ false, true, true, false, false, false };
    // ip_sk_ignore_df: DONT, WANT and OMIT let the stack fragment, so ip_select_ident_segs numbers a datagram no socket owns even with
    // DF; under DO, PROBE and INTERFACE a DF datagram keeps id 0, one without DF is numbered.
    const numbered = [6]bool{ true, true, false, false, true, true };
    for (0..6) |m| {
        const mode: u8 = @intCast(m);
        try std.testing.expectEqual(dgram[m], p.datagramDf(mode));
        try std.testing.expectEqual(stream[m], p.streamDf(mode));
        try std.testing.expectEqual(numbered[m], ip.numbersUnowned(p.datagramDf(mode), p.ignoreDf(mode)));
    }
    const ts = kt.tcp_source;
    try std.testing.expect(std.mem.indexOf(u8, ts, "    if (ipid_policy.tcpUsesSocketId(flags)) ipv4.setIdent(send_pkt[14..].ptr, ipid_policy.take(&tcb.ip_id), ip_opt_policy.streamDf(tcb.options.ip.pmtudisc));\n") != null);
    const us = kt.udp_source;
    try std.testing.expect(std.mem.indexOf(u8, us, "    ipv4.setIdent(send_pkt[14..].ptr, takePortIpid(src_key, dst_ip, our_ip, opts4.pmtudisc), ip_opt_policy.datagramDf(opts4.pmtudisc));\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, kt.ipid_source, "pub fn unowned(daddr: [4]u8, saddr: [4]u8, protocol: u8, mode: u8) u16 {") != null);
    const rs = kt.raw_icmp_source;
    try std.testing.expect(std.mem.indexOf(u8, rs, "    ipv4.setIdent(pkt[14..].ptr, ipid.unowned(dst, src, protocol, ip.pmtudisc), ipo.datagramDf(ip.pmtudisc));\n") != null);
    const is = kt.icmp_source;
    try std.testing.expect(std.mem.indexOf(u8, is, "pub fn sendFrom(bound: [4]u8, dst: [4]u8, msg: []const u8, mode: u8) i64 {") != null);
    try std.testing.expect(std.mem.indexOf(u8, is, "    ipv4.setIdent(pkt[14..].ptr, ipid.unowned(dst, src, ipv4.PROTO_ICMP, mode), ipo.datagramDf(mode));\n") != null);
}

test "IPv4 UDP receive control messages IP_PKTINFO / IP_RECVTTL / IP_RECVTOS (hello421): Linux ip_cmsg_recv_offset, put_cmsg" {
    const p = kt.ip_opt_policy;
    // On/off flags: any nonzero int sets, 0 clears; getsockopt reads 0 or 1 (inet_assign_bit / inet_test_bit).
    var o: p.IpOpts = .{};
    try std.testing.expectEqual(@as(?i32, 0), p.getValue(o, p.SOL_IP, p.IP_PKTINFO));
    o = p.applySet(o, p.SOL_IP, p.IP_PKTINFO, &.{ 5, 0, 0, 0 }).ok;
    o = p.applySet(o, p.SOL_IP, p.IP_RECVTTL, &.{ 1, 0, 0, 0 }).ok;
    try std.testing.expectEqual(@as(?i32, 1), p.getValue(o, p.SOL_IP, p.IP_PKTINFO));
    try std.testing.expectEqual(@as(?i32, 1), p.getValue(o, p.SOL_IP, p.IP_RECVTTL));
    try std.testing.expectEqual(@as(?i32, 0), p.getValue(o, p.SOL_IP, p.IP_RECVTOS));
    o = p.applySet(o, p.SOL_IP, p.IP_RECVTTL, &.{ 0, 0, 0, 0 }).ok;
    try std.testing.expectEqual(@as(?i32, 0), p.getValue(o, p.SOL_IP, p.IP_RECVTTL));

    const c = kt.ip_cmsg_policy;
    const info: c.RecvInfo = .{ .ifindex = 1, .dst = .{ 127, 0, 0, 5 }, .ttl = 33, .tos = 0x28 };
    var out: [128]u8 = undefined;
    // All three, in Linux order: PKTINFO (28, padded to 32), TTL (20 -> 24), TOS (17 -> 24).
    const all = c.build(.{ .pktinfo = true, .recvttl = true, .recvtos = true }, info, 128, &out);
    try std.testing.expectEqual(@as(usize, 80), all.written);
    try std.testing.expect(!all.truncated);
    try std.testing.expectEqual(@as(u64, 28), std.mem.readInt(u64, out[0..8], .little));
    try std.testing.expectEqual(@as(i32, 8), std.mem.readInt(i32, out[12..16], .little));
    try std.testing.expectEqual(@as(i32, 1), std.mem.readInt(i32, out[16..20], .little));
    try std.testing.expectEqualSlices(u8, &.{ 127, 0, 0, 5, 127, 0, 0, 5 }, out[20..28]);
    try std.testing.expectEqual(@as(u64, 20), std.mem.readInt(u64, out[32..40], .little));
    try std.testing.expectEqual(@as(i32, 2), std.mem.readInt(i32, out[44..48], .little));
    try std.testing.expectEqual(@as(i32, 33), std.mem.readInt(i32, out[48..52], .little));
    try std.testing.expectEqual(@as(u64, 17), std.mem.readInt(u64, out[56..64], .little));
    try std.testing.expectEqual(@as(i32, 1), std.mem.readInt(i32, out[68..72], .little));
    try std.testing.expectEqual(@as(u8, 0x28), out[72]);
    // A 40-byte buffer: PKTINFO fits; 8 bytes are left, no room for a header, so the rest is dropped with MSG_CTRUNC.
    const cut = c.build(.{ .pktinfo = true, .recvttl = true, .recvtos = true }, info, 40, &out);
    try std.testing.expectEqual(@as(usize, 32), cut.written);
    // 50 bytes: the TTL message is cut to the 18 left (cmsg_len 18) and uses them up.
    const cut2 = c.build(.{ .pktinfo = true, .recvttl = true }, info, 50, &out);
    try std.testing.expectEqual(@as(usize, 50), cut2.written);
    try std.testing.expect(cut2.truncated);
    try std.testing.expectEqual(@as(u64, 18), std.mem.readInt(u64, out[32..40], .little));
    try std.testing.expect(cut.truncated);
    // Nothing set: nothing written, no truncation; no buffer with a flag set: MSG_CTRUNC.
    try std.testing.expectEqual(@as(usize, 0), c.build(.{}, info, 128, &out).written);
    try std.testing.expect(!c.build(.{}, info, 0, &out).truncated);
    try std.testing.expect(c.build(.{ .recvtos = true }, info, 0, &out).truncated);

    const us = kt.udp_source;
    try std.testing.expect(std.mem.indexOf(u8, us, "pub fn handlePacketMeta(src_ip: [4]u8, dst_ip: [4]u8, data: [*]const u8, len: u32, ifindex: u8, ttl: u8, tos: u8) void {") != null);
    try std.testing.expect(std.mem.indexOf(u8, kt.net_mod_source, "udp.handlePacketMetaInfo(info.src_ip, info.dst_ip, data + payload_start, info.payload_len, meta4);") != null);
    const ss = kt.socket_syscall_source;
    try std.testing.expect(std.mem.indexOf(u8, ss, "ip_cmsg_policy.build(ip_cmsg_policy.Wanted.of(opts_ip).withStamp(sol_flags), meta, ctl_cap, &ctl_buf);") != null);
}

test "IPv6 UDP receive control messages IPV6_RECVPKTINFO / IPV6_RECVHOPLIMIT / IPV6_RECVTCLASS (hello422): Linux ip6_datagram_recv_*_ctl" {
    const p = kt.ip_opt_policy;
    var o: p.IpOpts = .{};
    try std.testing.expectEqual(@as(?i32, 0), p.getValue(o, p.SOL_IPV6, p.IPV6_RECVPKTINFO));
    o = p.applySet(o, p.SOL_IPV6, p.IPV6_RECVPKTINFO, &.{ 5, 0, 0, 0 }).ok;
    o = p.applySet(o, p.SOL_IPV6, p.IPV6_RECVTCLASS, &.{ 1, 0, 0, 0 }).ok;
    try std.testing.expectEqual(@as(?i32, 1), p.getValue(o, p.SOL_IPV6, p.IPV6_RECVPKTINFO));
    try std.testing.expectEqual(@as(?i32, 0), p.getValue(o, p.SOL_IPV6, p.IPV6_RECVHOPLIMIT));
    try std.testing.expectEqual(@as(?i32, 1), p.getValue(o, p.SOL_IPV6, p.IPV6_RECVTCLASS));
    // A full int is required (optlen < sizeof(int) is EINVAL).
    try std.testing.expectEqual(@as(i64, -22), p.applySet(o, p.SOL_IPV6, p.IPV6_RECVHOPLIMIT, &.{1}).err);

    const c = kt.ip_cmsg_policy;
    var dst: [16]u8 = @splat(0);
    dst[15] = 1;
    const info: c.RecvInfo6 = .{ .ifindex = 1, .dst = dst, .hops = 33, .tclass = 0x28 };
    var out: [128]u8 = undefined;
    const all = c.build6(.{ .pktinfo = true, .recvttl = true, .recvtos = true }, info, 128, &out);
    try std.testing.expectEqual(@as(usize, 88), all.written);
    try std.testing.expectEqual(@as(u64, 36), std.mem.readInt(u64, out[0..8], .little));
    try std.testing.expectEqual(@as(i32, 41), std.mem.readInt(i32, out[8..12], .little));
    try std.testing.expectEqual(@as(i32, 50), std.mem.readInt(i32, out[12..16], .little));
    try std.testing.expectEqualSlices(u8, &dst, out[16..32]);
    try std.testing.expectEqual(@as(i32, 1), std.mem.readInt(i32, out[32..36], .little));
    try std.testing.expectEqual(@as(i32, 52), std.mem.readInt(i32, out[52..56], .little));
    try std.testing.expectEqual(@as(i32, 33), std.mem.readInt(i32, out[56..60], .little));
    try std.testing.expectEqual(@as(i32, 67), std.mem.readInt(i32, out[76..80], .little));
    try std.testing.expectEqual(@as(i32, 0x28), std.mem.readInt(i32, out[80..84], .little));
    const cut = c.build6(.{ .pktinfo = true, .recvttl = true, .recvtos = true }, info, 48, &out);
    try std.testing.expectEqual(@as(usize, 40), cut.written);
    try std.testing.expect(cut.truncated);
    try std.testing.expectEqual(c.Wanted{ .pktinfo = true, .recvttl = false, .recvtos = true }, c.Wanted.of6(o));

    try std.testing.expect(std.mem.indexOf(u8, kt.udp_source, "pub fn handlePacketV6Meta(src_ip: [16]u8, dst_ip: [16]u8, data: [*]const u8, len: u32, ifindex: u8, hops: u8, tclass: u8, flowinfo: u32) void {") != null);
    try std.testing.expect(std.mem.indexOf(u8, kt.net_mod_source, "udp.handlePacketV6Info(info6.src_ip, info6.dst_ip, data + up_start, up_len, .{ .ifindex = ifindex, .dst = info6.dst_ip, .hops = info6.hop_limit, .tclass = info6.tclass, .flowinfo = info6.flowinfo, .mark = skb.mark, .priority = skb.priority });") != null);
    try std.testing.expect(std.mem.indexOf(u8, kt.socket_syscall_source, "ip_cmsg_policy.build6(ip_cmsg_policy.Wanted.of6(opts_ip).withStamp(sol_flags), meta6, ctl_cap, &ctl_buf)") != null);
}

test "IPv4 UDP sendmsg control messages IP_TTL / IP_TOS / IP_PKTINFO (hello423): Linux udp_cmsg_send, ip_cmsg_send, __sock_cmsg_send" {
    const c = kt.ip_cmsg_policy;
    var b: [256]u8 = @splat(0);
    const W = struct {
        fn put(buf: []u8, off: usize, level: i32, typ: i32, data: []const u8, len: ?u64) usize {
            const l: u64 = len orelse 16 + data.len;
            std.mem.writeInt(u64, buf[off..][0..8], l, .little);
            std.mem.writeInt(i32, buf[off + 8 ..][0..4], level, .little);
            std.mem.writeInt(i32, buf[off + 12 ..][0..4], typ, .little);
            @memcpy(buf[off + 16 ..][0..data.len], data);
            return off + ((16 + data.len + 7) & ~@as(usize, 7));
        }
    };
    const no_caps: c.SendCaps = .{};
    // No message at all, or a buffer shorter than one header.
    try std.testing.expectEqual(c.Send4{}, c.parseSend4(b[0..0], no_caps).ok);
    try std.testing.expectEqual(c.Send4{}, c.parseSend4(b[0..8], no_caps).ok);
    // IP_TTL 7 and IP_TOS 0x4b (an int) override the socket's values; a one-byte IP_TOS works too.
    var o = W.put(&b, 0, 0, 2, &.{ 7, 0, 0, 0 }, null);
    o = W.put(&b, o, 0, 1, &.{ 0x4b, 0, 0, 0 }, null);
    const both = c.parseSend4(b[0..o], no_caps).ok;
    try std.testing.expectEqual(@as(?u8, 7), both.ttl);
    try std.testing.expectEqual(@as(?u8, 0x4b), both.tos);
    o = W.put(&b, 0, 0, 1, &.{0x51}, null);
    try std.testing.expectEqual(@as(?u8, 0x51), c.parseSend4(b[0..o], no_caps).ok.tos);
    // IP_PKTINFO: the interface and ipi_spec_dst; ipi_addr is not looked at.
    o = W.put(&b, 0, 0, 8, &.{ 1, 0, 0, 0, 127, 0, 0, 5, 127, 0, 0, 9 }, null);
    const pk = c.parseSend4(b[0..o], no_caps).ok;
    try std.testing.expect(pk.pktinfo);
    try std.testing.expectEqual(@as(u32, 1), pk.oif);
    try std.testing.expectEqual([4]u8{ 127, 0, 0, 5 }, pk.spec_dst);
    // Skipped: SCM_RIGHTS, SCM_CREDENTIALS, other levels, IPV6_PKTINFO on an IPv4 socket, a valid UDP_SEGMENT.
    o = W.put(&b, 0, 1, 1, &.{ 3, 0, 0, 0 }, null);
    o = W.put(&b, o, 6, 1, &.{ 3, 0, 0, 0 }, null);
    o = W.put(&b, o, 41, 50, &(@as([20]u8, @splat(0))), null);
    o = W.put(&b, o, 17, 103, &.{ 0, 4 }, null);
    try std.testing.expectEqual(c.Send4{}, c.parseSend4(b[0..o], no_caps).ok);
    // EINVAL for each malformed message.
    const bad = [_]struct { lv: i32, ty: i32, d: []const u8, len: ?u64 }{
        .{ .lv = 0, .ty = 2, .d = &.{ 0, 0, 0, 0 }, .len = null }, // IP_TTL 0
        .{ .lv = 0, .ty = 2, .d = &.{ 0, 1, 0, 0 }, .len = null }, // IP_TTL 256
        .{ .lv = 0, .ty = 2, .d = &.{5}, .len = null }, // a 1-byte IP_TTL
        .{ .lv = 0, .ty = 1, .d = &.{ 0, 1, 0, 0 }, .len = null }, // IP_TOS 256
        .{ .lv = 0, .ty = 1, .d = &.{ 0xff, 0xff, 0xff, 0xff }, .len = null }, // IP_TOS -1
        .{ .lv = 0, .ty = 1, .d = &.{ 3, 0 }, .len = null }, // a 2-byte IP_TOS
        .{ .lv = 0, .ty = 99, .d = &.{ 3, 0, 0, 0 }, .len = null }, // unknown IP-level type
        .{ .lv = 0, .ty = 2, .d = &.{ 3, 0, 0, 0 }, .len = 12 }, // cmsg_len shorter than the header
        .{ .lv = 0, .ty = 2, .d = &.{ 3, 0, 0, 0 }, .len = 64 }, // cmsg_len past the end
        .{ .lv = 1, .ty = 99, .d = &.{ 3, 0, 0, 0 }, .len = null }, // unknown SOL_SOCKET type
        .{ .lv = 0, .ty = 8, .d = &(@as([16]u8, @splat(0))), .len = null }, // IP_PKTINFO of 16 bytes
        .{ .lv = 17, .ty = 103, .d = &.{ 1, 2, 3, 4 }, .len = null }, // UDP_SEGMENT of 4 bytes
        .{ .lv = 17, .ty = 1, .d = &.{ 1, 2 }, .len = null }, // unknown SOL_UDP type
        .{ .lv = 1, .ty = 61, .d = &(@as([8]u8, @splat(0))), .len = null }, // SCM_TXTIME without SO_TXTIME
        .{ .lv = 1, .ty = 37, .d = &.{ 0, 0, 1, 0 }, .len = null }, // SO_TIMESTAMPING with a receive flag
    };
    for (bad) |x| {
        @memset(&b, 0);
        const n = W.put(&b, 0, x.lv, x.ty, x.d, x.len);
        const end: usize = if (x.len != null and x.len.? > n) 24 else n;
        try std.testing.expectEqual(@as(i64, -22), c.parseSend4(b[0..end], no_caps).err);
    }
    // SO_MARK needs CAP_NET_RAW or CAP_NET_ADMIN (EPERM first, then the length); SO_PRIORITY above 6 needs them too.
    o = W.put(&b, 0, 1, 36, &.{ 1, 0, 0, 0 }, null);
    try std.testing.expectEqual(@as(i64, -1), c.parseSend4(b[0..o], no_caps).err);
    try std.testing.expect(c.parseSend4(b[0..o], .{ .net_admin = true }) == .ok);
    o = W.put(&b, 0, 1, 36, &.{ 1, 0 }, null);
    try std.testing.expectEqual(@as(i64, -1), c.parseSend4(b[0..o], no_caps).err);
    o = W.put(&b, 0, 1, 12, &.{ 6, 0, 0, 0 }, null);
    try std.testing.expect(c.parseSend4(b[0..o], no_caps) == .ok);
    o = W.put(&b, 0, 1, 12, &.{ 7, 0, 0, 0 }, null);
    try std.testing.expectEqual(@as(i64, -1), c.parseSend4(b[0..o], no_caps).err);
    // udp_cmsg_send looks at every SOL_UDP message before ip_cmsg_send: a bad UDP_SEGMENT after a SO_MARK is EINVAL, not EPERM.
    o = W.put(&b, 0, 1, 36, &.{ 1, 0, 0, 0 }, null);
    o = W.put(&b, o, 17, 103, &.{1}, null);
    try std.testing.expectEqual(@as(i64, -22), c.parseSend4(b[0..o], no_caps).err);

    // ipi_spec_dst as a source (ip_route_output_key_hash_rcu): 0 lets the stack choose, a group / broadcast / 0.x.y.z address is
    // EINVAL, an address of no interface ENETUNREACH. The interface must exist (ENODEV).
    try std.testing.expectEqual(@as(i64, 0), c.sourceErrno4(.{ 0, 0, 0, 0 }, .{ 10, 0, 2, 15 }, true));
    try std.testing.expectEqual(@as(i64, 0), c.sourceErrno4(.{ 127, 0, 0, 5 }, .{ 10, 0, 2, 15 }, false));
    try std.testing.expectEqual(@as(i64, 0), c.sourceErrno4(.{ 10, 0, 2, 15 }, .{ 10, 0, 2, 15 }, true));
    try std.testing.expectEqual(@as(i64, -101), c.sourceErrno4(.{ 10, 0, 2, 15 }, .{ 10, 0, 2, 15 }, false));
    try std.testing.expectEqual(@as(i64, -101), c.sourceErrno4(.{ 192, 0, 2, 1 }, .{ 10, 0, 2, 15 }, true));
    try std.testing.expectEqual(@as(i64, -101), c.sourceErrno4(.{ 10, 0, 2, 255 }, .{ 10, 0, 2, 15 }, true));
    try std.testing.expectEqual(@as(i64, -22), c.sourceErrno4(.{ 224, 0, 0, 1 }, .{ 10, 0, 2, 15 }, true));
    try std.testing.expectEqual(@as(i64, -22), c.sourceErrno4(.{ 255, 255, 255, 255 }, .{ 10, 0, 2, 15 }, true));
    try std.testing.expectEqual(@as(i64, -22), c.sourceErrno4(.{ 0, 1, 2, 3 }, .{ 10, 0, 2, 15 }, true));
    try std.testing.expectEqual(@as(i64, 0), c.oifErrno4(0, false));
    try std.testing.expectEqual(@as(i64, 0), c.oifErrno4(1, false));
    try std.testing.expectEqual(@as(i64, 0), c.oifErrno4(2, true));
    try std.testing.expectEqual(@as(i64, -19), c.oifErrno4(2, false));
    try std.testing.expectEqual(@as(i64, -19), c.oifErrno4(99, true));

    const ss = kt.socket_syscall_source;
    try std.testing.expect(std.mem.indexOf(u8, ss, "ip_cmsg_policy.parseSend4(control, sendCaps())") != null);
    try std.testing.expect(std.mem.indexOf(u8, kt.udp_source, "pub fn sendToFromOv(") != null);
}

test "IPv6 UDP sendmsg control messages IPV6_HOPLIMIT / IPV6_TCLASS / IPV6_PKTINFO (hello424): Linux ip6_datagram_send_ctl" {
    const c = kt.ip_cmsg_policy;
    var b: [256]u8 = @splat(0);
    const W = struct {
        fn put(buf: []u8, off: usize, level: i32, typ: i32, data: []const u8, len: ?u64) usize {
            const l: u64 = len orelse 16 + data.len;
            std.mem.writeInt(u64, buf[off..][0..8], l, .little);
            std.mem.writeInt(i32, buf[off + 8 ..][0..4], level, .little);
            std.mem.writeInt(i32, buf[off + 12 ..][0..4], typ, .little);
            @memcpy(buf[off + 16 ..][0..data.len], data);
            return off + ((16 + data.len + 7) & ~@as(usize, 7));
        }
        fn int(v: i32) [4]u8 {
            var o: [4]u8 = undefined;
            std.mem.writeInt(i32, &o, v, .little);
            return o;
        }
        fn pk(addr: [16]u8, ifx: u32) [20]u8 {
            var o: [20]u8 = undefined;
            @memcpy(o[0..16], &addr);
            std.mem.writeInt(u32, o[16..20], ifx, .little);
            return o;
        }
        var own: [16]u8 = .{ 0x20, 0x01, 0x0d, 0xb8 } ++ @as([11]u8, @splat(0)) ++ .{0x15};
        var own_ll: [16]u8 = .{ 0xfe, 0x80 } ++ @as([13]u8, @splat(0)) ++ .{0x15};
        fn isOwn(a: [16]u8) bool {
            return std.mem.eql(u8, &a, &own) or std.mem.eql(u8, &a, &own_ll);
        }
    };
    const lo6: [16]u8 = @as([15]u8, @splat(0)) ++ .{1};
    const any6: [16]u8 = @splat(0);
    const caps: c.SendCaps = .{};
    const ctx: c.Ctx6 = .{ .nic_active = true, .isOwnNic = W.isOwn };
    try std.testing.expectEqual(c.Send6{}, c.parseSend6(b[0..0], caps, ctx).ok);
    // IPV6_HOPLIMIT 7 (and RFC 2292's IPV6_2292HOPLIMIT 8), 0 is a hop limit too, -1 keeps the socket's; IPV6_TCLASS 0x4b, -1 sends 0xff.
    var o = W.put(&b, 0, 41, 52, &W.int(7), null);
    o = W.put(&b, o, 41, 67, &W.int(0x4b), null);
    const both = c.parseSend6(b[0..o], caps, ctx).ok;
    try std.testing.expectEqual(@as(?u8, 7), both.hops);
    try std.testing.expectEqual(@as(?u8, 0x4b), both.tclass);
    o = W.put(&b, 0, 41, 8, &W.int(0), null);
    try std.testing.expectEqual(@as(?u8, 0), c.parseSend6(b[0..o], caps, ctx).ok.hops);
    o = W.put(&b, 0, 41, 52, &W.int(-1), null);
    try std.testing.expectEqual(@as(?u8, null), c.parseSend6(b[0..o], caps, ctx).ok.hops);
    o = W.put(&b, 0, 41, 67, &W.int(-1), null);
    try std.testing.expectEqual(@as(?u8, 0xff), c.parseSend6(b[0..o], caps, ctx).ok.tclass);
    // Skipped: IPV6_FLOWINFO, SOL_IP, SCM_RIGHTS. IPV6_DONTFRAG 1 is recorded for the send (hello461; it was only checked before).
    o = W.put(&b, 0, 41, 62, &W.int(1), null);
    o = W.put(&b, o, 41, 11, &W.int(1), null);
    o = W.put(&b, o, 0, 2, &W.int(3), null);
    o = W.put(&b, o, 1, 1, &W.int(3), null);
    // hello462: IPV6_FLOWINFO's label (here an int 1, so label 0x1000000 & 0xFFFFF = 0) is recorded too.
    try std.testing.expectEqual(c.Send6{ .dontfrag = true, .flowlabel = 0 }, c.parseSend6(b[0..o], caps, ctx).ok);
    // EINVAL.
    const bad = [_]struct { ty: i32, d: []const u8 }{
        .{ .ty = 52, .d = &W.int(256) }, .{ .ty = 52, .d = &W.int(-2) }, .{ .ty = 52, .d = &.{5} },
        .{ .ty = 67, .d = &W.int(256) }, .{ .ty = 67, .d = &W.int(-2) }, .{ .ty = 67, .d = &.{5} },
        .{ .ty = 62, .d = &W.int(2) },   .{ .ty = 99, .d = &W.int(3) },  .{ .ty = 50, .d = &(@as([16]u8, @splat(0))) },
        .{ .ty = 57, .d = &.{ 0, 0, 0, 0 } }, // a type 0 routing header
    };
    for (bad) |x| {
        @memset(&b, 0);
        const n = W.put(&b, 0, 41, x.ty, x.d, null);
        try std.testing.expectEqual(@as(i64, -22), c.parseSend6(b[0..n], caps, ctx).err);
    }
    // Extension headers need CAP_NET_RAW (and are not sent: EOPNOTSUPP once allowed).
    o = W.put(&b, 0, 41, 54, &.{ 17, 0, 1, 4, 0, 0, 0, 0 }, null);
    try std.testing.expectEqual(@as(i64, -1), c.parseSend6(b[0..o], caps, ctx).err);
    try std.testing.expectEqual(@as(i64, -95), c.parseSend6(b[0..o], .{ .net_raw = true }, ctx).err);
    o = W.put(&b, 0, 41, 54, &.{ 17, 1, 1, 4, 0, 0, 0, 0 }, null); // hdrlen 1 says 16 bytes, only 8 given
    try std.testing.expectEqual(@as(i64, -22), c.parseSend6(b[0..o], caps, ctx).err);

    // IPV6_PKTINFO: :: and interface 0 change nothing; ::1 (also on lo) or an address of the NIC is the source; an interface that
    // does not exist is ENODEV; a link-local source needs an interface; an address that is not ours, or a group, is EINVAL.
    o = W.put(&b, 0, 41, 50, &W.pk(any6, 0), null);
    const p0 = c.parseSend6(b[0..o], caps, ctx).ok;
    try std.testing.expect(p0.pktinfo and p0.oif == 0 and std.mem.eql(u8, &p0.src, &any6));
    o = W.put(&b, 0, 41, 50, &W.pk(lo6, 1), null);
    const p1 = c.parseSend6(b[0..o], caps, ctx).ok;
    try std.testing.expect(p1.oif == 1 and std.mem.eql(u8, &p1.src, &lo6));
    o = W.put(&b, 0, 41, 2, &W.pk(W.own, 0), null);
    try std.testing.expectEqualSlices(u8, &W.own, &c.parseSend6(b[0..o], caps, ctx).ok.src);
    o = W.put(&b, 0, 41, 50, &(W.pk(W.own_ll, 2) ++ @as([4]u8, @splat(0))), null);
    try std.testing.expectEqual(@as(u32, 2), c.parseSend6(b[0..o], caps, ctx).ok.oif);
    o = W.put(&b, 0, 41, 50, &W.pk(any6, 99), null);
    try std.testing.expectEqual(@as(i64, -19), c.parseSend6(b[0..o], caps, ctx).err);
    o = W.put(&b, 0, 41, 50, &W.pk(any6, 2), null);
    try std.testing.expectEqual(@as(i64, -19), c.parseSend6(b[0..o], caps, .{ .isOwnNic = W.isOwn }).err);
    o = W.put(&b, 0, 41, 50, &W.pk(W.own_ll, 0), null);
    try std.testing.expectEqual(@as(i64, -22), c.parseSend6(b[0..o], caps, ctx).err);
    o = W.put(&b, 0, 41, 50, &W.pk(lo6, 2), null);
    try std.testing.expectEqual(@as(i64, -22), c.parseSend6(b[0..o], caps, ctx).err);
    var other: [16]u8 = W.own;
    other[15] = 0x99;
    o = W.put(&b, 0, 41, 50, &W.pk(other, 0), null);
    try std.testing.expectEqual(@as(i64, -22), c.parseSend6(b[0..o], caps, ctx).err);
    const grp: [16]u8 = .{ 0xff, 0x02 } ++ @as([13]u8, @splat(0)) ++ .{1};
    o = W.put(&b, 0, 41, 50, &W.pk(grp, 0), null);
    try std.testing.expectEqual(@as(i64, -22), c.parseSend6(b[0..o], caps, ctx).err);
    // An interface that differs from the one the destination's scope (or the socket's binding) chose is EINVAL.
    o = W.put(&b, 0, 41, 50, &W.pk(any6, 2), null);
    try std.testing.expectEqual(@as(i64, -22), c.parseSend6(b[0..o], caps, .{ .pre_oif = 1, .nic_active = true, .isOwnNic = W.isOwn }).err);
    try std.testing.expect(c.parseSend6(b[0..o], caps, .{ .pre_oif = 2, .nic_active = true, .isOwnNic = W.isOwn }) == .ok);
    // Messages are handled in order: a bad IPV6_PKTINFO before a bad IPV6_HOPLIMIT reports its own error.
    o = W.put(&b, 0, 41, 50, &W.pk(any6, 99), null);
    o = W.put(&b, o, 41, 52, &W.int(999), null);
    try std.testing.expectEqual(@as(i64, -19), c.parseSend6(b[0..o], caps, ctx).err);

    const ss = kt.socket_syscall_source;
    try std.testing.expect(std.mem.indexOf(u8, ss, "ip_cmsg_policy.parseSend6(control, sendCaps(), ctx6)") != null);
    try std.testing.expect(std.mem.indexOf(u8, kt.udp_source, "pub fn sendToV6FromOv(") != null);
}

test "IPv4 ping socket sendmsg control messages IP_TTL / IP_TOS / IP_PKTINFO (hello425): Linux ping_v4_sendmsg -> ip_cmsg_send" {
    const c = kt.ip_cmsg_policy;
    var b: [256]u8 = @splat(0);
    const W = struct {
        fn put(buf: []u8, off: usize, level: i32, typ: i32, data: []const u8, len: ?u64) usize {
            const l: u64 = len orelse 16 + data.len;
            std.mem.writeInt(u64, buf[off..][0..8], l, .little);
            std.mem.writeInt(i32, buf[off + 8 ..][0..4], level, .little);
            std.mem.writeInt(i32, buf[off + 12 ..][0..4], typ, .little);
            @memcpy(buf[off + 16 ..][0..data.len], data);
            return off + ((16 + data.len + 7) & ~@as(usize, 7));
        }
    };
    const no_caps: c.SendCaps = .{};
    try std.testing.expectEqual(c.Send4{}, c.parseSendPing4(b[0..0], no_caps).ok);
    // A ping socket has no udp_cmsg_send pass: SOL_UDP messages are skipped, a bad UDP_SEGMENT too.
    var o = W.put(&b, 0, 17, 103, &.{ 1, 2, 3, 4 }, null);
    o = W.put(&b, o, 17, 1, &.{1}, null);
    try std.testing.expectEqual(c.Send4{}, c.parseSendPing4(b[0..o], no_caps).ok);
    try std.testing.expectEqual(@as(i64, -22), c.parseSend4(b[0..o], no_caps).err);
    // The IP-level rules are those of a UDP socket.
    o = W.put(&b, 0, 0, 2, &.{ 9, 0, 0, 0 }, null);
    o = W.put(&b, o, 0, 1, &.{0x60}, null);
    o = W.put(&b, o, 0, 8, &.{ 1, 0, 0, 0, 127, 0, 0, 5, 0, 0, 0, 0 }, null);
    const v = c.parseSendPing4(b[0..o], no_caps).ok;
    try std.testing.expectEqual(@as(?u8, 9), v.ttl);
    try std.testing.expectEqual(@as(?u8, 0x60), v.tos);
    try std.testing.expect(v.pktinfo);
    try std.testing.expectEqual([4]u8{ 127, 0, 0, 5 }, v.spec_dst);
    o = W.put(&b, 0, 0, 2, &.{ 0, 0, 0, 0 }, null);
    try std.testing.expectEqual(@as(i64, -22), c.parseSendPing4(b[0..o], no_caps).err);
    o = W.put(&b, 0, 1, 99, &.{ 0, 0, 0, 0 }, null);
    try std.testing.expectEqual(@as(i64, -22), c.parseSendPing4(b[0..o], no_caps).err);
    o = W.put(&b, 0, 1, 36, &.{ 1, 0, 0, 0 }, null);
    try std.testing.expectEqual(@as(i64, -1), c.parseSendPing4(b[0..o], no_caps).err);

    // The echo request carries the socket's IP_TTL / IP_TOS (ipcm_init_sk), overridden per request by the control messages.
    const ss = kt.socket_syscall_source;
    try std.testing.expect(std.mem.indexOf(u8, ss, "ip_cmsg_policy.parseSendPing4(control, sendCaps())") != null);
    try std.testing.expect(std.mem.indexOf(u8, ss, "return pingSend(d, payload, addr_ptr, addr_len, control);") != null);
    try std.testing.expect(std.mem.indexOf(u8, kt.icmp_source, "pub fn sendFromOv(") != null);
    // The test runs as root (it writes ping_group_range) with CAP_NET_RAW for the raw socket that watches the requests.
    const prof = kt.capability_profile.profileForLaunch("hello425", true, false);
    try std.testing.expectEqual(@as(u32, 0), prof.uid);
    try std.testing.expect(prof.caps.cap_net_raw);
}

test "IPv4 raw socket sendmsg control messages IP_TTL / IP_TOS / IP_PKTINFO / IP_RETOPTS (hello426): Linux raw_sendmsg -> ip_cmsg_send" {
    const c = kt.ip_cmsg_policy;
    var b: [64]u8 = @splat(0);
    // An empty IP_RETOPTS is accepted but still gives the datagram an options block (ip_options_get), which IP_HDRINCL refuses.
    std.mem.writeInt(u64, b[0..8], 16, .little);
    std.mem.writeInt(i32, b[8..12], 0, .little);
    std.mem.writeInt(i32, b[12..16], 7, .little);
    const r = c.parseSendPing4(b[0..16], .{}).ok;
    try std.testing.expect(r.retopts);
    try std.testing.expect(!c.parseSendPing4(b[0..0], .{}).ok.retopts);

    // The control messages are parsed after the destination check and before the length / ICMP header checks.
    const ss = kt.socket_syscall_source;
    const fs = std.mem.indexOf(u8, ss, "pub fn rawSendFrom(d: *const vfs_mod.FileDescriptor, msg: []const u8, to: ?RawDest, control: []const u8) i64 {") orelse return error.TestUnexpectedResult;
    const dest = std.mem.indexOfPos(u8, ss, fs, "const rc = rp.sendtoErrno(false, 0, 0, raw.isConnected(d.raw_idx));") orelse return error.TestUnexpectedResult;
    const parse = std.mem.indexOfPos(u8, ss, fs, "ip_cmsg_policy.parseSendPing4(control, sendCaps())") orelse return error.TestUnexpectedResult;
    const hdr_opts = std.mem.indexOfPos(u8, ss, fs, "if (hdrincl and (ov.retopts or sock_opts.set)) return -22;") orelse return error.TestUnexpectedResult;
    const len = std.mem.indexOfPos(u8, ss, fs, "const lrc = if (hdrincl) rp.hdrinclErrno(msg) else rp.sendLengthErrno(protocol, msg.len);") orelse return error.TestUnexpectedResult;
    try std.testing.expect(dest < parse and parse < hdr_opts and hdr_opts < len);
    try std.testing.expect(std.mem.indexOf(u8, ss, "return rawSendFrom(d, data[0..@intCast(got)], if (name_ptr != 0) RawDest{ .ptr = name_ptr, .len = name_len } else null, ctl[0..cl]);") != null);
    // The test opens raw sockets: CAP_NET_RAW.
    try std.testing.expect(kt.capability_profile.profileForLaunch("hello426", true, false).caps.cap_net_raw);
}

test "IPv6 raw socket sendmsg control messages IPV6_HOPLIMIT / IPV6_TCLASS / IPV6_PKTINFO (hello427): Linux rawv6_sendmsg -> ip6_datagram_send_ctl" {
    const c = kt.ip_cmsg_policy;
    var b: [64]u8 = @splat(0);
    const W = struct {
        fn put(buf: []u8, off: usize, level: i32, typ: i32, data: []const u8) usize {
            std.mem.writeInt(u64, buf[off..][0..8], 16 + data.len, .little);
            std.mem.writeInt(i32, buf[off + 8 ..][0..4], level, .little);
            std.mem.writeInt(i32, buf[off + 12 ..][0..4], typ, .little);
            @memcpy(buf[off + 16 ..][0..data.len], data);
            return off + ((16 + data.len + 7) & ~@as(usize, 7));
        }
    };
    // No udp_cmsg_send pass: a 4-byte UDP_SEGMENT is skipped, where a UDP socket refuses it.
    var o = W.put(&b, 0, 17, 103, &.{ 1, 2, 3, 4 });
    try std.testing.expect(c.parseSendRaw6(b[0..o], .{}, .{}) == .ok);
    try std.testing.expectEqual(@as(i64, -22), c.parseSend6(b[0..o], .{}, .{}).err);
    // ip6_datagram_send_ctl's rules otherwise: hop limit 0 is a hop limit, tclass -1 sends 0xff, a bad value is EINVAL.
    o = W.put(&b, 0, 41, 52, &.{ 0, 0, 0, 0 });
    o = W.put(&b, o, 41, 67, &.{ 0xff, 0xff, 0xff, 0xff });
    const v = c.parseSendRaw6(b[0..o], .{}, .{}).ok;
    try std.testing.expectEqual(@as(?u8, 0), v.hops);
    try std.testing.expectEqual(@as(?u8, 0xff), v.tclass);
    o = W.put(&b, 0, 41, 52, &.{ 0, 1, 0, 0 });
    try std.testing.expectEqual(@as(i64, -22), c.parseSendRaw6(b[0..o], .{}, .{}).err);

    // Parsed after the destination checks and before the length check; the per-datagram values reach the IPv6 header.
    const ss = kt.socket_syscall_source;
    const fs = std.mem.indexOf(u8, ss, "fn rawSendFrom6(d: *const vfs_mod.FileDescriptor, msg: []const u8, to: ?RawDest, control: []const u8) i64 {") orelse return error.TestUnexpectedResult;
    const dest = std.mem.indexOfPos(u8, ss, fs, "const rc = rp.sendtoErrno6(false, 0, 0, 0, raw.isConnected(d.raw_idx), raw.protocolOf(d.raw_idx));") orelse return error.TestUnexpectedResult;
    const parse = std.mem.indexOfPos(u8, ss, fs, "ip_cmsg_policy.parseSendRaw6(control, sendCaps(), ctx6)") orelse return error.TestUnexpectedResult;
    const len = std.mem.indexOfPos(u8, ss, fs, "const lrc = rp.lengthErrno6(") orelse return error.TestUnexpectedResult;
    try std.testing.expect(dest < parse and parse < len);
    try std.testing.expect(std.mem.indexOf(u8, ss, "if (raw.isV6(d.raw_idx)) return rawSendFrom6(d, msg, to, control);") != null);
    try std.testing.expect(std.mem.indexOf(u8, kt.icmpv6_source, "pub fn sendProto6Ov(") != null);
    try std.testing.expect(kt.capability_profile.profileForLaunch("hello427", true, false).caps.cap_net_raw);
}

test "FUTEX_WAIT takes a default stop already pending before its first sleep (hello286 J, CI 44472101531)" {
    // A SIGSTOP whose bit was set while the thread still ran (the sender saw .running and only kicked it) must be taken when the
    // thread enqueues and marks itself .blocked; sleeping with it pending leaves the group stop unreported (the churn thread stayed
    // "S (sleeping)" while the rest of the group was stopped).
    const fs = kt.futex_source;
    const enq = std.mem.indexOf(u8, fs, "if (deadline != 0) armWaitDeadline(cur_idx, bucket, deadline);") orelse return error.TestUnexpectedResult;
    const loop = std.mem.indexOfPos(u8, fs, enq, "while (true) {") orelse return error.TestUnexpectedResult;
    const first = fs[enq..loop];
    try std.testing.expect(std.mem.indexOf(u8, first, "_ = @atomicRmw(u64, &cur_task.pending_signals, .Or, 0, .seq_cst);") != null);
    try std.testing.expect(std.mem.indexOf(u8, first, "const stop_first = sig_first.pendingStop(cur_task);") != null);
    try std.testing.expect(std.mem.indexOf(u8, first, "if (stop_first) _ = sig_first.stopWhileWaiting(cur_task);") != null);
    const rel = std.mem.indexOf(u8, first, "bucket.lock.release(irq_flags);").?;
    try std.testing.expect(rel < std.mem.indexOf(u8, first, "if (stop_first)").?);
}

test "raw socket recvmsg control messages IP_PKTINFO / IP_TTL / IP_TOS and the IPv6 ones (hello428): raw_recvmsg -> ip_cmsg_recv, rawv6_recvmsg -> ip6_datagram_recv_ctl" {
    const c = kt.ip_cmsg_policy;
    // The same layout as a UDP socket's: in_pktinfo, ttl as an int, tos as a byte (80 bytes for all three).
    var out: [96]u8 = undefined;
    const b = c.build(.{ .pktinfo = true, .recvttl = true, .recvtos = true }, .{ .ifindex = 1, .dst = .{ 127, 0, 0, 1 }, .ttl = 33, .tos = 0x28 }, 256, &out);
    try std.testing.expectEqual(@as(usize, 80), b.written);
    // Each queued datagram keeps what it arrived with; recvmsg lays the wanted messages out from it.
    const rs = kt.raw_icmp_source;
    try std.testing.expect(std.mem.indexOf(u8, rs, "meta: @import(\"ip_cmsg_policy.zig\").RecvInfo = .{},") != null);
    try std.testing.expect(std.mem.indexOf(u8, rs, "meta6: @import(\"ip_cmsg_policy.zig\").RecvInfo6 = .{},") != null);
    try std.testing.expect(std.mem.indexOf(u8, rs, "return deliverInfo(protocol, dgram, src, dst, .{ .ifindex = ifindex, .dst = dst, .ttl = if (dgram.len > 8) dgram[8] else 0, .tos = if (dgram.len > 1) dgram[1] else 0 });") != null);
    try std.testing.expect(std.mem.indexOf(u8, rs, "e.meta6 = .{ .ifindex = ifindex, .dst = dst, .hops = hops, .tclass = tclass, .flowinfo = flowinfo, .mark = rx_skb.mark, .priority = rx_skb.priority, .stamp_ns =") != null);
    const ss = kt.socket_syscall_source;
    const fr = std.mem.indexOf(u8, ss, "fn rawRecvmsg(") orelse return error.TestUnexpectedResult;
    _ = std.mem.indexOfPos(u8, ss, fr, "ip_cmsg_policy.build6(ip_cmsg_policy.Wanted.of6(opts_ip).withStamp(rawSolFlags(d.raw_idx)), got_meta.v6, ctl_cap, &ctl_buf)") orelse return error.TestUnexpectedResult;
    _ = std.mem.indexOfPos(u8, ss, fr, "ip_cmsg_policy.build(ip_cmsg_policy.Wanted.of(opts_ip).withStamp(rawSolFlags(d.raw_idx)), got_meta.v4, ctl_cap, &ctl_buf)") orelse return error.TestUnexpectedResult;
    try std.testing.expect(kt.capability_profile.profileForLaunch("hello428", true, false).caps.cap_net_raw);
}

test "IPv6 ping socket sendmsg control messages IPV6_HOPLIMIT / IPV6_TCLASS / IPV6_PKTINFO (hello429): Linux ping_v6_sendmsg -> ip6_datagram_send_ctl" {
    const c = kt.ip_cmsg_policy;
    var b: [64]u8 = @splat(0);
    const W = struct {
        fn put(buf: []u8, off: usize, level: i32, typ: i32, data: []const u8) usize {
            std.mem.writeInt(u64, buf[off..][0..8], 16 + data.len, .little);
            std.mem.writeInt(i32, buf[off + 8 ..][0..4], level, .little);
            std.mem.writeInt(i32, buf[off + 12 ..][0..4], typ, .little);
            @memcpy(buf[off + 16 ..][0..data.len], data);
            return off + ((16 + data.len + 7) & ~@as(usize, 7));
        }
    };
    // ping_v6_sendmsg calls ip6_datagram_send_ctl directly: a 4-byte SOL_UDP UDP_SEGMENT is skipped like any other level.
    var o = W.put(&b, 0, 17, 103, &.{ 1, 2, 3, 4 });
    try std.testing.expect(c.parseSendPing6(b[0..o], .{}, .{}) == .ok);
    o = W.put(&b, 0, 41, 52, &.{ 7, 0, 0, 0 });
    o = W.put(&b, o, 41, 67, &.{ 0x4b, 0, 0, 0 });
    const v = c.parseSendPing6(b[0..o], .{}, .{}).ok;
    try std.testing.expectEqual(@as(?u8, 7), v.hops);
    try std.testing.expectEqual(@as(?u8, 0x4b), v.tclass);
    // IPV6_PKTINFO naming interface 99 is ENODEV, an address this host does not have EINVAL.
    var pk: [20]u8 = @splat(0);
    std.mem.writeInt(u32, pk[16..20], 99, .little);
    o = W.put(&b, 0, 41, 50, &pk);
    try std.testing.expectEqual(@as(i64, -19), c.parseSendPing6(b[0..o], .{}, .{}).err);
    pk = @splat(0);
    pk[0] = 0x20;
    pk[1] = 0x01;
    pk[2] = 0x0d;
    pk[3] = 0xb8;
    pk[15] = 1;
    o = W.put(&b, 0, 41, 50, &pk);
    try std.testing.expectEqual(@as(i64, -22), c.parseSendPing6(b[0..o], .{}, .{}).err);

    // Parsed once the destination is routed, before the request is built; the per-request values and the socket's
    // IPV6_UNICAST_HOPS / IPV6_TCLASS reach the IPv6 header.
    const ss = kt.socket_syscall_source;
    const fs = std.mem.indexOf(u8, ss, "fn pingSend6(d: *vfs_mod.FileDescriptor, payload: []const u8, addr_ptr: u64, addr_len: u32, control: []const u8) i64 {") orelse return error.TestUnexpectedResult;
    const route = std.mem.indexOfPos(u8, ss, fs, "const unreach = bind_addr_policy.routeErrno6(dst, oif);") orelse return error.TestUnexpectedResult;
    const parse = std.mem.indexOfPos(u8, ss, fs, "ip_cmsg_policy.parseSendPing6(control, sendCaps(), ctx6)") orelse return error.TestUnexpectedResult;
    const build = std.mem.indexOfPos(u8, ss, fs, "pp.setIdent(msg[0..payload.len], d.udp_port);") orelse return error.TestUnexpectedResult;
    try std.testing.expect(route < parse and parse < build);
    _ = std.mem.indexOfPos(u8, ss, fs, "@import(\"icmpv6.zig\").sendProto6Ov(d.udp_local_ip6, dst, 58, 2, msg[0..payload.len], ping_ip6, ov6.hops, ov6.tclass)") orelse return error.TestUnexpectedResult;
    try std.testing.expect(std.mem.indexOf(u8, ss, "if (d.udp_is_v6) return pingSend6(d, payload, addr_ptr, addr_len, control);") != null);
    try std.testing.expect(kt.capability_profile.profileForLaunch("hello429", true, false).caps.cap_net_raw);
}

test "ping socket recvmsg control messages IP_PKTINFO / IP_TTL / IP_TOS and the IPv6 ones (hello430): ping_recvmsg -> ip_cmsg_recv, ip6_datagram_recv_*_ctl" {
    const c = kt.ip_cmsg_policy;
    // An echo reply never went through ipv4_pktinfo_prepare: in_pktinfo's spec_dst is 0.0.0.0, ipi_addr the header destination.
    var out: [96]u8 = undefined;
    const b = c.build(.{ .pktinfo = true, .recvttl = true, .recvtos = true }, .{ .ifindex = 1, .dst = .{ 127, 0, 0, 1 }, .spec_dst = .{ 0, 0, 0, 0 }, .ttl = 64, .tos = 0x28 }, 256, &out);
    try std.testing.expectEqual(@as(usize, 80), b.written);
    try std.testing.expectEqualSlices(u8, &.{ 0, 0, 0, 0, 127, 0, 0, 1 }, out[20..28]);
    // A UDP datagram's spec_dst is still its destination.
    _ = c.build(.{ .pktinfo = true }, .{ .ifindex = 1, .dst = .{ 127, 0, 0, 1 } }, 256, &out);
    try std.testing.expectEqualSlices(u8, &.{ 127, 0, 0, 1, 127, 0, 0, 1 }, out[20..28]);
    // The IP layer's values reach the ping socket's queue entry.
    const m = kt.net_mod_source;
    try std.testing.expect(std.mem.indexOf(u8, m, "var meta4: @import(\"ip_cmsg_policy.zig\").RecvInfo = .{ .ifindex = ifindex, .dst = info.dst_ip, .ttl = info.ttl, .tos = info.tos, .mark = skb.mark, .priority = skb.priority };") != null);
    try std.testing.expect(std.mem.indexOf(u8, m, "icmp.handlePacketMeta(info.src_ip, info.dst_ip, data + payload_start, info.payload_len, meta4);") != null);
    try std.testing.expect(std.mem.indexOf(u8, m, "icmpv6.handlePacketMeta(info6.src_ip, info6.dst_ip, data + up_start, up_len, .{ .ifindex = ifindex, .dst = info6.dst_ip, .hops = info6.hop_limit, .tclass = info6.tclass });") != null);
    const us = kt.udp_source;
    const d4 = std.mem.indexOf(u8, us, "pub fn deliverPing(ident: u16, src_ip: [4]u8, dst_ip: [4]u8, msg: []const u8, meta: ip_cmsg_policy.RecvInfo) void {") orelse return error.TestUnexpectedResult;
    const d6 = std.mem.indexOf(u8, us, "pub fn deliverPing6(ident: u16, src_ip: [16]u8, dst_ip: [16]u8, msg: []const u8, meta6: ip_cmsg_policy.RecvInfo6) void {") orelse return error.TestUnexpectedResult;
    _ = std.mem.indexOfPos(u8, us[0..d6], d4, "e.meta = meta;") orelse return error.TestUnexpectedResult;
    _ = std.mem.indexOfPos(u8, us, d6, "e.meta6 = meta6;") orelse return error.TestUnexpectedResult;
    try std.testing.expect(std.mem.indexOf(u8, kt.icmp_source, ".spec_dst = .{ 0, 0, 0, 0 }") != null);
    // The echo reply keeps the request's TOS / traffic class (icmp_reply: ipc.tos = ip_hdr(skb)->tos; icmpv6_echo_reply).
    try std.testing.expect(std.mem.indexOf(u8, kt.icmp_source, "const frame_len = buildEchoReplyMtu(&pkt, data, len, mtu, dst_ip, src_ip, our_mac, dst_mac, meta.tos);") != null);
    try std.testing.expect(std.mem.indexOf(u8, kt.icmp_source, "o[14 + 1] = tos;") != null);
    try std.testing.expect(std.mem.indexOf(u8, kt.icmpv6_source, "pkt[ip_off] = 0x60 | (tclass >> 4);") != null);
    try std.testing.expect(std.mem.indexOf(u8, kt.icmpv6_source, "ECHO_REQUEST => sendEchoReply(src_ip, dst_ip, data, len, meta6.tclass),") != null);
    try std.testing.expect(kt.capability_profile.profileForLaunch("hello430", true, false).caps.cap_net_raw);
}

test "rt_sigprocmask / rt_sigsuspend / rt_sigtimedwait need sigsetsize 8 and rt_sigpending takes up to 8 bytes (hello431)" {
    // Linux kernel/signal.c: sigsetsize != sizeof(sigset_t) is EINVAL before any pointer is touched; rt_sigpending only rejects a
    // size above 8 and copies exactly sigsetsize bytes. The kernel used to accept 4 as a legacy width and ignored the pending size.
    const ap = kt.signal_action_policy;
    try std.testing.expect(ap.sigsetSizeValid(8));
    try std.testing.expect(!ap.sigsetSizeValid(4) and !ap.sigsetSizeValid(0) and !ap.sigsetSizeValid(16));
    try std.testing.expect(ap.pendingSizeValid(0) and ap.pendingSizeValid(4) and ap.pendingSizeValid(8));
    try std.testing.expect(!ap.pendingSizeValid(9) and !ap.pendingSizeValid(16));
    const src = kt.signal_syscall_source;
    const idx = std.mem.indexOf;
    const sp = idx(u8, src, "pub fn sigprocmask(").?;
    const sp_check = idx(u8, src[sp..], "if (!action_policy.sigsetSizeValid(sigsetsize)) return -22;").?;
    const sp_read = idx(u8, src[sp..], "if (set_ptr != 0 and !copy.validateUserBuffer(set_ptr, width)) return -14;").?;
    try std.testing.expect(sp_check < sp_read);
    try std.testing.expect(idx(u8, src[sp..], "if (sigsetsize >= 8) 8 else 4") == null);
    const pd = idx(u8, src, "pub fn rtSigpending(").?;
    const pd_end = idx(u8, src[pd..], "\n}\n").? + pd;
    try std.testing.expect(idx(u8, src[pd..pd_end], "if (!action_policy.pendingSizeValid(sigsetsize)) return -22;") != null);
    try std.testing.expect(idx(u8, src[pd..pd_end], "_ = sigsetsize;") == null);
    try std.testing.expect(idx(u8, src[pd..pd_end], "copy.copyToUser(@ptrFromInt(set_ptr), bytes[0..n], n) != n") != null);
    const su = idx(u8, src, "pub fn rtSigsuspend(").?;
    const su_check = idx(u8, src[su..], "if (!action_policy.sigsetSizeValid(sigsetsize)) return -22;").?;
    const su_ptr = idx(u8, src[su..], "if (mask_ptr == 0 or mask_ptr >= 0x0000_8000_0000_0000) return -14;").?;
    try std.testing.expect(su_check < su_ptr);
    const tw = idx(u8, src, "pub fn rtSigtimedwait(").?;
    try std.testing.expect(idx(u8, src[tw..], "if (!action_policy.sigsetSizeValid(sigset_size)) return -22;\n    if (sigset_ptr == 0") != null);
}

test "SO_SNDTIMEO bounds a blocking TCP connect: EINPROGRESS once it runs out (hello432)" {
    // Linux __inet_stream_connect: timeo = sock_sndtimeo(sk, nonblock); inet_wait_for_connect returns 0 when it expires and the call
    // fails with the EINPROGRESS set before the wait. tcpWaitConnected used to wait with no deadline at all.
    const rp = kt.tcp_recv_policy;
    try std.testing.expectEqual(@as(i64, -115), rp.CONNECT_TIMED_OUT);
    try std.testing.expect(rp.connectDeadlineNs(1000, 0) == null);
    try std.testing.expectEqual(@as(?u64, 1000 + 300 * 1_000_000), rp.connectDeadlineNs(1000, 300));
    const ts = kt.tcp_source;
    const w = std.mem.indexOf(u8, ts, "pub fn tcpWaitConnected(").?;
    const w_end = std.mem.indexOf(u8, ts[w..], "\n}\n").? + w;
    const body = ts[w..w_end];
    try std.testing.expect(std.mem.indexOf(u8, body, "tcp_recv_policy.connectDeadlineNs(tsc.nanos(), sndTimeoutMs(tcb_idx))") != null);
    try std.testing.expect(std.mem.indexOf(u8, body, "if (tcp_recv_policy.timedOut(deadline, tsc.nanos())) return tcp_recv_policy.CONNECT_TIMED_OUT;") != null);
    try std.testing.expect(std.mem.indexOf(u8, body, "poll.waitSlice(deadline)") != null);
    try std.testing.expect(std.mem.indexOf(u8, body, "poll.waitSlice(null)") == null);
}

test "a signal sent to a task asleep in rt_sigtimedwait for it wakes the task at once (hello433)" {
    // Linux do_sigtimedwait: while it sleeps the waited signals are left out of the blocked set, so signal_wake_up wakes the
    // waiter. rt_sigtimedwait used to sleep until a 10 ms poll because kickIfBlocked only woke tasks for actionable signals.
    const ap = kt.signal_action_policy;
    try std.testing.expect(ap.wakesSigwaiter(1 << 9, 1 << 9));
    try std.testing.expect(!ap.wakesSigwaiter(1 << 9, 1 << 11));
    try std.testing.expect(!ap.wakesSigwaiter(1 << 9, 0));
    const ss = kt.signal_syscall_source;
    try std.testing.expect(std.mem.indexOf(u8, ss, "SIGWAIT_POLL_NS") == null);
    const tw = std.mem.indexOf(u8, ss, "pub fn rtSigtimedwait(").?;
    const tw_end = std.mem.indexOf(u8, ss[tw..], "\n}\n").? + tw;
    const body = ss[tw..tw_end];
    try std.testing.expect(std.mem.indexOf(u8, body, "@atomicStore(u64, &cur.sigwait_mask, mask, .release);") != null);
    try std.testing.expect(std.mem.indexOf(u8, body, "@atomicStore(u64, &cur.sigwait_mask, 0, .release);") != null);
    const sg = kt.signal_source;
    const k = std.mem.indexOf(u8, sg, "pub fn kickIfBlocked(").?;
    const k_end = std.mem.indexOf(u8, sg[k..], "\n}\n").? + k;
    try std.testing.expect(std.mem.indexOf(u8, sg[k..k_end], "action_policy.wakesSigwaiter(") != null);
}

test "sendmmsg / recvmmsg batch up to UIO_MAXIOV and recvmmsg writes the time left back (hello434)" {
    // Linux __sys_sendmmsg / do_recvmmsg clamp vlen to UIO_MAXIOV (1024); __sys_recvmmsg writes what remains of the timeout back once
    // a datagram arrived. The batch used to stop at 16 and the timeout was never written.
    const mp = kt.message_batch_policy;
    try std.testing.expectEqual(@as(u64, 1024), mp.MAX_MESSAGES);
    try std.testing.expectEqual(@as(u64, 1024), mp.clampVlen(2000));
    try std.testing.expectEqual(@as(u64, 40), mp.clampVlen(40));
    try std.testing.expectEqual(@as(u64, 0), mp.remainingNs(100, 200));
    try std.testing.expectEqual(@as(u64, 50), mp.remainingNs(150, 100));
    const ss = kt.socket_syscall_source;
    const r = std.mem.indexOf(u8, ss, "pub fn recvmmsg(").?;
    const r_end = std.mem.indexOf(u8, ss[r..], "\n}\n").? + r;
    const body = ss[r..r_end];
    try std.testing.expect(std.mem.indexOf(u8, body, "writeTimeoutLeft(timeout, d, tsc.nanos())") != null);
    // A batch that ends on an error after some messages (MSG_WAITFORONE's EAGAIN) still writes the timeout back.
    try std.testing.expect(std.mem.indexOf(u8, body, "if (result < 0) return mp.batchResult(count, result);") == null);
    const brk = std.mem.indexOf(u8, body, "err = result;\n            break;").?;
    const wr = std.mem.indexOf(u8, body, "writeTimeoutLeft(").?;
    try std.testing.expect(brk < wr);
}

test "lseek on a terminal is ESPIPE: the standard descriptors and /dev/tty (hello435)" {
    // Linux opens a tty without a position (tty_open: no_llseek / FMODE_STREAM), so lseek on stdin/stdout/stderr or /dev/tty is
    // ESPIPE; /dev/null and /dev/zero keep noop_llseek and succeed.
    const sk = kt.fd_seek_policy;
    try std.testing.expect(!sk.seekable("special"));
    try std.testing.expect(sk.seekable("devfs"));
    try std.testing.expect(!sk.devfsSeekable(true));
    try std.testing.expect(sk.devfsSeekable(false));
    const se = kt.syscall_entry_source;
    const l = std.mem.indexOf(u8, se, "fn syscallLseek(").?;
    const l_end = std.mem.indexOf(u8, se[l..], "\n}\n").? + l;
    try std.testing.expect(std.mem.indexOf(u8, se[l..l_end], "if (desc.fd_type == .devfs and !@import(\"../../fs/fd_seek_policy.zig\").devfsSeekable(vfs_mod.isConsoleTty(desc))) return -29;") != null);
}

test "an SA_SIGINFO handler's ucontext points fpregs at the interrupted FPU image (hello436)" {
    // Linux __unsafe_setup_sigcontext stores the user address of the FPU image written on the signal stack in sc->fpstate
    // (uc_mcontext.fpregs). The kernel used to leave it 0 although the FXSAVE image was already in the frame.
    const sf = kt.signal_frame_policy;
    try std.testing.expectEqual(@as(u64, 0x7000 + 16), sf.fpregsAddr(0x7000, 16));
    const sg = kt.signal_source;
    try std.testing.expect(std.mem.indexOf(u8, sg, "uc.fpregs = @import(\"signal_frame_policy.zig\").fpregsAddr(frame_addr, @offsetOf(SignalFrame, \"fpu\"));") != null);
}

test "pidfd_send_signal reads its siginfo and its scope flags (hello437)" {
    // Linux do_pidfd_send_signal: si_signo must equal sig; a non-negative code or SI_TKILL only to the caller's own process; flags
    // PIDFD_SIGNAL_THREAD / _THREAD_GROUP / _PROCESS_GROUP, at most one. The kernel ignored info and rejected every flag.
    const pp = kt.pidfd_signal_policy;
    try std.testing.expect(pp.flagsValid(0) and pp.flagsValid(1) and pp.flagsValid(2) and pp.flagsValid(4));
    try std.testing.expect(!pp.flagsValid(3) and !pp.flagsValid(8) and !pp.flagsValid(6));
    try std.testing.expectEqual(pp.Scope.process, pp.scope(0));
    try std.testing.expectEqual(pp.Scope.thread, pp.scope(1));
    try std.testing.expectEqual(pp.Scope.process, pp.scope(2));
    try std.testing.expectEqual(pp.Scope.group, pp.scope(4));
    try std.testing.expectEqual(@as(i64, 0), pp.infoErrno(10, 10, -1, false, .process));
    try std.testing.expectEqual(@as(i64, -22), pp.infoErrno(10, 12, -1, false, .process));
    try std.testing.expectEqual(@as(i64, -1), pp.infoErrno(10, 10, 0, false, .process));
    try std.testing.expectEqual(@as(i64, -1), pp.infoErrno(10, 10, -6, false, .process));
    try std.testing.expectEqual(@as(i64, 0), pp.infoErrno(10, 10, 0, true, .process));
    try std.testing.expectEqual(@as(i64, -1), pp.infoErrno(10, 10, 0, true, .group));
    const se = kt.syscall_entry_source;
    const f = std.mem.indexOf(u8, se, "fn syscallPidfdSendSignal(").?;
    const f_end = std.mem.indexOf(u8, se[f..], "\n}\n").? + f;
    try std.testing.expect(std.mem.indexOf(u8, se[f..f_end], "_ = info_ptr;") == null);
    // hello460: the flags passed on are eff_flags (a PIDFD_THREAD descriptor defaults to the thread scope).
    try std.testing.expect(std.mem.indexOf(u8, se[f..f_end], "signal_syscall_mod.pidfdSendSignal(target_tid, sig, info_ptr, eff_flags)") != null);
}

test "madvise MADV_DONTFORK / MADV_DOFORK: a fork child does not get a DONTFORK mapping (hello438)" {
    // Linux madvise_behavior sets / clears VM_DONTCOPY; dup_mmap skips such a vma, so the child has no mapping there. Both
    // advice values used to be EINVAL.
    const rp = kt.range_policy;
    try std.testing.expect(rp.madviseSupported(10) and rp.madviseSupported(11));
    try std.testing.expect(!rp.madviseSupported(99));
    try std.testing.expectEqual(@as(?bool, true), rp.dontforkValue(10));
    try std.testing.expectEqual(@as(?bool, false), rp.dontforkValue(11));
    try std.testing.expectEqual(@as(?bool, null), rp.dontforkValue(4));
    const mp = kt.mremap_policy;
    const t: mp.Traits = .{ .prot = 3, .shared = false, .may_write = true, .file_kind = 0, .no_free = false, .locked = false, .huge_pages = 0 };
    var d = t;
    d.dontfork = true;
    try std.testing.expect(!mp.canCoalesce(t, d));
    const fk = kt.fork_source;
    try std.testing.expect(std.mem.indexOf(u8, fk, "@import(\"../mm/filemap.zig\").inDontforkRegion(@import(\"task.zig\").MmapRegion, regs, virt)") != null);
    try std.testing.expect(std.mem.indexOf(u8, fk, "@import(\"../mm/vma_table.zig\").dropDontfork(&vma_snap);") != null);
    const se = kt.syscall_entry_source;
    try std.testing.expect(std.mem.indexOf(u8, se, "mmap_mod_dontfork.setDontfork(cur, addr, length, v)") != null);
}

test "the zero-window probe timer starts from the connection's RTO and the initial RTO is 1 s (hello439)" {
    // Linux tcp_probe0_base = max(icsk_rto, TCP_RTO_MIN), doubled per unanswered probe; icsk_rto starts at TCP_TIMEOUT_INIT (1 s).
    // The persist timer used to start from a fixed 2 s, which was also the initial RTO.
    const rp = kt.tcp_recv_policy;
    try std.testing.expectEqual(@as(u32, 1000), rp.TIMEOUT_INIT_MS);
    try std.testing.expectEqual(@as(u32, 200), rp.probe0BaseMs(150));
    try std.testing.expectEqual(@as(u32, 230), rp.probe0BaseMs(230));
    try std.testing.expectEqual(@as(u32, 1000), rp.probe0BaseMs(0));
    const ts = kt.tcp_source;
    try std.testing.expect(std.mem.indexOf(u8, ts, "const RETRANSMIT_MS: u32 = tcp_recv_policy.TIMEOUT_INIT_MS;") != null);
    // The window reopening and the persist timer stopping both rearm the first probe from the RTO, not a fixed value.
    try std.testing.expectEqual(@as(usize, 3), std.mem.count(u8, ts, "tcb.persist_rto_ms = tcp_recv_policy.probe0BaseMs(tcb.rto);"));
    // ... and so does the start of a run of probes.
    try std.testing.expect(std.mem.indexOf(u8, ts, "if (starting) tcb.persist_rto_ms = tcp_recv_policy.probe0BaseMs(tcb.rto);") != null);
    // The pass that starts a run charges only 1 ms: a full timer pass made the first probe come up to 100 ms early (QEMU: 73 ms).
    try std.testing.expect(std.mem.indexOf(u8, ts, "const persist_charge: u32 = if (starting) 1 else ms_elapsed;") != null);
    // The handshake's RTT sample is the time since the SYN went out, not a count of ~100 ms timer passes: in QEMU the pass count
    // gave samples of 0 to 300 ms and a first probe anywhere from 200 to 520 ms.
    try std.testing.expectEqual(@as(u64, 3), rp.sentAgoMs(1_000_000_000, 1_003_500_000, 100));
    try std.testing.expectEqual(@as(u64, 100), rp.sentAgoMs(0, 1_003_500_000, 100));
    try std.testing.expect(std.mem.indexOf(u8, ts, "const waited = tcp_recv_policy.sentAgoMs(tcb.rtx_start_ns, @import(\"../arch/arch.zig\").tsc.nanos(), tcb.rtx_elapsed_ms);") != null);
    try std.testing.expect(kt.capability_profile.profileForLaunch("hello439", true, false).caps.cap_net_raw);
    try std.testing.expect(std.mem.indexOf(u8, ts, "tcb.persist_rto_ms > 0) tcb.persist_rto_ms else tcp_recv_policy.probe0BaseMs(tcb.rto)") != null);
}

test "rt_sigaction requires sigsetsize 8 before anything else (hello440)" {
    // Linux rt_sigaction: sigsetsize != sizeof(sigset_t) is EINVAL before the act copy and do_sigaction. The dispatcher used not
    // to pass the fourth argument at all, so every size was accepted; libc's sigaction did not pass it either.
    const ss = kt.signal_syscall_source;
    const f = std.mem.indexOf(u8, ss, "pub fn sigaction(signum: u32, act_ptr: u64, oldact_ptr: u64, sigsetsize: u64) i64 {").?;
    const body = ss[f..];
    const size_check = std.mem.indexOf(u8, body, "if (!action_policy.sigsetSizeValid(sigsetsize)) return -22;").?;
    const sig_check = std.mem.indexOf(u8, body, "if (signum == 0 or signum > 64) return -22;").?;
    try std.testing.expect(size_check < sig_check);
    try std.testing.expect(std.mem.indexOf(u8, kt.syscall_entry_source, "signal_syscall_mod.sigaction(@truncate(frame.rdi), frame.rsi, frame.rdx, frame.r10)") != null);
}

test "the tail loss probe waits 2 SRTT + TCP_RTO_MIN with one segment out, so one lost segment waits for the RTO (hello414 CI)" {
    // Linux tcp_schedule_loss_probe: timeout = 2 * srtt + (packets_out == 1 ? tcp_rto_min : TCP_TIMEOUT_MIN 2 ms), TCP_TIMEOUT_INIT
    // without a sample, then min(that, the RTO). With a real handshake RTT sample of ~1 ms the old max(2 * SRTT, 10 ms) fired the
    // probe at the first timer pass, ~100 ms after the data, before the 200 ms RTO (hello414 F: 142 ms in CI).
    const rp = kt.tcp_recv_policy;
    try std.testing.expectEqual(@as(u32, 200), rp.tlpTimeoutMs(1, 200, true)); // 2 + 200 capped by the RTO: no probe before it
    try std.testing.expectEqual(@as(u32, 4), rp.tlpTimeoutMs(1, 200, false)); // 2 + 2 with more segments out
    try std.testing.expectEqual(@as(u32, 200), rp.tlpTimeoutMs(0, 200, false)); // no sample: TCP_TIMEOUT_INIT, capped by the RTO
    try std.testing.expectEqual(@as(u32, 260), rp.tlpTimeoutMs(30, 1000, true));
    const ts = kt.tcp_source;
    try std.testing.expect(std.mem.indexOf(u8, ts, "const tlp_to = tcp_recv_policy.tlpTimeoutMs(tcb.srtt, current_rto, pipeBytes(tcb) <= mssForTcb(tcb));") != null);
}

test "F_SETPIPE_SZ resizes a pipe: rounded to a power-of-two of pages, EPERM past pipe-max-size, EBUSY below the queued bytes (hello441)" {
    // Linux fs/pipe.c round_pipe_size / pipe_set_size / pipe_resize_ring. The pipe used to be one fixed page (anything bigger ENOMEM).
    const fp = kt.fcntl_policy;
    try std.testing.expectEqual(@as(u64, 4096), fp.roundPipeSize(0).?);
    try std.testing.expectEqual(@as(u64, 4096), fp.roundPipeSize(1).?);
    try std.testing.expectEqual(@as(u64, 8192), fp.roundPipeSize(5000).?);
    try std.testing.expectEqual(@as(u64, 131072), fp.roundPipeSize(100000).?);
    try std.testing.expectEqual(@as(?u64, null), fp.roundPipeSize((1 << 31) + 1));
    try std.testing.expectEqual(@as(i64, 0), fp.setPipeSizeErrno(131072, 4096, 0, false));
    try std.testing.expectEqual(@as(i64, -1), fp.setPipeSizeErrno(2 << 20, 4096, 0, false)); // over pipe-max-size, unprivileged
    try std.testing.expectEqual(@as(i64, 0), fp.setPipeSizeErrno(2 << 20, 4096, 0, true));
    try std.testing.expectEqual(@as(i64, 0), fp.setPipeSizeErrno(2 << 20, 2 << 20, 0, false)); // not growing: allowed
    try std.testing.expectEqual(@as(i64, -16), fp.setPipeSizeErrno(4096, 131072, 60000, false)); // EBUSY
    try std.testing.expectEqual(@as(i64, 0), fp.setPipeSizeErrno(65536, 131072, 60000, false));
    // The kernel keeps at most 4 MiB of pipe buffer (CAP_SYS_RESOURCE may go past pipe-max-size, not past this).
    try std.testing.expectEqual(@as(i64, -12), fp.setPipeSizeErrno(8 << 20, 4096, 0, true));
    const v = kt.vfs_source;
    try std.testing.expect(std.mem.indexOf(u8, v, "pub fn pipeSetSize(") != null);
    try std.testing.expect(std.mem.indexOf(u8, v, "% PIPE_BUF_SIZE") == null); // every ring index uses the pipe's own capacity
}

test "signalfd: argument checks and the signalfd_siginfo layout (hello442)" {
    // Linux fs/signalfd.c: sizemask must be 8, flags only SFD_NONBLOCK / SFD_CLOEXEC, SIGKILL / SIGSTOP leave the mask; a read gets
    // 128-byte signalfd_siginfo records (signalfd_copyinfo). The kernel used to hand out a plain eventfd and ignore all three.
    const sp = kt.signalfd_policy;
    try std.testing.expectEqual(@as(i64, -22), sp.argsErrno(4, 0));
    try std.testing.expectEqual(@as(i64, -22), sp.argsErrno(8, 1));
    try std.testing.expectEqual(@as(i64, 0), sp.argsErrno(8, 0x800 | 0x80000));
    try std.testing.expectEqual(@as(u64, 0), sp.cleanMask((1 << 8) | (1 << 18)));
    try std.testing.expectEqual(@as(u64, 1 << 9), sp.cleanMask((1 << 9) | (1 << 8)));
    const si = kt.siginfo_policy;
    // SIGUSR1 from kill: SI_USER, pid and uid.
    const k = sp.encode(10, .{ .code = si.SI_USER, .a = si.pidUid(42, 1000) });
    try std.testing.expectEqual(@as(usize, 128), k.len);
    try std.testing.expectEqual(@as(u32, 10), std.mem.readInt(u32, k[0..4], .little));
    try std.testing.expectEqual(@as(u32, 42), std.mem.readInt(u32, k[12..16], .little));
    try std.testing.expectEqual(@as(u32, 1000), std.mem.readInt(u32, k[16..20], .little));
    // sigqueue: SI_QUEUE with the value in ssi_int (44) and ssi_ptr (48).
    const q = sp.encode(34, .{ .code = si.SI_QUEUE, .a = si.pidUid(7, 0), .b = 5 });
    try std.testing.expectEqual(@as(i32, -1), std.mem.readInt(i32, q[8..12], .little));
    try std.testing.expectEqual(@as(i32, 5), std.mem.readInt(i32, q[44..48], .little));
    try std.testing.expectEqual(@as(u64, 5), std.mem.readInt(u64, q[48..56], .little));
    try std.testing.expect(std.mem.indexOf(u8, kt.vfs_source, "    signalfd = 24,") != null);
    try std.testing.expect(std.mem.indexOf(u8, kt.signal_syscall_source, "eventfdCreate(0, false)") == null);
}

test "TCP urgent data: the mark, recv(MSG_OOB), POLLPRI and exceptfds (hello443)" {
    // Linux tcp_check_urg / tcp_urg keep the urgent byte at urg_seq; tcp_recvmsg_locked stops in front of it and skips it,
    // tcp_recv_urg returns it once, tcp_poll adds EPOLLPRI, select maps that to exceptfds. The kernel used to ignore MSG_OOB on
    // send, write a zero urgent pointer and always clear exceptfds.
    const u = kt.tcp_urg_policy;
    try std.testing.expectEqual(@as(u32, 1002), u.pointerSeq(1000, 3));
    try std.testing.expectEqual(u.Check.new_mark, u.check(1002, 1000, 1000, .none, 0, false));
    try std.testing.expectEqual(u.Limit{ .skip = 0, .avail = 2 }, u.readLimit(.valid, 1002, 1000, 3, false));
    try std.testing.expectEqual(u.Limit{ .skip = 1, .avail = 2 }, u.readLimit(.read, 1002, 1002, 3, false));
    try std.testing.expectEqual(@as(u32, 2), u.inq(.valid, 1002, 1000, 5, false));
    try std.testing.expectEqual(u.Oob{ .byte = 'c' }, u.recvOob(.valid, 'c', false, false, false));
    try std.testing.expectEqual(u.Oob{ .err = -22 }, u.recvOob(.read, 'c', false, false, false));
    try std.testing.expectEqual(@as(?u16, 3), u.sendPointer(true, 1000, 1003, 1000));
    const rp = kt.tcp_ready_policy;
    const ev = rp.events(.{ .active = true, .state = .established, .recv_bytes = 2, .send_space = 1, .reset_by_peer = false, .shut_rd = false, .fin_pending = false, .urgent = true });
    try std.testing.expect(ev & rp.PRI != 0 and ev & rp.IN != 0);
    try std.testing.expect(kt.poll_policy.selectExceptional(kt.poll_policy.POLLPRI));
    try std.testing.expect(!kt.poll_policy.selectExceptional(kt.poll_policy.POLLIN));
    try std.testing.expect(std.mem.indexOf(u8, kt.select_source, "&zero, SET_BYTES") == null);
    try std.testing.expect(std.mem.indexOf(u8, kt.tcp_source, "pkt[tcp_off + 18] = 0;") == null);
    try std.testing.expect(std.mem.indexOf(u8, kt.ioctl_source, "SIOCATMARK => {") != null);
    try std.testing.expect(std.mem.indexOf(u8, kt.socket_syscall_source, "tcpSendOobBlocking(") != null);
}

test "receive timestamps and the original destination as control messages (hello444)" {
    // Linux __sock_set_timestamps: SO_TIMESTAMP / SO_TIMESTAMPNS replace each other; __sock_recv_timestamp puts the stamp first;
    // ip_cmsg_recv_dstaddr writes a sockaddr_in. The kernel used to answer ENOPROTOOPT for all four options.
    const sp = kt.sockopt_policy;
    var st: sp.Stored = .{};
    try std.testing.expectEqual(@as(i64, 0), sp.applySet(&st, sp.SO_TIMESTAMP, &.{ 1, 0, 0, 0 }));
    try std.testing.expectEqual(@as(u32, 1), sp.timestampValue(st.flags, sp.SO_TIMESTAMP));
    try std.testing.expectEqual(@as(i64, 0), sp.applySet(&st, sp.SO_TIMESTAMPNS, &.{ 1, 0, 0, 0 }));
    try std.testing.expectEqual(@as(u32, 0), sp.timestampValue(st.flags, sp.SO_TIMESTAMP));
    try std.testing.expectEqual(@as(u32, 1), sp.timestampValue(st.flags, sp.SO_TIMESTAMPNS));
    try std.testing.expectEqual(@as(i64, -22), sp.applySet(&st, sp.SO_TIMESTAMP, &.{ 1, 0 }));
    const ipo = kt.ip_opt_policy;
    const set = ipo.applySet(.{}, ipo.SOL_IP, ipo.IP_RECVORIGDSTADDR, &.{ 1, 0, 0, 0 });
    try std.testing.expect(set == .ok and set.ok.origdst);
    try std.testing.expectEqual(@as(?i32, 1), ipo.getValue(set.ok, ipo.SOL_IP, ipo.IP_RECVORIGDSTADDR));
    const cm = kt.ip_cmsg_policy;
    var out: [192]u8 = undefined;
    const w = cm.Wanted.of(set.ok).withStamp(st.flags);
    const b = cm.build(w, .{ .dst = .{ 127, 0, 0, 1 }, .dst_port = 47441, .stamp_ns = 5_000_000_123 }, 256, &out);
    try std.testing.expectEqual(@as(usize, 64), b.written);
    try std.testing.expectEqual(@as(i32, 35), std.mem.readInt(i32, out[12..16], .little));
    try std.testing.expectEqual(@as(i64, 5), std.mem.readInt(i64, out[16..24], .little));
    try std.testing.expectEqual(@as(i64, 123), std.mem.readInt(i64, out[24..32], .little));
    try std.testing.expectEqual(@as(i32, 20), std.mem.readInt(i32, out[44..48], .little));
    try std.testing.expectEqual(@as(u16, 47441), std.mem.readInt(u16, out[50..52], .big));
    const cut = cm.build(w, .{ .stamp_ns = 1 }, 20, &out);
    try std.testing.expect(cut.truncated and cut.written == 20);
}

test "IP_RECVERR: ICMP errors are queued for recvmsg(MSG_ERRQUEUE) (hello445)" {
    // Linux __udp4_lib_err queues every ICMP error for a socket with IP_RECVERR (ip_icmp_error), connected or not, and sets sk_err;
    // ip_recv_error hands out struct sock_extended_err + the offender. The kernel used to refuse IP_RECVERR and keep no queue.
    const eq = kt.errqueue_policy;
    try std.testing.expect(eq.route(true, false, false).queue and eq.route(true, false, false).set_err);
    try std.testing.expect(!eq.route(false, true, false).set_err);
    var off: [16]u8 = @splat(0);
    off[0] = 127;
    off[3] = 1;
    const ext = eq.encodeExtErr(.{ .errno = 111, .icmp_type = 3, .icmp_code = 3, .offender = off });
    try std.testing.expectEqual(@as(u8, eq.SO_EE_ORIGIN_ICMP), ext.bytes[4]);
    const ipo = kt.ip_opt_policy;
    const set = ipo.applySet(.{}, ipo.SOL_IP, ipo.IP_RECVERR, &.{ 1, 0, 0, 0 });
    try std.testing.expect(set == .ok and set.ok.recverr);
    try std.testing.expectEqual(@as(?i32, 1), ipo.getValue(set.ok, ipo.SOL_IP, ipo.IP_RECVERR));
    const iu = kt.icmp_unreach_policy;
    try std.testing.expect(!iu.errorFor(11, 0).?.hard); // time exceeded: soft, queued only with IP_RECVERR
    try std.testing.expect(iu.errorFor(3, 3).?.hard);
    try std.testing.expect(iu.errorFor(4, 0) == null);
    var out: [64]u8 = undefined;
    const b = kt.ip_cmsg_policy.buildRecvErr(ext.bytes[0..ext.len], false, 256, &out);
    try std.testing.expectEqual(@as(usize, 48), b.written);
    try std.testing.expect(std.mem.indexOf(u8, kt.icmp_source, "notifyIcmpError(.{") != null);
    try std.testing.expect(std.mem.indexOf(u8, kt.epoll_source, "udp_mod.hasQueuedError(") != null);
}

test "signalfd in epoll: readiness from the waiter's pending signals and a wake on arrival (hello446)" {
    // Linux signalfd_poll reads current's pending set and a signal wakes the sighand wait queue an epoll waiter sits on. The kernel
    // used to give epoll no signalfd readiness at all (computeCurrentEvents' `.signalfd => {}`), so epoll_wait slept until its timeout.
    const es = kt.epoll_source;
    try std.testing.expect(std.mem.indexOf(u8, es, "if (it.fd_type == .signalfd and !it.is_disabled and !it.on_ready and it.sigmask & pending_sigs != 0) addToReadyListLocked(inst, i);") != null);
    try std.testing.expect(std.mem.indexOf(u8, es, "@atomicStore(u64, &ct.sigwait_mask, sigwait, .seq_cst);") != null);
    try std.testing.expect(std.mem.indexOf(u8, es, ".sigmask = if (desc.fd_type == .signalfd) desc.file_data else 0,") != null);
    // kickIfBlocked wakes a blocked task for a signal in its sigwait_mask even though it blocks it.
    try std.testing.expect(kt.signal_action_policy.wakesSigwaiter(1 << 9, 1 << 9));
}

test "madvise MADV_WIPEONFORK / MADV_KEEPONFORK: a fork child gets the private anonymous range empty (hello447)" {
    // Linux VM_WIPEONFORK: dup_mmap copies the vma without its pages; madvise_vma_behavior refuses a shared or file vma. The kernel
    // used to reject both advice values with EINVAL.
    const rp = kt.range_policy;
    try std.testing.expect(rp.madviseSupported(18) and rp.madviseSupported(19));
    try std.testing.expectEqual(@as(?bool, true), rp.wipeonforkValue(18));
    try std.testing.expectEqual(@as(?bool, false), rp.wipeonforkValue(19));
    try std.testing.expectEqual(@as(?bool, null), rp.wipeonforkValue(10));
    const mp = kt.mremap_policy;
    const t: mp.Traits = .{ .prot = 3, .shared = false, .may_write = true, .file_kind = 0, .no_free = false, .locked = false, .huge_pages = 0 };
    var w = t;
    w.wipeonfork = true;
    try std.testing.expect(!mp.canCoalesce(t, w));
    const se = kt.syscall_entry_source;
    try std.testing.expect(std.mem.indexOf(u8, se, "if (v and !mmap_mod_wipe.rangePrivateAnon(cur, addr, length)) return -22;") != null);
    try std.testing.expect(std.mem.indexOf(u8, kt.filemap_source, "if (!r.active or !(r.fork.dontfork or r.fork.wipeonfork)) continue;") != null);
}

test "MADV_WIPEONFORK: fork gives the child fresh zero pages for the marked range (hello447 B)" {
    // Anonymous mappings are populated eagerly and have no demand-fill path: a wiped page left empty faulted to SIGSEGV in the child
    // (first QEMU run of hello447). fillWipedPages maps a zeroed frame per present parent page instead.
    const fk = kt.fork_source;
    try std.testing.expect(std.mem.indexOf(u8, fk, "if (!fillWipedPages(parent.page_table_phys, pml4, parent.vma().regions, marks)) {") != null);
    try std.testing.expect(std.mem.indexOf(u8, fk, "paging_mod.setPageEntryRaw(child_pml4_phys, va, phys | flags);") != null);
}

test "clone without CLONE_VM honours MADV_DONTFORK and MADV_WIPEONFORK like fork (hello447 E)" {
    // clone(SIGCHLD) copies the address space through arch/x86_64/clone.zig's own page-table walk, which used to copy every page
    // and keep every region, so DONTFORK / WIPEONFORK only worked for fork().
    const cs = kt.clone_source;
    try std.testing.expect(std.mem.indexOf(u8, cs, "if (@import(\"../../proc/fork.zig\").pageSkippedByFork(shared_regions, marks, virt)) continue;") != null);
    try std.testing.expect(std.mem.indexOf(u8, cs, "@import(\"../../proc/fork.zig\").fillWipedPages(parent.page_table_phys, pml4, parent.vma().regions, marks)") != null);
    try std.testing.expect(std.mem.indexOf(u8, cs, "@import(\"../../mm/vma_table.zig\").dropDontfork(&vma_snap);") != null);
}

test "clone takes SIGCHLD (or 0) as its exit signal, so clone(SIGCHLD) is fork (hello447 E)" {
    // Linux CSIGNAL: the low byte of the flags is the signal the parent gets at exit. clone(SIGCHLD) was EINVAL (17 is outside the
    // implemented flag set), so a runtime calling clone instead of fork failed. hello450 adds the other exit signals (and __WCLONE).
    const cfp = kt.clone_flags_policy;
    try std.testing.expect(cfp.valid(cfp.SIGCHLD, true));
    try std.testing.expect(cfp.valid(0, true));
    try std.testing.expect(cfp.valid(10, true));
    try std.testing.expect(!cfp.valid(65, true));
    try std.testing.expect(cfp.valid(cfp.CLONE_VM | cfp.CLONE_FS | cfp.CLONE_FILES | cfp.CLONE_SIGHAND | cfp.CLONE_THREAD | cfp.CLONE_SETTLS | cfp.CLONE_CHILD_CLEARTID, true));
}

test "a new pipe gets a 16-page ring like Linux (hello448)" {
    // Linux fs/pipe.c alloc_pipe_info: PIPE_DEF_BUFFERS (16) pages, F_GETPIPE_SZ 65536. The kernel gave every pipe one page.
    const v = kt.vfs_source;
    try std.testing.expect(std.mem.indexOf(u8, v, "pub const PIPE_DEFAULT_SIZE: u32 = 16 * 4096;") != null);
    try std.testing.expect(std.mem.indexOf(u8, v, "const wanted = @import(\"fcntl_policy.zig\").newPipeSize(PIPE_DEFAULT_SIZE, creator.cap_sys_resource);") != null);
    try std.testing.expect(std.mem.indexOf(u8, v, "pmm.allocContiguous(size / 4096)") != null);
    try std.testing.expect(std.mem.indexOf(u8, v, "pipes[i].cap = size;") != null);
    // F_SETPIPE_SZ still goes down to one page.
    try std.testing.expectEqual(@as(u64, 4096), kt.fcntl_policy.roundPipeSize(1).?);
}

test "ping sockets with IP_RECVERR queue ICMP errors, soft ones and source quench included (hello390 W)" {
    // Linux ping_err: with IP_RECVERR ip_icmp_error queues every error, connected or not; source quench and redirect are a soft
    // EREMOTEIO there. Without it only a hard error on a connected socket is taken (as before).
    const iu = kt.icmp_unreach_policy;
    try std.testing.expectEqual(@as(i32, 121), iu.pingErrorFor(4, 0).errno);
    try std.testing.expect(!iu.pingErrorFor(5, 1).hard);
    try std.testing.expectEqual(@as(i32, 113), iu.pingErrorFor(3, 1).errno);
    try std.testing.expect(!iu.pingErrorFor(3, 1).hard);
    try std.testing.expect(iu.pingErrorFor(3, 3).hard);
    const us = kt.udp_source;
    try std.testing.expect(std.mem.indexOf(u8, us, "pub fn notifyPingIcmpError(ident: u16, e: IcmpError, queue: bool) void {") != null);
    try std.testing.expect(std.mem.indexOf(u8, kt.icmp_source, "@import(\"udp.zig\").notifyPingIcmpError(q.src_port, .{") != null);
}

test "IPv6 ping sockets with IPV6_RECVERR queue ICMPv6 errors (hello392 W)" {
    // Linux ping_err → ipv6_icmp_error: queued with IPV6_RECVERR, soft ones too; packet too big is soft for ping, an unknown type a
    // soft EPROTO (icmpv6_err_convert).
    const iu = kt.icmp_unreach_policy;
    try std.testing.expect(!iu.pingErrorFor6(2, 0).hard);
    try std.testing.expectEqual(@as(i32, 90), iu.pingErrorFor6(2, 0).errno);
    try std.testing.expect(!iu.pingErrorFor6(1, 3).hard);
    try std.testing.expect(iu.pingErrorFor6(1, 4).hard);
    try std.testing.expectEqual(@as(i32, 71), iu.pingErrorFor6(100, 0).errno);
    try std.testing.expect(!iu.pingErrorFor6(100, 0).hard);
}

test "an oversized UDP datagram is EMSGSIZE, never a cut copy, and a local IP_RECVERR entry under DO (hello449)" {
    // Linux __ip_append_data refuses a datagram over the MTU when it may not fragment and ip_local_error queues SO_EE_ORIGIN_LOCAL with
    // ee_info = MTU. This stack never fragments: the send path used to copy the first 1472 bytes and send those.
    const eq = kt.errqueue_policy;
    try std.testing.expect(eq.oversize(1472, 1500, 1, false) == null);
    // hello452: over the MTU, WANT / DONT / OMIT fragment; DO / PROBE refuse; 65508 is always too long.
    try std.testing.expect(eq.oversize(1473, 1500, 1, false) == null);
    try std.testing.expect(eq.oversize(1473, 1500, 0, false) == null);
    try std.testing.expect(eq.oversize(1473, 1500, 5, false) == null);
    try std.testing.expect(eq.oversize(1473, 1500, 2, false) != null);
    try std.testing.expect(eq.oversize(1473, 1500, 3, false) != null);
    try std.testing.expect(eq.oversize(65507, 1500, 1, false) == null);
    try std.testing.expect(eq.oversize(65508, 1500, 1, false) != null);
    try std.testing.expect(eq.oversize(1600, 1500, 2, true).?.queue);
    const ss = kt.socket_syscall_source;
    try std.testing.expect(std.mem.indexOf(u8, ss, "if (udpOversize4(src_key, dst_ip, dst_port, len)) |e| return e;") != null);
    try std.testing.expect(std.mem.indexOf(u8, ss, "if (udpOversize4(src_key, dst_ip, dst_port, full_len)) |e| return e;") != null);
    try std.testing.expect(std.mem.indexOf(u8, ss, "const n = @min(payload.len, 1472);") == null);
}

test "IPv6 UDP: IPV6_MTU_DISCOVER, 1452-byte datagrams and a local IPV6_RECVERR EMSGSIZE (hello449 E)" {
    // Linux __ip6_append_data / ipv6_local_error; the kernel cut IPv6 datagrams to 1232 bytes and had no IPV6_MTU_DISCOVER.
    const ipo = kt.ip_opt_policy;
    const set = ipo.applySet(.{}, ipo.SOL_IPV6, ipo.IPV6_MTU_DISCOVER, &.{ 2, 0, 0, 0 });
    try std.testing.expect(set == .ok and set.ok.pmtudisc6 == 2);
    try std.testing.expectEqual(@as(?i32, 1), ipo.getValue(.{}, ipo.SOL_IPV6, ipo.IPV6_MTU_DISCOVER));
    try std.testing.expect(ipo.applySet(.{}, ipo.SOL_IPV6, ipo.IPV6_MTU_DISCOVER, &.{ 6, 0, 0, 0 }) == .err);
    const eq = kt.errqueue_policy;
    try std.testing.expect(eq.oversize6(1452, 1500, 1, false) == null);
    // hello453: WANT fragments an IPv6 datagram too; 65528 is always too long.
    try std.testing.expect(eq.oversize6(1453, 1500, 1, false) == null);
    try std.testing.expect(eq.oversize6(65527, 1500, 0, false) == null);
    try std.testing.expect(eq.oversize6(65528, 1500, 1, false) != null);
    try std.testing.expect(eq.oversize6(1453, 1500, 2, true).?.queue);
    const b = eq.encodeExtErr(eq.localEntry6(90, 1500, @splat(0), 1));
    try std.testing.expectEqual(@as(usize, 44), b.len);
    try std.testing.expectEqual(@as(u8, eq.SO_EE_ORIGIN_LOCAL), b.bytes[4]);
    try std.testing.expect(std.mem.indexOf(u8, kt.udp_source, "const MAX_UDP_PAYLOAD_V6 = 1452;") != null);
}

