test "SOL_IP / SOL_IPV6 options the stack only stores, and the fixed answers of the rest (hello487)" {
    const p = kt.ip_opt_policy;
    const none: p.IpOpts = .{};
    // RFC 2292 switches and the other stored booleans: any nonzero int sets, a short optlen is EINVAL (IPV6_RECVFRAGSIZE takes any).
    const s1 = p.applyExtra(none, p.SOL_IPV6, p.IPV6_2292PKTINFO, 255, 4, false).?.ok;
    try std.testing.expectEqual(@as(i32, 1), p.getExtra(s1, p.SOL_IPV6, p.IPV6_2292PKTINFO).?.val);
    try std.testing.expectEqual(@as(i64, -22), p.applyExtra(none, p.SOL_IPV6, p.IPV6_RECVHOPOPTS, 1, 1, false).?.err);
    _ = p.applyExtra(none, p.SOL_IPV6, p.IPV6_RECVFRAGSIZE, 1, 1, false).?.ok;
    // IPV6_RECVERR_RFC4884 and IP_RECVERR_RFC4884: 0 or 1 only. IPV6_MINHOPCOUNT and IP_MINTTL: 0..255.
    try std.testing.expectEqual(@as(i64, -22), p.applyExtra(none, p.SOL_IPV6, p.IPV6_RECVERR_RFC4884, 255, 4, false).?.err);
    try std.testing.expectEqual(@as(i64, -22), p.applyExtra(none, p.SOL_IP, p.IP_RECVERR_RFC4884, 2, 4, false).?.err);
    try std.testing.expectEqual(@as(i64, -22), p.applyExtra(none, p.SOL_IPV6, p.IPV6_MINHOPCOUNT, 256, 4, false).?.err);
    try std.testing.expectEqual(@as(i32, 255), p.getExtra(p.applyExtra(none, p.SOL_IP, p.IP_MINTTL, 255, 4, false).?.ok, p.SOL_IP, p.IP_MINTTL).?.val);
    // IPV6_ADDR_PREFERENCES: default PUBTMP_DEFAULT | HOME (0x500); TMP gives 0x401; PUBLIC | TMP is EINVAL.
    try std.testing.expectEqual(@as(i32, 0x500), p.getExtra(none, p.SOL_IPV6, p.IPV6_ADDR_PREFERENCES).?.val);
    try std.testing.expectEqual(@as(i32, 0x401), p.getExtra(p.applyExtra(none, p.SOL_IPV6, p.IPV6_ADDR_PREFERENCES, 1, 4, false).?.ok, p.SOL_IPV6, p.IPV6_ADDR_PREFERENCES).?.val);
    try std.testing.expectEqual(@as(i64, -22), p.applyExtra(none, p.SOL_IPV6, p.IPV6_ADDR_PREFERENCES, 3, 4, false).?.err);
    // IP_LOCAL_PORT_RANGE: exactly 4 bytes, lo <= hi unless one is 0; reads back as set (-1 is lo = hi = 65535).
    try std.testing.expectEqual(@as(i32, -1), p.getExtra(p.applyExtra(none, p.SOL_IP, p.IP_LOCAL_PORT_RANGE, -1, 4, false).?.ok, p.SOL_IP, p.IP_LOCAL_PORT_RANGE).?.val);
    try std.testing.expectEqual(@as(i64, -22), p.applyExtra(none, p.SOL_IP, p.IP_LOCAL_PORT_RANGE, 0x0001_0002, 4, false).?.err);
    // Fixed answers: unconnected IPV6_MTU / IP_MTU / IPV6_ADDRFORM read ENOTCONN; no unicast interface 99 (EADDRNOTAVAIL);
    // IP_TRANSPARENT without CAP_NET_ADMIN EPERM; the sticky header options read with length 0.
    try std.testing.expectEqual(@as(i64, -107), p.getExtra(none, p.SOL_IPV6, p.IPV6_MTU).?.err);
    try std.testing.expectEqual(@as(i64, -107), p.getExtra(none, p.SOL_IP, p.IP_MTU).?.err);
    try std.testing.expectEqual(@as(i64, -99), p.applyExtra(none, p.SOL_IPV6, p.IPV6_UNICAST_IF, 1, 4, false).?.err);
    try std.testing.expectEqual(@as(i64, -1), p.applyExtra(none, p.SOL_IP, p.IP_TRANSPARENT, 1, 4, false).?.err);
    try std.testing.expectEqual(@as(i32, -1), p.getExtra(none, p.SOL_IPV6, p.IPV6_HOPOPTS).?.val);
    // An option applyExtra does not own is left to applySet.
    try std.testing.expect(p.applyExtra(none, p.SOL_IP, p.IP_TTL, 5, 4, false) == null);
    // A datagram socket keeps the ECN bits of IP_TOS / IPV6_TCLASS; applySet alone (a stream socket) drops them.
    const tos = p.keepEcnForDatagram(p.applySet(none, p.SOL_IP, p.IP_TOS, &[_]u8{ 0x13, 0, 0, 0 }), p.SOL_IP, p.IP_TOS, 0x13).ok;
    try std.testing.expectEqual(@as(u8, 0x13), tos.tos);
    try std.testing.expectEqual(@as(u8, 0x10), p.applySet(none, p.SOL_IP, p.IP_TOS, &[_]u8{ 0x13, 0, 0, 0 }).ok.tos);
    const tc = p.keepEcnForDatagram(p.applySet(none, p.SOL_IPV6, p.IPV6_TCLASS, &[_]u8{ 1, 0, 0, 0 }), p.SOL_IPV6, p.IPV6_TCLASS, 1).ok;
    try std.testing.expectEqual(@as(u8, 1), tc.tclass);
    try std.testing.expect(std.mem.indexOf(u8, kt.socket_opt_source, "if (ipo.applyExtraFor(cur, level, optname, v, val.len, admin, net_raw, raw)) |r| return r;") != null);
    // TCP (hello487 C, D): IP_RECVFRAGSIZE is EINVAL; G covers IPV6_2292PKTOPTIONS with every receive-switch combination.
    try std.testing.expect(std.mem.indexOf(u8, kt.socket_opt_source, "if (optname == ipo.IP_RECVFRAGSIZE) return -22;") != null);
    // Raw sockets (hello487 E, F): IP_ROUTER_ALERT on, on again EADDRINUSE, off, off again ENOBUFS (ip_ra_control); IP_NODEFRAG
    // stored; with CAP_NET_RAW the sticky header options fail the header check (EINVAL), without it EPERM.
    const ra = p.applyExtraFor(none, p.SOL_IP, p.IP_ROUTER_ALERT, 1, 4, false, true, true).?.ok;
    try std.testing.expectEqual(@as(i32, 1), p.getExtra(ra, p.SOL_IP, p.IP_ROUTER_ALERT).?.val);
    try std.testing.expectEqual(@as(i64, -98), p.applyExtraFor(ra, p.SOL_IP, p.IP_ROUTER_ALERT, 255, 4, false, true, true).?.err);
    const ra_off = p.applyExtraFor(ra, p.SOL_IP, p.IP_ROUTER_ALERT, 0, 4, false, true, true).?.ok;
    try std.testing.expectEqual(@as(i64, -105), p.applyExtraFor(ra_off, p.SOL_IP, p.IP_ROUTER_ALERT, 0, 4, false, true, true).?.err);
    try std.testing.expectEqual(@as(i64, -22), p.applyExtraFor(none, p.SOL_IP, p.IP_ROUTER_ALERT, 1, 4, false, true, false).?.err);
    try std.testing.expectEqual(@as(i64, -22), p.applyExtraCaps(none, p.SOL_IPV6, p.IPV6_HOPOPTS, 1, 4, true, true).?.err);
    try std.testing.expectEqual(@as(i64, -1), p.applyExtraCaps(none, p.SOL_IPV6, p.IPV6_HOPOPTS, 1, 4, false, false).?.err);
    try std.testing.expectEqual(@as(i32, 1), p.getExtra(p.applyExtraCaps(none, p.SOL_IP, p.IP_TRANSPARENT, 1, 4, true, true).?.ok, p.SOL_IPV6, p.IPV6_TRANSPARENT).?.val);
}

test "TCP IPV6_2292PKTOPTIONS emits the six receive control messages with put_cmsg truncation (hello487 G)" {
    const p = kt.ip_opt_policy;
    const c = kt.ip_cmsg_policy;
    const o: p.IpOpts = .{
        .pktinfo6 = true,
        .recvhops6 = true,
        .recvtclass6 = true,
        .rxflow6 = true,
        .flags6 = p.F6_2292PKTINFO | p.F6_2292HOPLIMIT,
        .mc_hops = 37,
        .mc_if = 1,
    };
    var out: [176]u8 = @splat(0xa5);
    const b = c.buildPktOptions6(o, 0x0ab1_2345, out.len, &out);
    try std.testing.expectEqual(@as(usize, 176), b.written);
    const offsets = [_]usize{ 0, 40, 64, 88, 128, 152 };
    const types = [_]i32{ 50, 52, 67, 2, 8, 11 };
    const lens = [_]u64{ 36, 20, 20, 36, 20, 20 };
    const spaces = [_]usize{ 40, 24, 24, 40, 24, 24 };
    for (offsets, types, lens, spaces) |off, typ, len, space| {
        try std.testing.expectEqual(len, std.mem.readInt(u64, out[off..][0..8], .little));
        try std.testing.expectEqual(@as(i32, 41), std.mem.readInt(i32, out[off + 8 ..][0..4], .little));
        try std.testing.expectEqual(typ, std.mem.readInt(i32, out[off + 12 ..][0..4], .little));
        try std.testing.expectEqualSlices(u8, &([_]u8{0} ** 4), out[off + len .. off + space]);
    }
    try std.testing.expectEqual(@as(i32, 1), std.mem.readInt(i32, out[32..36], .little));
    try std.testing.expectEqual(@as(i32, 1), std.mem.readInt(i32, out[120..124], .little));
    try std.testing.expectEqual(@as(i32, 37), std.mem.readInt(i32, out[56..60], .little));
    try std.testing.expectEqual(@as(i32, 37), std.mem.readInt(i32, out[144..148], .little));
    try std.testing.expectEqual(@as(i32, 0xab), std.mem.readInt(i32, out[80..84], .little));
    try std.testing.expectEqual(@as(u32, 0x0ab1_2345), std.mem.readInt(u32, out[168..172], .big));
    try std.testing.expectEqual(@as(usize, 0), c.buildPktOptions6(.{}, 0, out.len, &out).written);

    var short: [40]u8 = @splat(0xa5);
    const just_info: p.IpOpts = .{ .pktinfo6 = true };
    try std.testing.expectEqual(@as(usize, 0), c.buildPktOptions6(just_info, 0, 15, &short).written);
    const cut = c.buildPktOptions6(just_info, 0, 17, &short);
    try std.testing.expectEqual(@as(usize, 17), cut.written);
    try std.testing.expect(cut.truncated);
    try std.testing.expectEqual(@as(u64, 17), std.mem.readInt(u64, short[0..8], .little));
    try std.testing.expectEqual(@as(u8, 0), short[16]);
    try std.testing.expectEqual(@as(u8, 0xa5), short[17]);
}

